     8	// FileChange represents a single file change from git status --porcelain.
     9	type FileChange struct {
    10		Status string // Two-character status (e.g., "M ", " M", "??", "R ")
    11		Path   string
    12		// For renames: original path
    13		OldPath string
    14	}
