    56	// StatusPorcelainIn returns parsed file changes for a specific directory.
    57	// Uses -uall to list individual files inside untracked directories,
    58	// rather than collapsing them into a single directory entry.
    59	func StatusPorcelainIn(dir string) ([]FileChange, error) {
    60		out, err := runRawIn(dir, "status", "--porcelain", "-uall")
    61		if err != nil {
    62			return nil, err
    63		}
    64		return ParsePorcelainOutput(out), nil
    65	}
    66	
    67	// ParsePorcelainOutput parses the output of `git status --porcelain` into FileChanges.
    68	func ParsePorcelainOutput(out string) []FileChange {
    69		if strings.TrimSpace(out) == "" {
    70			return nil
    71		}
    72	
    73		var changes []FileChange
    74		for line := range strings.SplitSeq(out, "\n") {
    75			if len(line) < 3 {
    76				continue
    77			}
    78			status := line[:2]
    79			path := line[3:]
    80	
    81			fc := FileChange{Status: status}
    82	
    83			// Handle renames: "R  old -> new"
    84			if strings.HasPrefix(status, "R") && strings.Contains(path, " -> ") {
    85				parts := strings.SplitN(path, " -> ", 2)
    86				fc.OldPath = parts[0]
    87				fc.Path = parts[1]
    88			} else {
    89				fc.Path = path
    90			}
    91	
    92			changes = append(changes, fc)
    93		}
    94	
    95		return changes
    96	}
