   100		out, err := RunIn(dir, "rev-list", "--count", "@{upstream}..HEAD")
   101		if err != nil {
   102			return 0
   103		}
   104		n, _ := strconv.Atoi(strings.TrimSpace(out))
   105		return n
   106	}
