     9	
    10	// LogEntry is one commit summary used by the dashboard detail panel.
    11	type LogEntry struct {
    12		Hash    string // short
    13		Subject string
    14		Age     string // already shortened, e.g. "2h"
    15	}
    16	
    17	// LogOnelineIn returns up to n commits reachable from HEAD but not from base,
    18	// most recent first. Returns nil (not error) if the range is empty.
    19	func LogOnelineIn(dir, base string, n int) ([]LogEntry, error) {
    20		if n <= 0 {
    21			return nil, nil
    22		}
    23		out, err := RunIn(dir, "log",
    24			fmt.Sprintf("-%d", n),
    25			"--format=%h\t%s\t%ct",
    26			base+"..HEAD",
    27		)
    28		if err != nil {
    29			return nil, err
    30		}
    31		if out == "" {
    32			return nil, nil
    33		}
    34		lines := strings.Split(out, "\n")
    35		entries := make([]LogEntry, 0, len(lines))
    36		for _, line := range lines {
    37			parts := strings.SplitN(line, "\t", 3)
    38			if len(parts) < 3 {
    39				continue
    40			}
    41			age := ""
    42			if ts, err := strconv.ParseInt(parts[2], 10, 64); err == nil {
    43				age = formatRelativeAge(time.Since(time.Unix(ts, 0)))
    44			}
    45			entries = append(entries, LogEntry{
    46				Hash:    parts[0],
    47				Subject: parts[1],
    48				Age:     age,
    49			})
    50		}
    51		return entries, nil
    52	}
    53	
    54	// DiffStats summarises a diff between base and HEAD.
    55	type DiffStats struct {
    56		Commits   int
    57		Files     int
    58		Additions int
    59		Deletions int
    60	}
    61	
    62	// DiffStatsIn returns commits-ahead and shortstat (files/additions/deletions)
    63	// for HEAD vs base. Empty range yields zeroed struct, not an error.
    64	func DiffStatsIn(dir, base string) (DiffStats, error) {
    65		stats := DiffStats{}
    66	
    67		commitsStr, err := RunIn(dir, "rev-list", "--count", base+"..HEAD")
    68		if err != nil {
    69			return stats, err
    70		}
    71		stats.Commits, _ = strconv.Atoi(strings.TrimSpace(commitsStr))
    72	
    73		if stats.Commits == 0 {
    74			return stats, nil
    75		}
    76	
    77		// `git diff --shortstat` output: " 14 files changed, 247 insertions(+), 82 deletions(-)"
    78		shortstat, err := RunIn(dir, "diff", "--shortstat", base+"..HEAD")
    79		if err != nil {
    80			return stats, err
    81		}
    82		stats.Files, stats.Additions, stats.Deletions = parseShortstat(shortstat)
    83		return stats, nil
    84	}
    85	
    86	func parseShortstat(s string) (files, adds, dels int) {
    87		for part := range strings.SplitSeq(s, ",") {
    88			part = strings.TrimSpace(part)
    89			fields := strings.Fields(part)
    90			if len(fields) < 2 {
    91				continue
    92			}
    93			n, err := strconv.Atoi(fields[0])
    94			if err != nil {
    95				continue
    96			}
    97			switch {
    98			case strings.HasPrefix(fields[1], "file"):
    99				files = n
   100			case strings.HasPrefix(fields[1], "insertion"):
   101				adds = n
   102			case strings.HasPrefix(fields[1], "deletion"):
   103				dels = n
   104			}
   105		}
   106		return
   107	}
   108	
   109	// DiffFile is one entry from `git diff --name-status`.
