   159		d.Email = parts[2]
   160		d.Date = parts[3]
   161		d.Subject = parts[4]
   162		d.Body = strings.TrimSpace(parts[5])
   163	
   164		// Per-file changes via numstat.
   165		numOut, err := RunIn(dir, "show", "--numstat", "--format=", hash)
   166		if err != nil {
