   217			// and a second path; we only surface the first letter and the destination path.
   218			status := string(fields[0][0])
   219			path := fields[len(fields)-1]
   220			changes = append(changes, DiffFile{Status: status, Path: path})
   221		}
   222		return changes, nil
   223	}

