    10	
    11	// Config holds all wt configuration. Every field has a sensible default.
    12	// Resolved via: defaults → global (~/.config/wt/config.toml) → global per-repo → .wt.toml
    13	type Config struct {
    14		// BaseBranch is the branch worktrees are created from and rebased onto.
    15		// Common values: "main", "staging", "develop"
    16		BaseBranch string `toml:"base_branch"`
    17	
    18		// Remote is the git remote name. Almost always "origin".
    19		Remote string `toml:"remote"`
    20	
    21		// BranchPrefix is prepended to new branch names: "<prefix>/<name>".
    22		// Default: git user's first name (lowercase). Set to "" to disable prefixing.
    23		// Pointer so we can distinguish "not set" (nil) from "explicitly empty" ("").
    24		BranchPrefix *string `toml:"branch_prefix"`
    25	
    26		// WorktreePrefix controls the directory naming: "<prefix><name>".
    27		// Default: "wt-<repo>-". Set to customize (e.g., "wt-" for shorter names).
    28		// Pointer so we can distinguish "not set" (nil) from "explicitly empty" ("").
    29		WorktreePrefix *string `toml:"worktree_prefix"`
    30	
    31		// StaleThreshold is the number of days after which a worktree with no open PR
    32		// is considered stale in `wt list`. Default: 7.
    33		StaleThreshold int `toml:"stale_threshold"`
    34	
    35		// AutoInstall controls whether `wt rebase` runs the package manager
    36		// install command when the lockfile changes. Default: true.
    37		// Pointer to distinguish "not set" (nil → true) from "explicitly false".
    38		AutoInstall *bool `toml:"auto_install"`
    39	
    40		// PortBase is added to a worktree's index to give WT_PORT. Default: 3000.
    41		PortBase int `toml:"port_base"`
    42	
    43		// Init configures the `wt init` command behavior.
    44		Init InitConfig `toml:"init"`
    45	
    46		// Hooks are shell commands run at points in a worktree's life. Only the
    47		// global config may set them; see RepoHooksIgnored.
    48		Hooks HooksConfig `toml:"hooks"`
    49	
    50		// RepoHooksIgnored is set when .wt.toml has [hooks]. Hooks run without being
    51		// asked for, so a repo you clone must not be able to set them.
    52		RepoHooksIgnored bool `toml:"-"`
    53	}
    54	
    55	// HooksConfig lists shell commands per lifecycle event. Configure under [hooks].
    56	type HooksConfig struct {
    57		// PostNew runs in the new worktree after new, pr and pull (after init, if it ran).
    58		PostNew []string `toml:"post_new"`
    59	
    60		// PreClose runs in the worktree before close removes it. A failure aborts the close.
    61		PreClose []string `toml:"pre_close"`
    62	
    63		// PostClose runs in the main worktree after close removes the worktree.
    64		PostClose []string `toml:"post_close"`
    65	}
    66	
    67	// globalFile is the on-disk shape of ~/.config/wt/config.toml.
    68	// Top-level fields are defaults; [repos.<name>] sections override per repo.
    69	type globalFile struct {
    70		Config
    71		Repos map[string]Config `toml:"repos"`
    72	}
    73	
    74	// InitConfig controls what `wt init` does. Entirely config-driven —
    75	// no auto-detection. Configure in .wt.toml under [init].
    76	type InitConfig struct {
    77		// CopyFiles are copied from the main worktree if missing in the target.
    78		CopyFiles []string `toml:"copy_files"`
    79	
    80		// Commands are shell commands run sequentially during init.
    81		Commands []string `toml:"commands"`
    82	
    83		// CloneDirs are copy-on-write cloned from the main worktree if missing
    84		// (e.g. node_modules), before commands run.
    85		CloneDirs []string `toml:"clone_dirs"`
    86	
    87		// Env holds KEY = "template" lines upserted into EnvFile. Templates may use
    88		// {index}, {port}, {name}, {branch} and {repo}.
    89		Env map[string]string `toml:"env"`
    90	
    91		// EnvFile is the file Env writes to, relative to the worktree. Default: ".env".
    92		EnvFile string `toml:"env_file"`
    93	}
    94	
    95	// Load reads config with layered precedence:
    96	//  1. Hardcoded defaults (base_branch="main", remote="origin")
    97	//  2. Global defaults (~/.config/wt/config.toml top-level fields)
    98	//  3. Global per-repo ([repos.<repoName>] section)
    99	//  4. Repo-local (.wt.toml in the main worktree root), except [hooks]
   100	//
   101	// Each layer only overrides fields it explicitly sets.
   102	func Load(dir, repoName string) (*Config, error) {
   103		cfg := &Config{
   104			BaseBranch: "main",
   105			Remote:     "origin",
   106		}
   107	
   108		// Layer 1+2: global defaults + per-repo overrides
   109		if globalPath, err := globalConfigPath(); err == nil {
   110			data, readErr := os.ReadFile(globalPath)
   111			if readErr == nil {
   112				var gf globalFile
   113				if err := toml.Unmarshal(data, &gf); err != nil {
   114					return nil, fmt.Errorf("global config (%s): %w", globalPath, err)
   115				}
   116				// Apply global defaults
   117				mergeConfig(cfg, &gf.Config)
   118				// Apply per-repo overrides
   119				if repoName != "" {
   120					if repoCfg, ok := gf.Repos[repoName]; ok {
   121						mergeConfig(cfg, &repoCfg)
   122					}
   123				}
   124			} else if !os.IsNotExist(readErr) {
   125				return nil, fmt.Errorf("global config (%s): %w", globalPath, readErr)
   126			}
   127		}
   128	
   129		// Layer 3: repo-local .wt.toml (overrides non-zero fields, same as other layers)
   130		repoPath := filepath.Join(dir, ".wt.toml")
   131		if data, err := os.ReadFile(repoPath); err == nil {
   132			var repoCfg Config
   133			if err := toml.Unmarshal(data, &repoCfg); err != nil {
   134				return nil, fmt.Errorf("repo config (%s): %w", repoPath, err)
   135			}
   136			if h := repoCfg.Hooks; len(h.PostNew)+len(h.PreClose)+len(h.PostClose) > 0 {
   137				cfg.RepoHooksIgnored = true
   138				repoCfg.Hooks = HooksConfig{}
   139			}
   140			mergeConfig(cfg, &repoCfg)
   141		}
   142	
   143		return cfg, nil
   144	}
   145	
   146	// mergeConfig copies non-zero fields from src into dst.
   147	func mergeConfig(dst, src *Config) {
   148		if src.BaseBranch != "" {
   149			dst.BaseBranch = src.BaseBranch
   150		}
   151		if src.Remote != "" {
   152			dst.Remote = src.Remote
   153		}
   154		if src.BranchPrefix != nil {
   155			dst.BranchPrefix = src.BranchPrefix
   156		}
   157		if src.WorktreePrefix != nil {
   158			dst.WorktreePrefix = src.WorktreePrefix
   159		}
   160		if src.StaleThreshold > 0 {
   161			dst.StaleThreshold = src.StaleThreshold
   162		}
   163		if src.AutoInstall != nil {
   164			dst.AutoInstall = src.AutoInstall
   165		}
   166		if len(src.Init.CopyFiles) > 0 {
   167			dst.Init.CopyFiles = src.Init.CopyFiles
   168		}
   169		if len(src.Init.Commands) > 0 {
   170			dst.Init.Commands = src.Init.Commands
   171		}
   172		if len(src.Init.CloneDirs) > 0 {
   173			dst.Init.CloneDirs = src.Init.CloneDirs
   174		}
   175		if len(src.Init.Env) > 0 {
   176			dst.Init.Env = src.Init.Env
   177		}
   178		if src.Init.EnvFile != "" {
   179			dst.Init.EnvFile = src.Init.EnvFile
   180		}
   181		if src.PortBase > 0 {
   182			dst.PortBase = src.PortBase
   183		}
   184		if len(src.Hooks.PostNew) > 0 {
   185			dst.Hooks.PostNew = src.Hooks.PostNew
   186		}
   187		if len(src.Hooks.PreClose) > 0 {
   188			dst.Hooks.PreClose = src.Hooks.PreClose
   189		}
   190		if len(src.Hooks.PostClose) > 0 {
   191			dst.Hooks.PostClose = src.Hooks.PostClose
   192		}
   193	}
   194	
   195	// globalConfigPath returns ~/.config/wt/config.toml.
   196	func globalConfigPath() (string, error) {
   197		home, err := os.UserHomeDir()
   198		if err != nil {
   199			return "", err
   200		}
   201		return filepath.Join(home, ".config", "wt", "config.toml"), nil
   202	}
   203	
   204	// EffectiveBranchName builds the full branch name for a new worktree.
   205	// If BranchPrefix is explicitly set (even to ""), uses that value.
   206	// Otherwise falls back to gitUsername. Returns just "name" if both are empty.
   207	func (c *Config) EffectiveBranchName(name, gitUsername string) string {
   208		var prefix string
   209		if c.BranchPrefix != nil {
   210			prefix = *c.BranchPrefix
   211		} else {
   212			prefix = gitUsername
   213		}
   214		if prefix == "" {
   215			return name
   216		}
   217		return prefix + "/" + name
   218	}
   219	
   220	// EffectiveStaleThreshold returns the stale threshold in days, defaulting to 7.
   221	func (c *Config) EffectiveStaleThreshold() int {
   222		if c.StaleThreshold > 0 {
   223			return c.StaleThreshold
   224		}
   225		return 7
   226	}
   227	
   228	// EffectiveAutoInstall returns whether auto-install is enabled (default: true).
   229	func (c *Config) EffectiveAutoInstall() bool {
   230		if c.AutoInstall != nil {
   231			return *c.AutoInstall
   232		}
   233		return true
   234	}
   235	
   236	// EffectivePortBase returns the port base, defaulting to 3000.
   237	func (c *Config) EffectivePortBase() int {
   238		if c.PortBase > 0 {
   239			return c.PortBase
   240		}
   241		return 3000
   242	}
   243	
   244	// EffectiveEnvFile returns the file [init] env writes to, defaulting to ".env".
   245	func (c *Config) EffectiveEnvFile() string {
   246		if c.Init.EnvFile != "" {
   247			return c.Init.EnvFile
   248		}
   249		return ".env"
   250	}
   251	
   252	// EffectiveWorktreeDir builds the worktree directory name.
   253	// Default pattern: "wt-<repo>/<name>" (nested under a per-project folder).
   254	// If WorktreePrefix is explicitly set (even to ""), uses flat layout instead.
   255	func (c *Config) EffectiveWorktreeDir(repoName, name string) string {
   256		if c.WorktreePrefix != nil {
   257			return *c.WorktreePrefix + name
   258		}
   259		return filepath.Join("wt-"+repoName, name)
   260	}
