     1	package ui
     2	
     3	import (
     4		"bufio"
     5		"errors"
     6		"fmt"
     7		"os"
     8		"os/exec"
     9		"path/filepath"
    10		"strconv"
    11		"strings"
    12	
    13		"github.com/fatih/color"
    14		"github.com/mattn/go-isatty"
    15	)
    16	
    17	// Color shortcuts — matches the fish script's set_color calls.
    18	var (
    19		Green   = color.New(color.FgGreen).SprintFunc()
    20		Yellow  = color.New(color.FgYellow).SprintFunc()
    21		Red     = color.New(color.FgRed).SprintFunc()
    22		Blue    = color.New(color.FgBlue).SprintFunc()
    23		Cyan    = color.New(color.FgCyan).SprintFunc()
    24		Magenta = color.New(color.FgMagenta).SprintFunc()
    25		Dim     = color.New(color.FgHiBlack).SprintFunc()
    26		Bold    = color.New(color.Bold).SprintFunc()
    27	
    28		GreenF  = color.New(color.FgGreen).PrintfFunc()
    29		YellowF = color.New(color.FgYellow).PrintfFunc()
    30		BlueF   = color.New(color.FgBlue).PrintfFunc()
    31		CyanF   = color.New(color.FgCyan).PrintfFunc()
    32		DimF    = color.New(color.FgHiBlack).PrintfFunc()
    33	)
    34	
    35	// Glyphs used throughout the UI.
    36	const (
    37		Current   = "●"
    38		Pending   = "◐"
    39		Pass      = "✓"
    40		Fail      = "✗"
    41		ArrowDown = "⇣"
    42		ArrowUp   = "⇡"
    43		PushUp    = "⬆"
    44		Dash      = "—"
    45		NoReview  = "○"
    46	)
    47	
    48	// YesFlag is set by the root command's --yes persistent flag.
    49	// When true, Confirm() skips the interactive prompt and returns true.
    50	// It never answers ConfirmDiscard(); that takes --force.
    51	var YesFlag bool
    52	
    53	// JSON is set when a command prints JSON. IsTTY then reports false, so
    54	// nothing prompts or animates, and PrintCTA stays quiet: the JSON has its own cta.
    55	var JSON bool
    56	
    57	// Truncate shortens a string to max runes, adding "…" if truncated.
    58	func Truncate(s string, max int) string {
    59		runes := []rune(s)
    60		if len(runes) <= max {
    61			return s
    62		}
    63		if max <= 1 {
    64			return "…"
    65		}
    66		return string(runes[:max-1]) + "…"
    67	}
    68	
    69	// Confirm prompts the user with a y/n question.
    70	// defaultYes: if true, pressing Enter means yes (Y/n); if false, means no (y/N).
    71	// When stdin is not a terminal, returns defaultYes without prompting.
    72	// Unrecognized input re-prompts until a valid answer is given.
    73	func Confirm(message string, defaultYes bool) bool {
    74		if YesFlag {
    75			return true
    76		}
    77		if !IsTTY() {
    78			return defaultYes
    79		}
    80		return ask(message, defaultYes)
    81	}
    82	
    83	// ErrNeedsForce is returned by ConfirmDiscard when it may not ask.
    84	var ErrNeedsForce = errors.New("won't discard work without --force\n   Re-run with --force to discard it")
    85	
    86	// ConfirmDiscard asks before throwing away uncommitted changes or commits.
    87	// Only force answers it: --yes does not, and with no terminal (or under
    88	// --yes) it returns ErrNeedsForce so the command exits non-zero.
    89	func ConfirmDiscard(message string, force bool) (bool, error) {
    90		if force {
    91			return true, nil
    92		}
    93		if YesFlag || !IsTTY() {
    94			return false, ErrNeedsForce
    95		}
    96		return ask(message, false), nil
    97	}
    98	
    99	func ask(message string, defaultYes bool) bool {
   100		hint := "y/N"
   101		if defaultYes {
   102			hint = "Y/n"
   103		}
   104	
   105		reader := bufio.NewReader(os.Stdin)
   106		for {
   107			fmt.Printf("%s [%s] ", message, hint)
   108			input, err := reader.ReadString('\n')
   109			if err != nil {
   110				return defaultYes
   111			}
   112			input = strings.TrimSpace(strings.ToLower(input))
   113	
   114			switch input {
   115			case "":
   116				return defaultYes
   117			case "y", "yes":
   118				return true
   119			case "n", "no":
   120				return false
   121			default:
   122				fmt.Println("Answer y or n.")
   123			}
   124		}
   125	}
   126	
   127	// PrintCdHint tells the shell wrapper to cd into the given path.
   128	// When WT_CD_FILE is set (by the shell wrapper), writes the path to that file.
   129	// Otherwise prints a hint so the user knows to cd manually.
   130	func PrintCdHint(path string) {
   131		if cdFile := os.Getenv("WT_CD_FILE"); cdFile != "" {
   132			if err := os.WriteFile(cdFile, []byte(path), 0600); err != nil {
   133				fmt.Printf("  → cd %s\n", shellQuote(path))
   134			}
   135			return
   136		}
   137		fmt.Printf("  → cd %s\n", shellQuote(path))
   138		PrintWrapperHint()
   139	}
   140	
   141	var wrapperHintShown bool
   142	
   143	// PrintWrapperHint tells a human at a terminal how to load the shell wrapper,
   144	// once per run. It stays quiet when the wrapper is loaded or stdout is not a TTY.
   145	func PrintWrapperHint() {
   146		if wrapperHintShown || os.Getenv("WT_CD_FILE") != "" || !IsTTY() {
   147			return
   148		}
   149		wrapperHintShown = true
   150		DimF("  wt can't cd for you: the shell wrapper isn't loaded. %s\n", wrapperSetup(currentShell()))
   151	}
   152	
   153	// currentShell names the shell that ran wt: the parent process, since $SHELL is
   154	// the login shell and may differ (zsh started from fish). Falls back to $SHELL.
   155	func currentShell() string {
   156		out, err := exec.Command("ps", "-o", "comm=", "-p", strconv.Itoa(os.Getppid())).Output()
   157		if err == nil {
   158			name := strings.TrimPrefix(filepath.Base(strings.TrimSpace(string(out))), "-")
   159			switch name {
   160			case "fish", "zsh", "bash":
   161				return name
   162			}
   163		}
   164		return os.Getenv("SHELL")
   165	}
   166	
   167	// wrapperSetup returns the line that loads the wrapper for the given $SHELL.
   168	func wrapperSetup(shell string) string {
   169		switch filepath.Base(shell) {
   170		case "fish":
   171			return "Add to ~/.config/fish/config.fish:\n    wt init-shell fish | source"
   172		case "zsh":
   173			return "Add to ~/.zshrc:\n    eval \"$(wt init-shell zsh)\""
   174		case "bash":
   175			return "Add to ~/.bashrc:\n    eval \"$(wt init-shell bash)\""
   176		}
   177		return "See: wt init-shell --help"
   178	}
   179	
   180	// shellQuote wraps a path in single quotes if it contains shell-special characters.
   181	func shellQuote(s string) string {
   182		if !strings.ContainsAny(s, " \t\n'\"\\$`|&;<>(){}[]!*?~") {
   183			return s
   184		}
   185		return "'" + strings.ReplaceAll(s, "'", `'\''`) + "'"
   186	}
   187	
   188	// Error prints an error message with ✗ prefix to stderr.
   189	func Error(format string, args ...any) {
   190		fmt.Fprintf(os.Stderr, Red("✗")+" "+format+"\n", args...)
   191	}
   192	
   193	// Success prints a success message with ✓ prefix.
   194	func Success(format string, args ...any) {
   195		fmt.Printf(Green("✓")+" "+format+"\n", args...)
   196	}
   197	
   198	// Warn prints a warning message to stderr.
   199	func Warn(format string, args ...any) {
   200		fmt.Fprintf(os.Stderr, Yellow("⚠")+"  "+format+"\n", args...)
   201	}
   202	
   203	// Info prints a regular message.
   204	func Info(format string, args ...any) {
   205		fmt.Printf(format+"\n", args...)
   206	}
   207	
   208	// IsTTY reports whether stdout is connected to a terminal.
   209	func IsTTY() bool {
   210		return !JSON && isatty.IsTerminal(os.Stdout.Fd()) || isatty.IsCygwinTerminal(os.Stdout.Fd())
   211	}
   212	
   213	// ClearLines moves the cursor up n lines and clears each one.
   214	// Used by wt watch to redraw the live status table in-place.
   215	// No-op when stdout is not a terminal.
   216	func ClearLines(n int) {
   217		if !IsTTY() {
   218			return
   219		}
   220		for range n {
   221			fmt.Print("\033[A\033[K")
   222		}
   223	}
   224	
   225	// Header prints a dim section header (like "WORKTREES").
   226	func Header(text string) {
   227		fmt.Println()
   228		DimF("  %s\n", text)
   229	}
   230	
   231	// PrintCTA prints machine-readable call-to-action suggestions for agent consumers.
   232	// Only emits output when stdout is not a TTY — human terminal output is unaffected.
   233	// Format: "cta: cmd1 | cmd2"
   234	func PrintCTA(cmds ...string) {
   235		if len(cmds) == 0 || IsTTY() || JSON {
   236			return
   237		}
   238		fmt.Printf("cta: %s\n", strings.Join(cmds, " | "))
   239	}
   240	
   241	// CISummary condenses CI check counts into one short cell: "✗ 2/36" when any
   242	// fail, "◐ 3/36" when any are pending, otherwise "✓ 36". Returns "" when
   243	// there are no checks. Callers pick the color.
   244	func CISummary(pass, fail, pending, total int) string {
   245		switch {
   246		case total == 0:
   247			return ""
   248		case fail > 0:
   249			return fmt.Sprintf("%s %d/%d", Fail, fail, total)
   250		case pending > 0:
   251			return fmt.Sprintf("%s %d/%d", Pending, pending, total)
   252		}
   253		return fmt.Sprintf("%s %d", Pass, pass)
   254	}
