    10		"time"
    11	)
    12	
    13	const (
    14		releasesURL   = "https://api.github.com/repos/mvwi/wt/releases/latest"
    15		checkInterval = 24 * time.Hour
    16		httpTimeout   = 3 * time.Second
    17	)
    18	
    19	// cacheDir returns ~/.config/wt/, creating it if needed.
    20	func cacheDir() (string, error) {
    21		configDir, err := os.UserConfigDir()
    22		if err != nil {
    23			return "", err
    24		}
    25		dir := filepath.Join(configDir, "wt")
    26		if err := os.MkdirAll(dir, 0755); err != nil {
    27			return "", err
    28		}
    29		return dir, nil
    30	}
    31	
    32	func cacheFile() (string, error) {
    33		dir, err := cacheDir()
    34		if err != nil {
    35			return "", err
    36		}
    37		return filepath.Join(dir, "latest-version"), nil
    38	}
    39	
    40	// CheckInBackground spawns a goroutine to fetch the latest version from
    41	// GitHub and write it to the cache file. Non-blocking — if the command
    42	// exits before the fetch completes, the cache is simply not updated.
    43	func CheckInBackground() {
    44		path, err := cacheFile()
    45		if err != nil {
    46			return
    47		}
    48	
    49		// Skip if cache is fresh
    50		info, err := os.Stat(path)
    51		if err == nil && time.Since(info.ModTime()) < checkInterval {
    52			return
    53		}
    54	
    55		// Skip in CI environments
    56		if os.Getenv("CI") != "" {
    57			return
    58		}
    59	
    60		go func() {
    61			client := &http.Client{Timeout: httpTimeout}
    62			resp, err := client.Get(releasesURL)
    63			if err != nil {
    64				return
    65			}
    66			defer resp.Body.Close() //nolint:errcheck // best-effort close
    67			if resp.StatusCode != 200 {
    68				return
    69			}
    70	
    71			var release struct {
    72				TagName string `json:"tag_name"`
    73			}
    74			if err := json.NewDecoder(resp.Body).Decode(&release); err != nil {
    75				return
    76			}
    77			if release.TagName == "" {
    78				return
    79			}
    80	
    81			// Atomic write via temp file + rename to prevent corruption
    82			// if the process exits mid-write.
    83			tmpPath := path + ".tmp"
    84			if err := os.WriteFile(tmpPath, []byte(release.TagName), 0644); err != nil {
    85				return
    86			}
    87			_ = os.Rename(tmpPath, path)
    88		}()
    89	}
    90	
    91	// UpdateInfo holds version comparison results for the caller to format.
    92	type UpdateInfo struct {
    93		Current string
    94		Latest  string
    95	}
    96	
    97	// GetUpdateInfo reads the cached latest version and returns update info
    98	// if a newer version is available. Returns nil if no update is needed.
    99	func GetUpdateInfo(currentVersion string) *UpdateInfo {
   100		path, err := cacheFile()
   101		if err != nil {
   102			return nil
   103		}
   104	
   105		data, err := os.ReadFile(path)
   106		if err != nil {
   107			return nil
   108		}
   109	
   110		latest := strings.TrimSpace(string(data))
   111		if latest == "" {
   112			return nil
   113		}
   114	
   115		// Normalize: strip "v" prefix for comparison
   116		cur := strings.TrimPrefix(currentVersion, "v")
   117		lat := strings.TrimPrefix(latest, "v")
   118	
   119		if cur == "dev" || lat == cur {
   120			return nil
   121		}
   122	
   123		if !isNewer(lat, cur) {
   124			return nil
   125		}
   126	
   127		return &UpdateInfo{Current: currentVersion, Latest: latest}
   128	}
   129	
   130	// isNewer returns true if version a is newer than b (simple semver comparison).
   131	func isNewer(a, b string) bool {
   132		aParts := parseSemver(a)
   133		bParts := parseSemver(b)
   134		for i := range 3 {
   135			if aParts[i] > bParts[i] {
   136				return true
   137			}
   138			if aParts[i] < bParts[i] {
   139				return false
   140			}
   141		}
   142		return false
   143	}
   144	
   145	// parseSemver extracts major.minor.patch as ints. Returns [0,0,0] on failure.
   146	func parseSemver(v string) [3]int {
   147		var parts [3]int
   148		v = strings.TrimPrefix(v, "v")
   149		segments := strings.SplitN(v, ".", 3)
   150		for i, s := range segments {
   151			if i >= 3 {
   152				break
   153			}
   154			// Strip pre-release suffix (e.g., "1-rc1" → "1")
   155			if idx := strings.IndexAny(s, "-+"); idx >= 0 {
   156				s = s[:idx]
   157			}
   158			_, _ = fmt.Sscanf(s, "%d", &parts[i])
   159		}
   160		return parts
   161	}

