    48		Hooks HooksConfig `toml:"hooks"`
    49	
    50		// RepoHooksIgnored is set when .wt.toml has [hooks]. Hooks run without being
    51		// asked for, so a repo you clone must not be able to set them.
    52		RepoHooksIgnored bool `toml:"-"`
