    68	// Top-level fields are defaults; [repos.<name>] sections override per repo.
    69	type globalFile struct {
    70		Config
    71		Repos map[string]Config `toml:"repos"`
    72	}
    73	
    74	// InitConfig controls what `wt init` does. Entirely config-driven —
    75	// no auto-detection. Configure in .wt.toml under [init].
    76	type InitConfig struct {
    77		// CopyFiles are copied from the main worktree if missing in the target.
    78		CopyFiles []string `toml:"copy_files"`
    79	
    80		// Commands are shell commands run sequentially during init.
    81		Commands []string `toml:"commands"`
    82	
    83		// CloneDirs are copy-on-write cloned from the main worktree if missing
    84		// (e.g. node_modules), before commands run.
    85		CloneDirs []string `toml:"clone_dirs"`
    86	
    87		// Env holds KEY = "template" lines upserted into EnvFile. Templates may use
