    94	
    95	// Load reads config with layered precedence:
    96	//  1. Hardcoded defaults (base_branch="main", remote="origin")
    97	//  2. Global defaults (~/.config/wt/config.toml top-level fields)
    98	//  3. Global per-repo ([repos.<repoName>] section)
    99	//  4. Repo-local (.wt.toml in the main worktree root), except [hooks]
   100	//
   101	// Each layer only overrides fields it explicitly sets.
   102	func Load(dir, repoName string) (*Config, error) {
   103		cfg := &Config{
   104			BaseBranch: "main",
   105			Remote:     "origin",
   106		}
   107	
   108		// Layer 1+2: global defaults + per-repo overrides
   109		if globalPath, err := globalConfigPath(); err == nil {
   110			data, readErr := os.ReadFile(globalPath)
   111			if readErr == nil {
   112				var gf globalFile
   113				if err := toml.Unmarshal(data, &gf); err != nil {
   114					return nil, fmt.Errorf("global config (%s): %w", globalPath, err)
   115				}
   116				// Apply global defaults
   117				mergeConfig(cfg, &gf.Config)
   118				// Apply per-repo overrides
   119				if repoName != "" {
   120					if repoCfg, ok := gf.Repos[repoName]; ok {
   121						mergeConfig(cfg, &repoCfg)
   122					}
   123				}
   124			} else if !os.IsNotExist(readErr) {
   125				return nil, fmt.Errorf("global config (%s): %w", globalPath, readErr)
   126			}
   127		}
   128	
   129		// Layer 3: repo-local .wt.toml (overrides non-zero fields, same as other layers)
   130		repoPath := filepath.Join(dir, ".wt.toml")
   131		if data, err := os.ReadFile(repoPath); err == nil {
   132			var repoCfg Config
   133			if err := toml.Unmarshal(data, &repoCfg); err != nil {
   134				return nil, fmt.Errorf("repo config (%s): %w", repoPath, err)
   135			}
   136			if h := repoCfg.Hooks; len(h.PostNew)+len(h.PreClose)+len(h.PostClose) > 0 {
   137				cfg.RepoHooksIgnored = true
   138				repoCfg.Hooks = HooksConfig{}
   139			}
   140			mergeConfig(cfg, &repoCfg)
   141		}
   142	
   143		return cfg, nil
   144	}
   145	
   146	// mergeConfig copies non-zero fields from src into dst.
   147	func mergeConfig(dst, src *Config) {
   148		if src.BaseBranch != "" {
   149			dst.BaseBranch = src.BaseBranch
   150		}
   151		if src.Remote != "" {
   152			dst.Remote = src.Remote
   153		}
   154		if src.BranchPrefix != nil {
   155			dst.BranchPrefix = src.BranchPrefix
   156		}
   157		if src.WorktreePrefix != nil {
   158			dst.WorktreePrefix = src.WorktreePrefix
   159		}
   160		if src.StaleThreshold > 0 {
   161			dst.StaleThreshold = src.StaleThreshold
   162		}
   163		if src.AutoInstall != nil {
   164			dst.AutoInstall = src.AutoInstall
   165		}
   166		if len(src.Init.CopyFiles) > 0 {
   167			dst.Init.CopyFiles = src.Init.CopyFiles
   168		}
   169		if len(src.Init.Commands) > 0 {
   170			dst.Init.Commands = src.Init.Commands
   171		}
   172		if len(src.Init.CloneDirs) > 0 {
   173			dst.Init.CloneDirs = src.Init.CloneDirs
   174		}
   175		if len(src.Init.Env) > 0 {
   176			dst.Init.Env = src.Init.Env
   177		}
   178		if src.Init.EnvFile != "" {
   179			dst.Init.EnvFile = src.Init.EnvFile
   180		}
   181		if src.PortBase > 0 {
   182			dst.PortBase = src.PortBase
   183		}
   184		if len(src.Hooks.PostNew) > 0 {
   185			dst.Hooks.PostNew = src.Hooks.PostNew
   186		}
   187		if len(src.Hooks.PreClose) > 0 {
   188			dst.Hooks.PreClose = src.Hooks.PreClose
   189		}
   190		if len(src.Hooks.PostClose) > 0 {
   191			dst.Hooks.PostClose = src.Hooks.PostClose
   192		}
   193	}
   194	
   195	// globalConfigPath returns ~/.config/wt/config.toml.
   196	func globalConfigPath() (string, error) {
   197		home, err := os.UserHomeDir()
   198		if err != nil {
   199			return "", err
   200		}
   201		return filepath.Join(home, ".config", "wt", "config.toml"), nil
   202	}
   203	
   204	// EffectiveBranchName builds the full branch name for a new worktree.
   205	// If BranchPrefix is explicitly set (even to ""), uses that value.
   206	// Otherwise falls back to gitUsername. Returns just "name" if both are empty.
   207	func (c *Config) EffectiveBranchName(name, gitUsername string) string {
   208		var prefix string
   209		if c.BranchPrefix != nil {
   210			prefix = *c.BranchPrefix
   211		} else {
   212			prefix = gitUsername
   213		}
   214		if prefix == "" {
   215			return name
   216		}
   217		return prefix + "/" + name
   218	}
