    57	// Truncate shortens a string to max runes, adding "…" if truncated.
    58	func Truncate(s string, max int) string {
    59		runes := []rune(s)
    60		if len(runes) <= max {
    61			return s
    62		}
    63		if max <= 1 {
    64			return "…"
