    98	
    99	func ask(message string, defaultYes bool) bool {
   100		hint := "y/N"
   101		if defaultYes {
   102			hint = "Y/n"
   103		}
   104	
   105		reader := bufio.NewReader(os.Stdin)
   106		for {
   107			fmt.Printf("%s [%s] ", message, hint)
   108			input, err := reader.ReadString('\n')
   109			if err != nil {
   110				return defaultYes
   111			}
   112			input = strings.TrimSpace(strings.ToLower(input))
   113	
   114			switch input {
   115			case "":
   116				return defaultYes
   117			case "y", "yes":
   118				return true
   119			case "n", "no":
   120				return false
   121			default:
   122				fmt.Println("Answer y or n.")
