   141	var wrapperHintShown bool
   142	
   143	// PrintWrapperHint tells a human at a terminal how to load the shell wrapper,
   144	// once per run. It stays quiet when the wrapper is loaded or stdout is not a TTY.
   145	func PrintWrapperHint() {
   146		if wrapperHintShown || os.Getenv("WT_CD_FILE") != "" || !IsTTY() {
   147			return
   148		}
   149		wrapperHintShown = true
   150		DimF("  wt can't cd for you: the shell wrapper isn't loaded. %s\n", wrapperSetup(currentShell()))
   151	}
   152	
   153	// currentShell names the shell that ran wt: the parent process, since $SHELL is
   154	// the login shell and may differ (zsh started from fish). Falls back to $SHELL.
   155	func currentShell() string {
   156		out, err := exec.Command("ps", "-o", "comm=", "-p", strconv.Itoa(os.Getppid())).Output()
   157		if err == nil {
   158			name := strings.TrimPrefix(filepath.Base(strings.TrimSpace(string(out))), "-")
   159			switch name {
   160			case "fish", "zsh", "bash":
   161				return name
   162			}
   163		}
   164		return os.Getenv("SHELL")
   165	}
   166	
   167	// wrapperSetup returns the line that loads the wrapper for the given $SHELL.
   168	func wrapperSetup(shell string) string {
   169		switch filepath.Base(shell) {
   170		case "fish":
   171			return "Add to ~/.config/fish/config.fish:\n    wt init-shell fish | source"
   172		case "zsh":
   173			return "Add to ~/.zshrc:\n    eval \"$(wt init-shell zsh)\""
   174		case "bash":
   175			return "Add to ~/.bashrc:\n    eval \"$(wt init-shell bash)\""
   176		}
   177		return "See: wt init-shell --help"
   178	}
   179	
   180	// shellQuote wraps a path in single quotes if it contains shell-special characters.
   181	func shellQuote(s string) string {
   182		if !strings.ContainsAny(s, " \t\n'\"\\$`|&;<>(){}[]!*?~") {
   183			return s
   184		}
   185		return "'" + strings.ReplaceAll(s, "'", `'\''`) + "'"
   186	}
   187	
   188	// Error prints an error message with ✗ prefix to stderr.
   189	func Error(format string, args ...any) {
   190		fmt.Fprintf(os.Stderr, Red("✗")+" "+format+"\n", args...)
   191	}
   192	
   193	// Success prints a success message with ✓ prefix.
   194	func Success(format string, args ...any) {
   195		fmt.Printf(Green("✓")+" "+format+"\n", args...)
   196	}
   197	
   198	// Warn prints a warning message to stderr.
   199	func Warn(format string, args ...any) {
   200		fmt.Fprintf(os.Stderr, Yellow("⚠")+"  "+format+"\n", args...)
   201	}
   202	
   203	// Info prints a regular message.
   204	func Info(format string, args ...any) {
   205		fmt.Printf(format+"\n", args...)
   206	}
   207	
   208	// IsTTY reports whether stdout is connected to a terminal.
   209	func IsTTY() bool {
   210		return !JSON && isatty.IsTerminal(os.Stdout.Fd()) || isatty.IsCygwinTerminal(os.Stdout.Fd())
   211	}
   212	
   213	// ClearLines moves the cursor up n lines and clears each one.
   214	// Used by wt watch to redraw the live status table in-place.
   215	// No-op when stdout is not a terminal.
   216	func ClearLines(n int) {
   217		if !IsTTY() {
   218			return
   219		}
   220		for range n {
   221			fmt.Print("\033[A\033[K")
   222		}
   223	}
   224	
   225	// Header prints a dim section header (like "WORKTREES").
   226	func Header(text string) {
   227		fmt.Println()
   228		DimF("  %s\n", text)
   229	}
   230	
   231	// PrintCTA prints machine-readable call-to-action suggestions for agent consumers.
   232	// Only emits output when stdout is not a TTY — human terminal output is unaffected.
   233	// Format: "cta: cmd1 | cmd2"
   234	func PrintCTA(cmds ...string) {
   235		if len(cmds) == 0 || IsTTY() || JSON {
   236			return
   237		}
   238		fmt.Printf("cta: %s\n", strings.Join(cmds, " | "))
   239	}
   240	
   241	// CISummary condenses CI check counts into one short cell: "✗ 2/36" when any
   242	// fail, "◐ 3/36" when any are pending, otherwise "✓ 36". Returns "" when
   243	// there are no checks. Callers pick the color.
   244	func CISummary(pass, fail, pending, total int) string {
   245		switch {
   246		case total == 0:
   247			return ""
   248		case fail > 0:
   249			return fmt.Sprintf("%s %d/%d", Fail, fail, total)
   250		case pending > 0:
   251			return fmt.Sprintf("%s %d/%d", Pending, pending, total)
   252		}
   253		return fmt.Sprintf("%s %d", Pass, pass)
   254	}
