  1	package github
  2	
  3	import (
  4		"bytes"
  5		"encoding/json"
  6		"fmt"
  7		"os/exec"
  8		"strconv"
  9		"strings"
 10		"sync"
 11	)
 12	
 13	var (
 14		ghOnce      sync.Once
 15		ghInstalled bool
 16	)
 17	
 18	// IsAvailable returns true if `gh` CLI is on PATH.
 19	func IsAvailable() bool {
 20		ghOnce.Do(func() {
 21			_, err := exec.LookPath("gh")
 22			ghInstalled = err == nil
 23		})
 24		return ghInstalled
 25	}
 26	
 27	// ResetAvailability resets the cached gh availability check.
 28	// Intended for testing only.
 29	func ResetAvailability() {
 30		ghOnce = sync.Once{}
 31		ghInstalled = false
 32	}
 33	
 34	// runGH executes a gh command and returns stdout.
 35	func runGH(args ...string) (string, error) {
 36		cmd := exec.Command("gh", args...)
 37		var stdout, stderr bytes.Buffer
 38		cmd.Stdout = &stdout
 39		cmd.Stderr = &stderr
 40		if err := cmd.Run(); err != nil {
 41			// Name only the subcommand ("gh pr list"); the full flag list buries the reason.
 42			return "", fmt.Errorf("gh %s: %s", strings.Join(args[:min(2, len(args))], " "), strings.TrimSpace(stderr.String()))
 43		}
 44		return strings.TrimSpace(stdout.String()), nil
 45	}
 46	
 47	// PR represents a GitHub pull request.
 48	type PR struct {
 49		Number         int             `json:"number"`
 50		HeadRefName    string          `json:"headRefName"`
 51		State          string          `json:"state"`
 52		ReviewRequests []ReviewRequest `json:"reviewRequests"`
 53		LatestReviews  []Review        `json:"latestReviews"`
 54		StatusChecks   Checks          `json:"statusCheckRollup"`
 55	}
 56	
 57	// ReviewRequest represents a pending review request.
 58	type ReviewRequest struct {
 59		Login string `json:"login"`
 60	}
 61	
 62	// Review represents a completed review.
 63	type Review struct {
 64		Author struct {
 65			Login string `json:"login"`
 66		} `json:"author"`
 67		State string `json:"state"` // APPROVED, CHANGES_REQUESTED, COMMENTED
 68	}
 69	
 70	// StatusCheckRun represents a CI check.
 71	type StatusCheckRun struct {
 72		Name       string `json:"name"`
 73		State      string `json:"state"`      // SUCCESS, FAILURE, PENDING, etc.
 74		Conclusion string `json:"conclusion"` // SUCCESS, FAILURE, SKIPPED, TIMED_OUT, CANCELLED, ""
 75	}
 76	
 77	// Checks is a PR's statusCheckRollup. gh mixes check runs (which have a name)
 78	// with commit statuses such as codecov (which have a context), and lists a job
 79	// once per workflow event. Decoding gives every check a name and keeps one
 80	// entry per name, the worst result winning.
 81	type Checks []StatusCheckRun
 82	
 83	// UnmarshalJSON implements json.Unmarshaler.
 84	func (cs *Checks) UnmarshalJSON(data []byte) error {
 85		var raw []struct {
 86			StatusCheckRun
 87			Context string `json:"context"`
 88		}
 89		if err := json.Unmarshal(data, &raw); err != nil {
 90			return err
 91		}
 92		rank := map[string]int{"pass": 0, "pending": 1, "fail": 2}
 93		index := map[string]int{}
 94		out := Checks{}
 95		for _, r := range raw {
 96			c := r.StatusCheckRun
 97			if c.Name == "" {
 98				c.Name = r.Context
 99			}
100			if c.Name == "" {
101				continue
102			}
103			if i, ok := index[c.Name]; ok {
104				if rank[c.Result()] > rank[out[i].Result()] {
105					out[i] = c
106				}
107				continue
108			}
109			index[c.Name] = len(out)
110			out = append(out, c)
111		}
112		*cs = out
113		return nil
114	}
115	
116	// Result classifies a CI check as "pass", "fail", or "pending".
117	func (c StatusCheckRun) Result() string {
118		switch {
119		case c.Conclusion == "SUCCESS" || c.Conclusion == "SKIPPED" || c.State == "SUCCESS":
120			return "pass"
121		case c.Conclusion == "FAILURE" || c.Conclusion == "TIMED_OUT" || c.Conclusion == "CANCELLED" || c.State == "FAILURE" || c.State == "ERROR":
122			return "fail"
123		default:
124			return "pending"
125		}
126	}
127	
128	// ReviewSummary aggregates review counts.
129	type ReviewSummary struct {
130		Approved int
131		Changes  int
132		Pending  int
133	}
134	
135	// CISummary aggregates CI check counts.
136	type CISummary struct {
137		Pass    int
138		Fail    int
139		Pending int
140		Total   int
141	}
142	
143	// GetReviewSummary computes review state counts.
144	func (pr *PR) GetReviewSummary() ReviewSummary {
145		return getReviewSummary(pr.ReviewRequests, pr.LatestReviews)
146	}
147	
148	// GetCISummary computes CI check state counts.
149	func (pr *PR) GetCISummary() CISummary {
150		return getCISummary(pr.StatusChecks)
151	}
152	
153	// getReviewSummary computes review state counts from requests and reviews.
154	// A pending re-review request supersedes a stale completed review.
155	func getReviewSummary(requests []ReviewRequest, reviews []Review) ReviewSummary {
156		reRequested := make(map[string]bool)
157		for _, rr := range requests {
158			if rr.Login != "" {
159				reRequested[rr.Login] = true
160			}
161		}
162	
163		var s ReviewSummary
164		seen := make(map[string]bool)
165		for _, r := range reviews {
166			login := r.Author.Login
167			if login == "" || r.State == "COMMENTED" {
168				continue
169			}
170			seen[login] = true
171			if reRequested[login] {
172				s.Pending++
173				continue
174			}
175			switch r.State {
176			case "APPROVED":
177				s.Approved++
178			case "CHANGES_REQUESTED":
179				s.Changes++
180			}
181		}
182		for _, rr := range requests {
183			if rr.Login != "" && !seen[rr.Login] {
184				seen[rr.Login] = true
185				s.Pending++
186			}
187		}
188		return s
189	}
190	
191	// getCISummary computes CI check state counts from status checks.
192	// Checks with empty names (GitHub summary checks) are excluded.
193	func getCISummary(checks []StatusCheckRun) CISummary {
194		var s CISummary
195		for _, c := range checks {
196			if c.Name == "" {
197				continue
198			}
199			s.Total++
200			switch c.Result() {
201			case "pass":
202				s.Pass++
203			case "fail":
204				s.Fail++
205			default:
206				s.Pending++
207			}
208		}
209		return s
210	}
211	
212	// ListPRs fetches PRs in a given state with full review/CI data.
213	// When heads are given, it fetches only PRs whose head branch matches one of
214	// them, which is far faster on busy repos than listing the latest 50.
215	func ListPRs(state string, heads ...string) ([]PR, error) {
216		if !IsAvailable() {
217			return nil, nil
218		}
219	
220		fields := "number,headRefName"
221		if state == "open" {
222			fields = "number,headRefName,reviewRequests,latestReviews,statusCheckRollup"
223		}
224		args := []string{"pr", "list", "--state", state, "--json", fields}
225	
226		if len(heads) == 0 {
227			return listPRs(append(args, "--limit", "50")...)
228		}
229		var all []PR
230		for _, q := range headQueries(heads) {
231			// shortcut: head: is a prefix match on GitHub, so a short branch name can
232			// pull in extra PRs and crowd out the limit; callers match exactly.
233			prs, err := listPRs(append(args, "--limit", "100", "--search", q)...)
234			if err != nil {
235				return nil, err
236			}
237			all = append(all, prs...)
238		}
239		return all, nil
240	}
241	
242	func listPRs(args ...string) ([]PR, error) {
243		out, err := runGH(args...)
244		if err != nil {
245			return nil, err
246		}
247		var prs []PR
248		if err := json.Unmarshal([]byte(out), &prs); err != nil {
249			return nil, err
250		}
251		return prs, nil
252	}
253	
254	// maxHeadQuery keeps each search under GitHub's 256-character query limit,
255	// with room for the repo and state qualifiers gh adds.
256	const maxHeadQuery = 180
257	
258	// headQueries packs "head:<branch>" terms, which GitHub ORs together, into
259	// search strings no longer than maxHeadQuery.
260	func headQueries(heads []string) []string {
261		var queries []string
262		cur := ""
263		for _, h := range heads {
264			term := "head:" + h
265			if cur != "" && len(cur)+1+len(term) > maxHeadQuery {
266				queries = append(queries, cur)
267				cur = ""
268			}
269			if cur != "" {
270				cur += " "
271			}
272			cur += term
273		}
274		if cur != "" {
275			queries = append(queries, cur)
276		}
277		return queries
278	}
279	
280	// PRDetail is the rich PR info used by the dashboard detail panel.
281	// Fetched on demand — kept separate from the lighter `PR` returned by ListPRs.
282	type PRDetail struct {
283		Number int    `json:"number"`
284		Title  string `json:"title"`
285		Body   string `json:"body"`
286		Author struct {
287			Login string `json:"login"`
288		} `json:"author"`
289		StatusChecks Checks `json:"statusCheckRollup"`
290	}
291	
292	// GetPRDetail fetches title/body/author and named CI checks for one PR in a
293	// single gh call. Returns (nil, nil) when gh isn't installed.
294	func GetPRDetail(number int) (*PRDetail, error) {
295		if !IsAvailable() {
296			return nil, nil
297		}
298		out, err := runGH("pr", "view", strconv.Itoa(number),
299			"--json", "number,title,body,author,statusCheckRollup")
300		if err != nil {
301			return nil, err
302		}
303		var d PRDetail
304		if err := json.Unmarshal([]byte(out), &d); err != nil {
305			return nil, err
306		}
307		return &d, nil
308	}
309	
310	// FindPRForBranch returns the first PR matching the branch name and state.
311	func FindPRForBranch(prs []PR, branch string) *PR {
312		for i := range prs {
313			if prs[i].HeadRefName == branch {
314				return &prs[i]
315			}
316		}
317		return nil
318	}
319	
320	// GetPRForBranch fetches the PR for a specific branch.
321	// Returns (nil, nil) if gh is not available or no PR exists.
322	func GetPRForBranch(branch string) (*PR, error) {
323		if !IsAvailable() {
324			return nil, nil
325		}
326		out, err := runGH("pr", "list", "--head", branch, "--json", "number,state", "--limit", "1")
327		if err != nil {
328			return nil, err
