 18	// IsAvailable returns true if `gh` CLI is on PATH.
 19	func IsAvailable() bool {
 20		ghOnce.Do(func() {
 21			_, err := exec.LookPath("gh")
 22			ghInstalled = err == nil
 23		})
 24		return ghInstalled
 25	}
