 47	// PR represents a GitHub pull request.
 48	type PR struct {
 49		Number         int             `json:"number"`
 50		HeadRefName    string          `json:"headRefName"`
 51		State          string          `json:"state"`
 52		ReviewRequests []ReviewRequest `json:"reviewRequests"`
 53		LatestReviews  []Review        `json:"latestReviews"`
 54		StatusChecks   Checks          `json:"statusCheckRollup"`
 55	}
