413	// WatchStatus holds detailed PR state from `gh pr view`, including fields
414	// not available from `gh pr list` (mergeStateStatus, mergeable).
415	type WatchStatus struct {
416		Number           int             `json:"number"`
417		Title            string          `json:"title"`
418		State            string          `json:"state"` // OPEN, CLOSED, MERGED
419		HeadRefName      string          `json:"headRefName"`
420		MergeStateStatus string          `json:"mergeStateStatus"` // CLEAN, BLOCKED, BEHIND, DRAFT, DIRTY, UNKNOWN
421		Mergeable        string          `json:"mergeable"`        // MERGEABLE, CONFLICTING, UNKNOWN
422		ReviewDecision   string          `json:"reviewDecision"`   // APPROVED, CHANGES_REQUESTED, REVIEW_REQUIRED, ""
423		ReviewRequests   []ReviewRequest `json:"reviewRequests"`
424		LatestReviews    []Review        `json:"latestReviews"`
425		StatusChecks     Checks          `json:"statusCheckRollup"`
426	}
427	
428	// GetReviewSummary computes review state counts for a WatchStatus.
429	func (ws *WatchStatus) GetReviewSummary() ReviewSummary {
430		return getReviewSummary(ws.ReviewRequests, ws.LatestReviews)
431	}
432	
433	// GetCISummary computes CI check state counts for a WatchStatus.
434	func (ws *WatchStatus) GetCISummary() CISummary {
435		return getCISummary(ws.StatusChecks)
436	}
437	
438	// FailedCheckNames returns the names of checks that failed.
439	func (ws *WatchStatus) FailedCheckNames() []string {
440		var names []string
441		for _, c := range ws.StatusChecks {
442			if c.Result() == "fail" {
443				names = append(names, c.Name)
444			}
445		}
446		return names
447	}
448	
449	// ChecksByStatus returns checks sorted into pass, fail, and pending buckets.
450	// Checks with empty names (GitHub summary checks) are excluded.
451	func (ws *WatchStatus) ChecksByStatus() (pass, fail, pending []StatusCheckRun) {
452		for _, c := range ws.StatusChecks {
453			if c.Name == "" {
454				continue
455			}
456			switch c.Result() {
457			case "pass":
458				pass = append(pass, c)
459			case "fail":
460				fail = append(fail, c)
461			default:
462				pending = append(pending, c)
463			}
464		}
465		return
466	}
467	
468	// ReviewItem represents a unified review entry (completed or pending).
469	type ReviewItem struct {
470		Login string
471		State string // "approved", "changes_requested", "pending"
472	}
473	
474	// ReviewItems merges LatestReviews and ReviewRequests into a unified list.
475	// A pending re-review request supersedes any previous completed review
476	// (the old approval is stale after new commits are pushed).
477	func (ws *WatchStatus) ReviewItems() []ReviewItem {
478		// Build set of logins with pending re-review requests
479		reRequested := make(map[string]bool)
480		for _, rr := range ws.ReviewRequests {
481			if rr.Login != "" {
482				reRequested[rr.Login] = true
483			}
484		}
485	
486		seen := make(map[string]bool)
487		var items []ReviewItem
488	
489		for _, r := range ws.LatestReviews {
490			if r.State == "COMMENTED" {
491				continue
492			}
493			login := r.Author.Login
494			if login == "" {
495				continue
496			}
497			seen[login] = true
498	
499			// Re-review request supersedes the stale completed review
500			if reRequested[login] {
501				items = append(items, ReviewItem{Login: login, State: "pending"})
502				continue
503			}
504	
505			state := "approved"
506			if r.State == "CHANGES_REQUESTED" {
507				state = "changes_requested"
508			}
509			items = append(items, ReviewItem{Login: login, State: state})
510		}
511	
512		// Add reviewers who were requested but haven't reviewed yet
513		for _, rr := range ws.ReviewRequests {
514			if rr.Login != "" && !seen[rr.Login] {
515				seen[rr.Login] = true
516				items = append(items, ReviewItem{Login: rr.Login, State: "pending"})
517			}
518		}
519		return items
520	}
521	
522	// GetWatchStatus fetches detailed PR status for a branch using `gh pr view`.
523	func GetWatchStatus(branch string) (*WatchStatus, error) {
524		if !IsAvailable() {
525			return nil, fmt.Errorf("gh not installed")
526		}
527	
528		fields := "number,title,state,headRefName,mergeStateStatus,mergeable,reviewDecision,reviewRequests,latestReviews,statusCheckRollup"
529		out, err := runGH("pr", "view", branch, "--json", fields)
530		if err != nil {
531			return nil, err
532		}
533	
534		var ws WatchStatus
535		if err := json.Unmarshal([]byte(out), &ws); err != nil {
536			return nil, err
537		}
538		return &ws, nil
539	}
540	
541	// repoSettings holds the merge method settings for a repository.
542	type repoSettings struct {
543		AllowSquashMerge bool `json:"allow_squash_merge"`
544		AllowMergeCommit bool `json:"allow_merge_commit"`
545		AllowRebaseMerge bool `json:"allow_rebase_merge"`
546	}
547	
548	// GetDefaultMergeMethod returns the preferred merge method for the repo.
549	// Picks the first enabled method in order: squash → merge → rebase.
550	func GetDefaultMergeMethod() (string, error) {
551		slug, err := RepoSlug()
552		if err != nil {
553			return "", err
554		}
555		out, err := runGH("api", "repos/"+slug)
556		if err != nil {
557			return "", err
558		}
559		var s repoSettings
560		if err := json.Unmarshal([]byte(out), &s); err != nil {
561			return "", err
562		}
563		switch {
564		case s.AllowSquashMerge:
565			return "squash", nil
566		case s.AllowMergeCommit:
567			return "merge", nil
568		case s.AllowRebaseMerge:
569			return "rebase", nil
570		default:
571			return "merge", nil
572		}
573	}
574	
575	// MergePR merges a pull request using the given method (squash, merge, rebase).
576	func MergePR(prNumber int, method string) error {
577		_, err := runGH("pr", "merge", strconv.Itoa(prNumber), "--"+method)
578		return err
579	}
580	
581	// CreatePR creates a new pull request and returns the PR URL.
582	func CreatePR(head, base, title, body string, draft bool, labels []string) (string, error) {
583		if !IsAvailable() {
584			return "", fmt.Errorf("gh not installed")
585		}
586		args := []string{"pr", "create", "--head", head, "--base", base, "--title", title, "--body", body}
587		if draft {
588			args = append(args, "--draft")
589		}
590		for _, l := range labels {
591			args = append(args, "--label", l)
592		}
593		return runGH(args...)
594	}

