    20		ParentDir    string
    21		Username     string
    22	}
    23	
    24	// newContext builds shared context from the current repo.
    25	func newContext() (*cmdContext, error) {
    26		if !git.IsInsideRepo() {
    27			cwd, _ := os.Getwd()
    28			return nil, fmt.Errorf("not inside a git repository: %s", cwd)
    29		}
    30		if git.IsBareRepo() {
    31			cwd, _ := os.Getwd()
    32			return nil, fmt.Errorf("%s is a bare repository; wt needs a normal checkout\n   Run wt from a clone with a working tree", cwd)
    33		}
    34	
    35		mainWT, err := git.MainWorktree()
    36		if err != nil {
    37			return nil, err
    38		}
    39	
    40		repo, err := git.RepoName()
    41		if err != nil {
    42			return nil, err
    43		}
    44	
    45		cfg, err := config.Load(mainWT, repo)
    46		if err != nil {
    47			return nil, err
    48		}
    49	
    50		parentDir, err := git.ParentDir()
    51		if err != nil {
    52			return nil, err
    53		}
    54	
    55		username, err := git.Username()
    56		if err != nil && cfg.BranchPrefix == nil {
    57			// Only warn if branch_prefix isn't explicitly configured,
    58			// since the username is only used as a fallback prefix.
    59			ui.Warn("Could not determine git username — branches won't have a prefix. Set branch_prefix in .wt.toml or run: git config user.name \"Your Name\"")
    60		}
    61	
    62		return &cmdContext{
    63			Config:       cfg,
    64			RepoName:     repo,
    65			MainWorktree: mainWT,
    66			ParentDir:    parentDir,
    67			Username:     username,
    68		}, nil
    69	}
    70	
    71	// branchName builds a full branch name using config.
    72	func (c *cmdContext) branchName(name string) string {
    73		return c.Config.EffectiveBranchName(name, c.Username)
    74	}
    75	
    76	// worktreeDir builds a worktree directory name using config.
    77	func (c *cmdContext) worktreeDir(name string) string {
    78		return c.Config.EffectiveWorktreeDir(c.RepoName, name)
    79	}
    80	
    81	// worktreePath builds a full worktree path.
    82	func (c *cmdContext) worktreePath(name string) string {
    83		return c.ParentDir + "/" + c.worktreeDir(name)
    84	}
    85	
    86	// baseRef returns the full remote ref for the base branch (e.g., "origin/staging").
    87	func (c *cmdContext) baseRef() string {
    88		return c.Config.Remote + "/" + c.Config.BaseBranch
    89	}
    90	
    91	// shortName returns a worktree's path relative to the worktrees dir, so a
    92	// "feat/foo" worktree shows as "feat/foo", not "foo". Paths outside the
    93	// worktrees dir fall back to their base name.
    94	func (c *cmdContext) shortName(path string) string {
    95		prefix := c.Config.EffectiveWorktreeDir(c.RepoName, "")
    96		if rel, err := filepath.Rel(c.ParentDir, path); err == nil && rel != "." && !strings.HasPrefix(rel, "..") {
    97			return strings.TrimPrefix(strings.TrimPrefix(filepath.ToSlash(rel), filepath.ToSlash(prefix)), "/")
    98		}
    99		return strings.TrimPrefix(filepath.Base(path), prefix)
   100	}
   101	
   102	// isBaseBranch returns true if the branch is the configured base branch or a common default.
   103	func (c *cmdContext) isBaseBranch(branch string) bool {
   104		return branch == c.Config.BaseBranch || branch == "main" || branch == "master"
   105	}
   106	
   107	// isSubpath returns true if child is a subdirectory of parent.
   108	func isSubpath(child, parent string) bool {
   109		rel, err := filepath.Rel(parent, child)
   110		if err != nil {
   111			return false
   112		}
   113		return rel != "." && !strings.HasPrefix(rel, "..") && !filepath.IsAbs(rel)
   114	}
   115	
   116	// fileExists returns true if the path exists.
   117	func fileExists(path string) bool {
   118		_, err := os.Stat(path)
   119		return err == nil
   120	}
   121	
   122	// isDir returns true if the path exists and is a directory.
   123	func isDir(path string) bool {
   124		info, err := os.Stat(path)
   125		return err == nil && info.IsDir()
   126	}
   127	
   128	// completeWorktreeNames returns a Cobra ValidArgsFunction that suggests worktree short names.
   129	func completeWorktreeNames(_ *cobra.Command, _ []string, toComplete string) ([]string, cobra.ShellCompDirective) {
   130		ctx, err := newContext()
   131		if err != nil {
   132			return nil, cobra.ShellCompDirectiveNoFileComp
   133		}
   134	
   135		worktrees, err := git.ListWorktrees()
   136		if err != nil {
   137			return nil, cobra.ShellCompDirectiveNoFileComp
   138		}
   139	
   140		prefix := ctx.Config.EffectiveWorktreeDir(ctx.RepoName, "")
   141		var names []string
   142		for _, wt := range worktrees {
   143			if wt.Path == ctx.MainWorktree {
   144				continue
   145			}
   146			short := strings.TrimPrefix(filepath.Base(wt.Path), prefix)
   147			if toComplete == "" || strings.HasPrefix(short, toComplete) {
   148				names = append(names, short)
   149			}
   150		}
   151		return names, cobra.ShellCompDirectiveNoFileComp
   152	}
