    12	// knownLockfiles is the ordered list of lockfile→install-command mappings.
    13	// Order matters: first match wins (pnpm preferred over npm, etc.).
    14	var knownLockfiles = []lockfileMapping{
    15		{"pnpm-lock.yaml", "pnpm install --frozen-lockfile", "pnpm exec"},
    16		{"yarn.lock", "yarn install --frozen-lockfile", "yarn"},
    17		{"bun.lockb", "bun install --frozen-lockfile", "bunx"},
    18		{"package-lock.json", "npm ci", "npx"},
    19		{"go.sum", "go mod download", ""},
    20		{"Gemfile.lock", "bundle install", ""},
    21		{"Cargo.lock", "cargo fetch", ""},
    22		{"requirements.txt", "pip install -r requirements.txt", ""},
    23		{"pyproject.toml", "pip install -e .", ""},
    24	}
