    47	func runHooks(event string, cmds []string, dir string, env []string) error {
    48		for _, c := range cmds {
    49			fmt.Println(ui.Dim(event + ": " + c))
    50			if err := runShellString(dir, c, env...); err != nil {
    51				return fmt.Errorf("%s hook failed: %s: %w", event, c, err)
    52			}
    53		}
    54		return nil
    55	}
    56	
    57	// worktreeVars returns the values exposed to hooks, init commands and [init]
    58	// env templates. "index" and "port" are missing if no index could be assigned.
    59	func worktreeVars(ctx *cmdContext, path string) map[string]string {
    60		branch, _ := git.CurrentBranchIn(path)
    61		v := map[string]string{
    62			"name":   ctx.shortName(path),
    63			"path":   path,
    64			"branch": branch,
    65			"main":   ctx.MainWorktree,
    66			"repo":   ctx.RepoName,
    67		}
    68		gitDir, err := git.RunIn(path, "rev-parse", "--absolute-git-dir")
    69		var n int
    70		if err == nil {
    71			n, err = worktreeIndex(gitDir)
    72		}
    73		if err != nil {
    74			ui.Warn("Could not assign a worktree index: %v", err)
    75			return v
    76		}
    77		v["index"] = strconv.Itoa(n)
    78		v["port"] = strconv.Itoa(ctx.Config.EffectivePortBase() + n)
    79		return v
    80	}
    81	
    82	// worktreeEnv turns vars into WT_* environment entries.
    83	func worktreeEnv(vars map[string]string) []string {
    84		env := make([]string, 0, len(vars))
    85		for k, v := range vars {
    86			env = append(env, "WT_"+strings.ToUpper(k)+"="+v)
    87		}
    88		return env
    89	}
    90	
    91	// expandVars replaces {key} in s with vars[key].
    92	func expandVars(s string, vars map[string]string) string {
    93		for k, v := range vars {
    94			s = strings.ReplaceAll(s, "{"+k+"}", v)
    95		}
    96		return s
    97	}
    98	
    99	// worktreeIndex returns the index stored in gitDir, or stores the lowest
   100	// number no sibling worktree uses. The main worktree is always 0.
   101	// shortcut: two wt runs at the same moment can pick the same number.
   102	func worktreeIndex(gitDir string) (int, error) {
   103		// Linked worktrees keep their git dir at <common>/worktrees/<id>.
   104		if filepath.Base(filepath.Dir(gitDir)) != "worktrees" {
   105			return 0, nil
   106		}
   107		own := filepath.Join(gitDir, indexFile)
   108		if n, ok := readIndex(own); ok {
   109			return n, nil
   110		}
   111		used := map[int]bool{}
   112		siblings, _ := filepath.Glob(filepath.Join(filepath.Dir(gitDir), "*", indexFile))
   113		for _, f := range siblings {
   114			if n, ok := readIndex(f); ok {
   115				used[n] = true
   116			}
   117		}
   118		n := 1
   119		for used[n] {
   120			n++
   121		}
   122		return n, os.WriteFile(own, []byte(strconv.Itoa(n)+"\n"), 0644)
   123	}
   124	
   125	func readIndex(path string) (int, bool) {
   126		data, err := os.ReadFile(path)
   127		if err != nil {
   128			return 0, false
   129		}
   130		n, err := strconv.Atoi(strings.TrimSpace(string(data)))
   131		return n, err == nil && n > 0
   132	}
   133	
   134	// printToolHint tells the user to trust direnv/mise files; wt never runs them.
   135	func printToolHint(dir string) {
   136		var cmds []string
   137		if fileExists(filepath.Join(dir, ".envrc")) {
   138			cmds = append(cmds, "direnv allow")
   139		}
   140		for _, f := range []string{"mise.toml", ".mise.toml", ".tool-versions"} {
   141			if fileExists(filepath.Join(dir, f)) {
   142				cmds = append(cmds, "mise trust")
   143				break
   144			}
   145		}
   146		if len(cmds) > 0 {
   147			fmt.Println(ui.Dim("Tip: run " + strings.Join(cmds, " and ") + " in this worktree"))
   148		}
   149	}
