    90	
    91	// shortName returns a worktree's path relative to the worktrees dir, so a
    92	// "feat/foo" worktree shows as "feat/foo", not "foo". Paths outside the
    93	// worktrees dir fall back to their base name.
    94	func (c *cmdContext) shortName(path string) string {
    95		prefix := c.Config.EffectiveWorktreeDir(c.RepoName, "")
    96		if rel, err := filepath.Rel(c.ParentDir, path); err == nil && rel != "." && !strings.HasPrefix(rel, "..") {
    97			return strings.TrimPrefix(strings.TrimPrefix(filepath.ToSlash(rel), filepath.ToSlash(prefix)), "/")
    98		}
    99		return strings.TrimPrefix(filepath.Base(path), prefix)
   100	}
