   127	
   128	// completeWorktreeNames returns a Cobra ValidArgsFunction that suggests worktree short names.
   129	func completeWorktreeNames(_ *cobra.Command, _ []string, toComplete string) ([]string, cobra.ShellCompDirective) {
   130		ctx, err := newContext()
   131		if err != nil {
   132			return nil, cobra.ShellCompDirectiveNoFileComp
   133		}
   134	
   135		worktrees, err := git.ListWorktrees()
   136		if err != nil {
   137			return nil, cobra.ShellCompDirectiveNoFileComp
   138		}
   139	
   140		prefix := ctx.Config.EffectiveWorktreeDir(ctx.RepoName, "")
   141		var names []string
   142		for _, wt := range worktrees {
   143			if wt.Path == ctx.MainWorktree {
   144				continue
   145			}
   146			short := strings.TrimPrefix(filepath.Base(wt.Path), prefix)
   147			if toComplete == "" || strings.HasPrefix(short, toComplete) {
   148				names = append(names, short)
   149			}
   150		}
