   252	// runStatus is called when `wt` is run with no subcommand.
   253	// Shows a quick status of the current worktree, or help if not in a repo.
   254	func runStatus(cmd *cobra.Command, args []string) error {
   255		if !git.IsInsideWorkTree() {
   256			return cmd.Help()
   257		}
   258	
   259		ctx, err := newContext()
   260		if err != nil {
   261			return cmd.Help()
   262		}
   263	
   264		cwd, err := os.Getwd()
   265		if err != nil {
   266			return fmt.Errorf("cannot determine current directory: %w", err)
   267		}
   268		branch, err := git.CurrentBranch()
   269		if err != nil {
   270			return cmd.Help()
   271		}
   272	
   273		// Worktree name
   274		short := ctx.shortName(cwd)
   275		isMain := cwd == ctx.MainWorktree || isSubpath(cwd, ctx.MainWorktree)
   276	
   277		fmt.Printf("%s %s", ui.Yellow(ui.Current), short)
   278		if branch != short {
   279			fmt.Printf("  %s", ui.Dim(branch))
   280		}
   281		fmt.Println()
   282	
   283		// Base/main branch: just show it
   284		if isMain || ctx.isBaseBranch(branch) {
   285			printHelpPointer()
   286			return nil
   287		}
   288	
   289		// Sync status
   290		ab, err := git.GetAheadBehind(ctx.baseRef())
   291		if err == nil {
   292			var parts []string
   293			if ab.Behind > 0 {
   294				parts = append(parts, ui.Yellow(fmt.Sprintf("%s%d behind %s", ui.ArrowDown, ab.Behind, ctx.Config.BaseBranch)))
   295			}
   296			if ab.Ahead > 0 {
   297				parts = append(parts, ui.Green(fmt.Sprintf("%s%d ahead", ui.ArrowUp, ab.Ahead)))
   298			}
   299			if len(parts) > 0 {
   300				fmt.Printf("  %s\n", strings.Join(parts, "  "))
   301			} else {
   302				fmt.Printf("  %s\n", ui.Green("up to date with "+ctx.Config.BaseBranch))
   303			}
   304		}
   305	
   306		// Uncommitted changes
   307		if git.HasChanges() {
   308			statusShort, _ := git.StatusShort()
   309			lines := strings.Split(strings.TrimSpace(statusShort), "\n")
   310			fmt.Printf("  %s\n", ui.Yellow(fmt.Sprintf("%d uncommitted change(s)", len(lines))))
   311		}
   312	
   313		// Unpushed commits
   314		unpushed := git.UnpushedCountIn(cwd)
   315		if unpushed > 0 {
   316			fmt.Printf("  %s\n", ui.Cyan(fmt.Sprintf("%s%d unpushed commit(s)", ui.PushUp, unpushed)))
   317		}
   318	
   319		// PR status
   320		if github.IsAvailable() {
   321			pr, err := github.GetPRForBranch(branch)
   322			if err != nil {
   323				fmt.Fprintln(os.Stderr, ui.Dim("  Couldn't load PR status: "+firstLine(err.Error())))
   324			}
   325			if pr != nil && pr.State == "OPEN" {
   326				rs := pr.GetReviewSummary()
   327				cs := pr.GetCISummary()
   328	
   329				prStr := fmt.Sprintf("PR #%d", pr.Number)
   330				var details []string
   331				if rs.Approved > 0 {
   332					details = append(details, fmt.Sprintf("%d approved", rs.Approved))
   333				}
   334				if rs.Changes > 0 {
   335					details = append(details, fmt.Sprintf("%d changes requested", rs.Changes))
   336				}
   337				if rs.Pending > 0 {
   338					details = append(details, fmt.Sprintf("%d pending", rs.Pending))
   339				}
   340				switch {
   341				case cs.Fail > 0:
   342					details = append(details, ui.Red("CI failing"))
   343				case cs.Pending > 0:
   344					details = append(details, ui.Yellow("CI pending"))
   345				case cs.Pass > 0:
   346					details = append(details, ui.Green("CI passing"))
   347				}
   348	
   349				if len(details) > 0 {
   350					fmt.Printf("  %s  %s\n", ui.Blue(prStr), strings.Join(details, ", "))
   351				} else {
   352					fmt.Printf("  %s\n", ui.Blue(prStr))
   353				}
   354			}
   355		}
   356	
   357		printHelpPointer()
   358		return nil
   359	}
