    17	
    18	// finishNew runs init (if asked) and the post_new hooks for a new worktree,
    19	// then prints the next step. new, pr and pull all end here.
    20	func finishNew(ctx *cmdContext, name, wtPath string, doInit bool) error {
    21		if doInit {
    22			if err := runInitIn(wtPath, ctx); err != nil {
    23				return err
    24			}
    25		}
    26		warnRepoHooks(ctx)
    27		if hooks := ctx.Config.Hooks.PostNew; len(hooks) > 0 {
    28			if err := runHooks("post_new", hooks, wtPath, worktreeEnv(worktreeVars(ctx, wtPath))); err != nil {
    29				ui.Warn("%v", err)
    30			}
    31		}
    32		if !doInit {
    33			printToolHint(wtPath)
    34			printSwitchHint(name)
    35		}
    36		return nil
    37	}
    38	
    39	// runHooks runs each command with sh -c in dir and stops at the first failure.
    40	// warnRepoHooks says that [hooks] in .wt.toml were skipped and where they belong.
    41	func warnRepoHooks(ctx *cmdContext) {
    42		if ctx.Config.RepoHooksIgnored {
    43			ui.Warn("Skipped [hooks] in .wt.toml: hooks only run from ~/.config/wt/config.toml (under [repos.%s] for this repo)", ctx.RepoName)
    44		}
    45	}
