    57	// worktreeVars returns the values exposed to hooks, init commands and [init]
    58	// env templates. "index" and "port" are missing if no index could be assigned.
    59	func worktreeVars(ctx *cmdContext, path string) map[string]string {
    60		branch, _ := git.CurrentBranchIn(path)
    61		v := map[string]string{
    62			"name":   ctx.shortName(path),
    63			"path":   path,
    64			"branch": branch,
    65			"main":   ctx.MainWorktree,
    66			"repo":   ctx.RepoName,
    67		}
    68		gitDir, err := git.RunIn(path, "rev-parse", "--absolute-git-dir")
    69		var n int
    70		if err == nil {
    71			n, err = worktreeIndex(gitDir)
    72		}
    73		if err != nil {
    74			ui.Warn("Could not assign a worktree index: %v", err)
    75			return v
    76		}
    77		v["index"] = strconv.Itoa(n)
    78		v["port"] = strconv.Itoa(ctx.Config.EffectivePortBase() + n)
    79		return v
    80	}
