    99	// worktreeIndex returns the index stored in gitDir, or stores the lowest
   100	// number no sibling worktree uses. The main worktree is always 0.
   101	// shortcut: two wt runs at the same moment can pick the same number.
   102	func worktreeIndex(gitDir string) (int, error) {
   103		// Linked worktrees keep their git dir at <common>/worktrees/<id>.
   104		if filepath.Base(filepath.Dir(gitDir)) != "worktrees" {
   105			return 0, nil
   106		}
   107		own := filepath.Join(gitDir, indexFile)
   108		if n, ok := readIndex(own); ok {
   109			return n, nil
   110		}
   111		used := map[int]bool{}
   112		siblings, _ := filepath.Glob(filepath.Join(filepath.Dir(gitDir), "*", indexFile))
   113		for _, f := range siblings {
   114			if n, ok := readIndex(f); ok {
   115				used[n] = true
   116			}
   117		}
   118		n := 1
   119		for used[n] {
   120			n++
   121		}
   122		return n, os.WriteFile(own, []byte(strconv.Itoa(n)+"\n"), 0644)
   123	}
   124	
   125	func readIndex(path string) (int, bool) {
   126		data, err := os.ReadFile(path)
   127		if err != nil {
   128			return 0, false
   129		}
   130		n, err := strconv.Atoi(strings.TrimSpace(string(data)))
   131		return n, err == nil && n > 0
   132	}
   133	
   134	// printToolHint tells the user to trust direnv/mise files; wt never runs them.
   135	func printToolHint(dir string) {
   136		var cmds []string
   137		if fileExists(filepath.Join(dir, ".envrc")) {
   138			cmds = append(cmds, "direnv allow")
   139		}
   140		for _, f := range []string{"mise.toml", ".mise.toml", ".tool-versions"} {
   141			if fileExists(filepath.Join(dir, f)) {
   142				cmds = append(cmds, "mise trust")
   143				break
   144			}
   145		}
   146		if len(cmds) > 0 {
   147			fmt.Println(ui.Dim("Tip: run " + strings.Join(cmds, " and ") + " in this worktree"))
   148		}
   149	}
