    12	// cloneTree copies src to dst with reflinks. --reflink=always makes cp fail
    13	// on file systems without them instead of making a full copy.
    14	func cloneTree(src, dst string) error {
    15		if out, err := exec.Command("cp", "-R", "--reflink=always", src, dst).CombinedOutput(); err != nil {
    16			_ = os.RemoveAll(dst) // dst did not exist before; drop the partial copy
    17			msg, _, _ := strings.Cut(strings.TrimSpace(string(out)), "\n")
    18			if msg == "" {
    19				msg = err.Error()
    20			}
    21			return fmt.Errorf("%s", msg)
    22		}
    23		return nil
    24	}

