   165		// Step 3: Write [init] env into the env file (after copy_files may have created it)
   166		if len(cfg.Env) > 0 {
   167			envFile := ctx.Config.EffectiveEnvFile()
   168			vals := make(map[string]string, len(cfg.Env))
   169			for k, tmpl := range cfg.Env {
   170				vals[k] = expandVars(tmpl, vars)
   171			}
   172			if err := upsertEnv(filepath.Join(dir, envFile), vals); err != nil {
   173				steps = append(steps, initStep{"write " + envFile, "fail", err.Error()})
   174			} else {
   175				steps = append(steps, initStep{"write " + envFile, "ok", ""})
   176			}
   177		}
   178	
   179		// Step 4: Run commands
   180		env := worktreeEnv(vars)
   181		for _, command := range commands {
   182			fmt.Printf("  %s %s\n", ui.Dim("$"), command)
   183			if err := runShellString(dir, command, env...); err != nil {
   184				steps = append(steps, initStep{"run " + command, "fail", err.Error()})
   185			} else {
   186				steps = append(steps, initStep{"run " + command, "ok", ""})
   187			}
   188			fmt.Println()
   189		}
   190	
   191		// Print summary
   192		hasFailures := false
   193		for _, s := range steps {
   194			switch s.status {
   195			case "ok":
   196				fmt.Printf("  %s  %s\n", ui.Green(ui.Pass), s.label)
   197			case "skip":
   198				fmt.Printf("  %s  %s %s\n", ui.Dim(ui.Dash), s.label, ui.Dim("("+s.detail+")"))
   199			case "fail":
   200				fmt.Printf("  %s  %s %s\n", ui.Red(ui.Fail), s.label, ui.Dim("("+s.detail+")"))
   201				hasFailures = true
   202			}
   203		}
   204	
   205		fmt.Println()
   206		if hasFailures {
   207			ui.Warn("Worktree initialized with errors")
   208		} else {
   209			ui.Success("Worktree initialized")
   210		}
   211	
   212		if !configured && len(cfg.CloneDirs) == 0 && len(cfg.Env) == 0 {
   213			fmt.Println()
   214			fmt.Println(ui.Dim("Tip: add [init] to .wt.toml to customize this behavior"))
   215		}
   216		printToolHint(dir)
   217	
   218		return nil
   219	}
