   125	// collectWorktreeInfos gathers branch/status data for all worktrees.
   126	func collectWorktreeInfos(ctx *cmdContext, cwd string, worktrees []git.Worktree) ([]worktreeInfo, []string) {
   127		var infos []worktreeInfo
   128		var featureBranches []string
   129	
   130		for _, wt := range worktrees {
   131			short := ctx.shortName(wt.Path)
   132	
   133			branch := wt.Branch
   134			if branch == "" {
   135				branch, _ = git.CurrentBranchIn(wt.Path)
   136			}
   137	
   138			isCurrent := wt.Path == cwd || isSubpath(cwd, wt.Path)
   139	
   140			info := worktreeInfo{
   141				Path:      wt.Path,
   142				ShortName: short,
   143				Branch:    branch,
   144				IsCurrent: isCurrent,
   145			}
   146	
   147			// Dirty count for all worktrees
   148			if changes, err := git.StatusPorcelainIn(wt.Path); err == nil {
   149				info.DirtyCount = len(changes)
   150			}
   151	
   152			if !ctx.isBaseBranch(branch) {
   153				info.Age = git.LastCommitAge(wt.Path)
   154				ab, err := git.GetAheadBehindIn(wt.Path, ctx.baseRef())
   155				if err == nil {
   156					info.Behind = ab.Behind
   157					info.Ahead = ab.Ahead
   158				}
   159				featureBranches = append(featureBranches, branch)
   160			}
   161	
   162			infos = append(infos, info)
   163		}
   164	
   165		return infos, featureBranches
   166	}
