   122	// pickWorktree opens fzf over worktrees, starting with query typed in.
   123	// Returns "" when the user cancels.
   124	func pickWorktree(ctx *cmdContext, worktrees []git.Worktree, cwd, query string) (string, error) {
   125		var lines []string
   126		for _, wt := range worktrees {
   127			short := ctx.shortName(wt.Path)
   128			branch, _ := git.CurrentBranchIn(wt.Path)
   129			marker := "  "
   130			if wt.Path == cwd || isSubpath(cwd, wt.Path) {
   131				marker = ui.Current + " "
