 77	func runInitIn(dir string, ctx *cmdContext) error {
 78		// Check if we're in the main repo
 79		if dir == ctx.MainWorktree || isSubpath(dir, ctx.MainWorktree) {
 80			return fmt.Errorf("you're in the main repo\n   Switch to a worktree first: wt switch <name>")
 81		}
 82	
 83		cfg := ctx.Config.Init
 84		copyFiles := cfg.CopyFiles
 85		commands := cfg.Commands
 86		configured := len(copyFiles) > 0 || len(commands) > 0
 87	
 88		// Auto-detect when no [init] steps are configured. clone_dirs and env
 89		// add to either set of steps.
 90		if !configured {
 91			copyFiles, commands = detectInit(ctx.MainWorktree)
 92			if len(copyFiles) == 0 && len(commands) == 0 && len(cfg.CloneDirs) == 0 && len(cfg.Env) == 0 {
 93				fmt.Println("Nothing to initialize — no [init] config and nothing detected.")
 94				fmt.Println()
 95				fmt.Println("Add an [init] section to .wt.toml to configure setup:")
 96				fmt.Println()
 97				fmt.Println("  [init]")
 98				fmt.Println("  copy_files = [\".env\"]")
 99				fmt.Println("  commands = [\"pnpm install\"]")
100				return nil
101			}
102		}
103	
104		fmt.Println("Initializing worktree…")
105		fmt.Println()
106	
107		var steps []initStep
108	
109		// Step 1: Copy files/directories from main worktree
110		for _, file := range copyFiles {
111			src := filepath.Join(ctx.MainWorktree, file)
112			dst := filepath.Join(dir, file)
113	
114			if !fileExists(src) {
115				steps = append(steps, initStep{"copy " + file, "skip", "not found in main worktree"})
116				continue
117			}
118			if fileExists(dst) {
119				steps = append(steps, initStep{"copy " + file, "skip", "already exists"})
120				continue
121			}
122	
123			if isDir(src) {
124				if err := copyDirRecursive(src, dst); err != nil {
125					steps = append(steps, initStep{"copy " + file, "fail", err.Error()})
126				} else {
127					steps = append(steps, initStep{"copy " + file, "ok", ""})
128				}
129			} else {
130				data, err := os.ReadFile(src)
131				if err != nil {
132					steps = append(steps, initStep{"copy " + file, "fail", err.Error()})
133				} else if err := os.WriteFile(dst, data, 0644); err != nil {
134					steps = append(steps, initStep{"copy " + file, "fail", err.Error()})
135				} else {
136					steps = append(steps, initStep{"copy " + file, "ok", ""})
137				}
138			}
139		}
