260	// runShellString runs command with sh -c in dir, adding env to wt's own environment.
261	func runShellString(dir, command string, env ...string) error {
262		cmd := exec.Command("sh", "-c", command)
263		cmd.Dir = dir
264		cmd.Env = append(os.Environ(), env...)
265		cmd.Stdout = os.Stdout
266		cmd.Stderr = os.Stderr
267		return cmd.Run()
268	}
