260	// runShellString runs command with sh -c in dir, adding env to wt's own environment.
261	func runShellString(dir, command string, env ...string) error {
262		cmd := exec.Command("sh", "-c", command)
263		cmd.Dir = dir
264		cmd.Env = append(os.Environ(), env...)
265		cmd.Stdout = os.Stdout
266		cmd.Stderr = os.Stderr
267		return cmd.Run()
268	}
269	
270	// upsertEnv sets each key in the env file at path: it replaces the key's line
271	// if there is one and appends one if not. Other lines stay as they are.
272	func upsertEnv(path string, vals map[string]string) error {
273		data, err := os.ReadFile(path)
274		if err != nil && !os.IsNotExist(err) {
275			return err
276		}
277		var lines []string
278		if len(data) > 0 {
279			lines = strings.Split(strings.TrimSuffix(string(data), "\n"), "\n")
280		}
281		for _, k := range slices.Sorted(maps.Keys(vals)) {
282			line := k + "=" + vals[k]
283			i := slices.IndexFunc(lines, func(l string) bool { return envKey(l) == k })
284			if i < 0 {
285				lines = append(lines, line)
286				continue
287			}
288			if strings.HasPrefix(strings.TrimSpace(lines[i]), "export ") {
289				line = "export " + line
290			}
291			lines[i] = line
292		}
293		return os.WriteFile(path, []byte(strings.Join(lines, "\n")+"\n"), 0644)
294	}
295	
296	// envKey returns the key a dotenv line sets, or "" for comments and blanks.
297	func envKey(line string) string {
298		line = strings.TrimPrefix(strings.TrimSpace(line), "export ")
299		k, _, ok := strings.Cut(line, "=")
300		if !ok || strings.HasPrefix(k, "#") {
301			return ""
302		}
303		return strings.TrimSpace(k)
304	}
305	
306	// copyDirRecursive copies a directory tree from src to dst, preserving permissions.
307	func copyDirRecursive(src, dst string) error {
308		return filepath.WalkDir(src, func(path string, d fs.DirEntry, err error) error {
309			if err != nil {
310				return err
311			}
312	
313			rel, err := filepath.Rel(src, path)
314			if err != nil {
315				return err
316			}
317			target := filepath.Join(dst, rel)
318	
319			if d.IsDir() {
320				info, err := d.Info()
321				if err != nil {
322					return err
323				}
324				return os.MkdirAll(target, info.Mode())
325			}
326	
327			data, err := os.ReadFile(path)
328			if err != nil {
329				return err
330			}
331			info, err := d.Info()
332			if err != nil {
333				return err
334			}
335			return os.WriteFile(target, data, info.Mode())
336		})
337	}
338	
339	// shellQuoteInit wraps a string in single quotes for safe shell interpolation.
340	func shellQuoteInit(s string) string {
341		if !strings.ContainsAny(s, " \t\n'\"\\$`|&;<>(){}[]!*?~") {
342			return s
343		}
344		return "'" + strings.ReplaceAll(s, "'", `'\''`) + "'"
345	}
346	
347	// findPrismaSchema walks the tree looking for a .prisma file, skipping
348	// node_modules and other heavy dirs. Returns the repo-relative path to
349	// the first schema found, or "" if none exists.
350	func findPrismaSchema(root string) string {
351		skipDirs := map[string]bool{
352			"node_modules": true,
353			".git":         true,
354			"dist":         true,
355			".next":        true,
356			".turbo":       true,
357		}
358		var result string
359		_ = filepath.WalkDir(root, func(path string, d fs.DirEntry, err error) error {
360			if err != nil {
361				return nil // skip unreadable paths
362			}
363			if result != "" {
364				return fs.SkipAll
365			}
366			if d.IsDir() && skipDirs[d.Name()] {
367				return fs.SkipDir
368			}
369			if !d.IsDir() && filepath.Ext(d.Name()) == ".prisma" {
370				rel, err := filepath.Rel(root, path)
371				if err != nil {
372					return nil
373				}
374				result = rel
375				return fs.SkipAll
376			}
377			return nil
378		})
379		return result
380	}
