192		var openPRs, mergedPRs, closedPRs []github.PR
193		if github.IsAvailable() {
194			openPRs, mergedPRs, closedPRs, _ = fetchPRData(branches)
195		}
196	
197		entries := make([]listJSONEntry, 0, len(infos))
198		hasBehind := false
199		hasStale := false
200		for _, info := range infos {
201			isBase := ctx.isBaseBranch(info.Branch)
202	
203			entry := listJSONEntry{
204				Name:       info.ShortName,
205				Path:       info.Path,
206				Branch:     info.Branch,
207				Current:    info.IsCurrent,
208				BaseBranch: isBase,
209				Age:        info.Age,
210				Dirty:      info.DirtyCount,
211				Behind:     info.Behind,
212				Ahead:      info.Ahead,
213			}
214	
215			if !isBase {
216				entry.PR = findPRJSON(info.Branch, openPRs, mergedPRs, closedPRs)
217				if info.Behind > 0 {
218					hasBehind = true
219				}
220				if entry.PR != nil && (entry.PR.State == "merged" || entry.PR.State == "closed") {
221					hasStale = true
222				}
223			}
224	
225			entries = append(entries, entry)
226		}
227	
228		data, err := json.MarshalIndent(listJSONOutput{Worktrees: entries, CTA: deriveListCTA(hasStale, hasBehind)}, "", "  ")
229		if err != nil {
