297	// findPRJSON finds the PR for a branch and converts it to JSON format.
298	func findPRJSON(branch string, openPRs, mergedPRs, closedPRs []github.PR) *listJSONPR {
299		if pr := github.FindPRForBranch(openPRs, branch); pr != nil {
300			rs := pr.GetReviewSummary()
301			cs := pr.GetCISummary()
302			return &listJSONPR{
303				Number: pr.Number,
304				State:  "open",
305				Review: listJSONReview{Approved: rs.Approved, Changes: rs.Changes, Pending: rs.Pending},
306				CI:     listJSONCI{Pass: cs.Pass, Fail: cs.Fail, Pending: cs.Pending, Total: cs.Total},
307			}
308		}
309		if pr := github.FindPRForBranch(mergedPRs, branch); pr != nil {
310			return &listJSONPR{Number: pr.Number, State: "merged"}
311		}
312		if pr := github.FindPRForBranch(closedPRs, branch); pr != nil {
313			return &listJSONPR{Number: pr.Number, State: "closed"}
314		}
315		return nil
316	}
