168	// fetchPRData fetches open, merged, and closed PRs for the given branches in
169	// parallel. err is the first failure, if any; the other lists may still hold data.
170	func fetchPRData(branches []string) (openPRs, mergedPRs, closedPRs []github.PR, err error) {
171		if len(branches) == 0 {
172			return
173		}
174		var openErr, mergedErr, closedErr error
175		var wg sync.WaitGroup
176		wg.Add(3)
177		go func() { defer wg.Done(); openPRs, openErr = github.ListPRs("open", branches...) }()
178		go func() { defer wg.Done(); mergedPRs, mergedErr = github.ListPRs("merged", branches...) }()
179		go func() { defer wg.Done(); closedPRs, closedErr = github.ListPRs("closed", branches...) }()
180		wg.Wait()
181		err = cmp.Or(openErr, mergedErr, closedErr)
182		if openErr == nil {
183			cacheOpenPRs(branches, openPRs)
184		}
185		return
186	}
