366			spin := ui.NewSpinner("Loading PR status")
367			var err error
368			openPRs, mergedPRs, closedPRs, err = fetchPRData(featureBranches)
369			spin.Stop()
370			switch {
371			case err == nil:
372			case isNotGitHubRemote(err):
373				// Not a GitHub repo: PR columns would only ever be empty.
374				showPR = false
375			default:
376				_, reason, _ := strings.Cut(err.Error(), ": ")
377				ui.DimF("  PR status may be incomplete: %s\n", ui.Truncate(reason, 100))
378				ui.DimF("  Check gh with: gh auth status\n\n")
379			}
380		} else if ui.IsTTY() {
381			ui.DimF("  PR status needs the GitHub CLI (gh): https://cli.github.com\n\n")
382		}
383	
384		staleThreshold := ctx.Config.EffectiveStaleThreshold()
385	
386		header := fmt.Sprintf("  %-*s %-6s %-6s %-8s", listBranchCol, "Branch", "Commit", "Dirty", "Sync")
387		if showPR {
388			header += fmt.Sprintf(" %-6s %-8s %s", "PR", "Review", "CI")
389		}
390		ui.DimF("%s\n", header)
391		ui.DimF("  %s\n", strings.Repeat("─", utf8.RuneCountInString(header)-2))
392	
393		var table strings.Builder
394		hasStale := false
395	
396		for _, info := range infos {
397			if ctx.isBaseBranch(info.Branch) {
398				continue
399			}
400	
401			var openPR, mergedPR, closedPR *github.PR
402			isStale := false
403			if showPR {
404				openPR = github.FindPRForBranch(openPRs, info.Branch)
405				mergedPR = github.FindPRForBranch(mergedPRs, info.Branch)
406				closedPR = github.FindPRForBranch(closedPRs, info.Branch)
407				// Stale: no recent activity and no open PR. Needs PR data, or
408				// every quiet branch would look stale.
409				isStale = git.WorktreeAgeDays(info.Path) >= staleThreshold && openPR == nil
410			}
411	
412			// Dim the entire row if stale
413			colorize := fmt.Sprintf
414			if isStale {
415				colorize = func(f string, a ...any) string {
416					return ui.Dim(fmt.Sprintf(f, a...))
417				}
418			}
419	
420			row := &table
421			fmt.Fprintf(row, "  %s ", colorize("%s", padRight(ui.Truncate(info.Branch, listBranchCol), listBranchCol)))
422			fmt.Fprintf(row, "%s ", colorize("%-6s", info.Age))
423	
424			// Dirty
425			switch {
426			case info.DirtyCount == 0:
427				fmt.Fprintf(row, "%s ", ui.Dim(fmt.Sprintf("%-6s", ui.Dash)))
428			case isStale:
429				fmt.Fprintf(row, "%s ", colorize("%-6d", info.DirtyCount))
430			default:
431				fmt.Fprintf(row, "%s ", ui.Yellow(fmt.Sprintf("%-6d", info.DirtyCount)))
432			}
433	
434			// Sync
435			syncStr := padRight(buildSyncStr(info.Behind, info.Ahead), 8)
436			switch {
437			case isStale:
438				fmt.Fprint(row, colorize("%s", syncStr))
439			case info.Behind > 0:
440				fmt.Fprint(row, ui.Yellow(syncStr))
441			default:
442				fmt.Fprint(row, ui.Green(syncStr))
443			}
444	
445			if showPR {
446				row.WriteString(" ")
447				switch {
448				case openPR != nil:
449					row.WriteString(openPRStatus(openPR, info.Path))
450				case mergedPR != nil:
451					fmt.Fprintf(row, "%s %s   %s", ui.Blue(fmt.Sprintf("%-6s", fmt.Sprintf("#%d", mergedPR.Number))), ui.Green("merged"), ui.Yellow("stale"))
452					hasStale = true
453				case closedPR != nil:
454					fmt.Fprintf(row, "%s %s  %s", ui.Blue(fmt.Sprintf("%-6s", fmt.Sprintf("#%d", closedPR.Number))), ui.Red("closed"), ui.Yellow("stale"))
455					hasStale = true
456				case isStale:
457					row.WriteString(ui.Dim(ui.Dash) + " \U0001f4a4") // 💤
458				default:
459					row.WriteString(ui.Dim(ui.Dash))
460				}
461			}
462			row.WriteString("\n")
463		}
464		fmt.Print(table.String())
465	
466		if legend := listLegend(table.String()); legend != "" {
467			fmt.Println()
468			ui.DimF("  %s\n", legend)
469		}
470	
471		if hasStale {
472			fmt.Printf("  %s\n", ui.Yellow("Tip: run 'wt prune' to clean up stale worktrees"))
473		}
474	
475		fmt.Println()
476		return nil
477	}
478	
479	// isNotGitHubRemote reports whether gh failed because no remote points at a
480	// GitHub host. That is a normal setup, not an error worth a warning.
481	func isNotGitHubRemote(err error) bool {
482		return strings.Contains(err.Error(), "known GitHub host")
483	}
484	
485	// padRight pads s with spaces to width runes. Unlike %-*s it counts runes,
486	// not bytes, so glyphs and non-ASCII names line up.
487	func padRight(s string, width int) string {
488		if n := utf8.RuneCountInString(s); n < width {
489			return s + strings.Repeat(" ", width-n)
490		}
491		return s
492	}
493	
494	// legendEntries lists each glyph the status table can show, in print order.
495	var legendEntries = []struct{ glyph, meaning string }{
496		{ui.ArrowDown, "behind base"},
497		{ui.ArrowUp, "ahead of base"},
498		{ui.Pass, "ok"},
499		{ui.Fail, "fail/changes"},
500		{ui.Pending, "pending"},
501		{ui.NoReview, "none yet"},
502		{ui.PushUp, "unpushed"},
503		{"\U0001f4a4", "stale"},
504	}
505	
506	// listLegend explains only the glyphs that appear in the rendered table.
507	func listLegend(table string) string {
508		var parts []string
509		for _, e := range legendEntries {
510			if strings.Contains(table, e.glyph) {
511				parts = append(parts, e.glyph+" "+e.meaning)
512			}
513		}
514		return strings.Join(parts, "  ")
515	}
516	
517	func buildSyncStr(behind, ahead int) string {
518		var parts []string
519		if behind > 0 {
520			parts = append(parts, fmt.Sprintf("%s%d", ui.ArrowDown, behind))
521		}
522		if ahead > 0 {
523			parts = append(parts, fmt.Sprintf("%s%d", ui.ArrowUp, ahead))
524		}
525		if len(parts) == 0 {
526			return ui.Pass
527		}
528		return strings.Join(parts, "")
529	}
530	
531	// openPRStatus renders the PR, Review, and CI cells for an open PR.
532	func openPRStatus(pr *github.PR, wtPath string) string {
533		var b strings.Builder
534		b.WriteString(ui.Blue(fmt.Sprintf("%-6s", fmt.Sprintf("#%d", pr.Number))) + " ")
535	
536		// Review glyphs, one per reviewer
537		rs := pr.GetReviewSummary()
538		reviewCount := rs.Approved + rs.Changes + rs.Pending
539		if rs.Approved > 0 {
540			b.WriteString(ui.Green(strings.Repeat(ui.Pass, rs.Approved)))
541		}
542		if rs.Changes > 0 {
543			b.WriteString(ui.Red(strings.Repeat(ui.Fail, rs.Changes)))
544		}
545		if rs.Pending > 0 {
546			b.WriteString(ui.Blue(strings.Repeat(ui.Pending, rs.Pending)))
547		}
548		if reviewCount == 0 {
549			b.WriteString(ui.Dim(ui.NoReview))
550			reviewCount = 1
551		}
552		if pad := 8 - reviewCount; pad > 0 {
553			b.WriteString(strings.Repeat(" ", pad))
554		}
555		b.WriteString(" ")
556	
557		// CI: one summary cell, not one glyph per check
558		cs := pr.GetCISummary()
559		ci := ui.CISummary(cs.Pass, cs.Fail, cs.Pending, cs.Total)
560		switch {
561		case cs.Total == 0:
562			b.WriteString(ui.Dim(ui.NoReview))
563		case cs.Fail > 0:
564			b.WriteString(ui.Red(ci))
565		case cs.Pending > 0:
566			b.WriteString(ui.Yellow(ci))
567		default:
568			b.WriteString(ui.Green(ci))
569		}
570	
571		if unpushed := git.UnpushedCountIn(wtPath); unpushed > 0 {
572			b.WriteString(" " + ui.Magenta(fmt.Sprintf("%s%d", ui.PushUp, unpushed)))
573		}
574		return b.String()
575	}

