 13		"github.com/mvwi/wt/internal/github"
 14		"github.com/mvwi/wt/internal/ui"
 15		"github.com/spf13/cobra"
 16	)
 17	
 18	var newCmd = &cobra.Command{
 19		Use:     "new <name>",
 20		Aliases: []string{"create"},
 21		GroupID: groupWorkflow,
 22		Short:   "Create a new worktree with a feature branch",
 23		Long: `Create a new worktree with a feature branch based on your configured base branch.
 24	
 25	By default, creates a branch named "<prefix>/<name>" from the base branch
 26	(configurable in .wt.toml, defaults to "main").
 27	
 28	Use --from to create a worktree from an existing branch or PR number.`,
 29		Example: `  wt new sidebar-card               Create <user>/sidebar-card from base branch
 30	  wt new --from feature/old         Create worktree from existing branch
 31	  wt new fix --from origin/hotfix   Create worktree with custom name from remote
 32	  wt new --from #123                Create worktree from PR #123's branch
 33	  wt new feature --init             Create + auto-initialize
 34	  wt new fix-123 -i --run "claude 'fix issue 123'"
 35	                                    Create, init, then start a command in it`,
 36		Args: cobra.MaximumNArgs(1),
 37		RunE: runNew,
 38	}
 39	
 40	var newFromBranch string
 41	
 42	// Flags shared by new, pr and pull. Only one command runs per process.
 43	var (
 44		createInit bool
 45		createEdit bool
 46		createRun  string
 47	)
 48	
 49	func init() {
 50		newCmd.Flags().StringVarP(&newFromBranch, "from", "f", "", "base on an existing branch or PR number")
 51		addCreateFlags(newCmd)
 52		rootCmd.AddCommand(newCmd)
 53	}
 54	
 55	func addCreateFlags(c *cobra.Command) {
 56		c.Flags().BoolVarP(&createInit, "init", "i", false, "run 'wt init' after creating")
 57		c.Flags().BoolVarP(&createEdit, "edit", "e", false, "open the new worktree in your editor")
 58		c.Flags().StringVar(&createRun, "run", "", "run a shell command in the new worktree and exit with its code")
 59		addOutputFlag(c)
 60	}
 61	
 62	func runNew(cmd *cobra.Command, args []string) error {
 63		if err := startOutput(); err != nil {
 64			return err
 65		}
 66		ctx, err := newContext()
 67		if err != nil {
 68			return err
 69		}
 70	
 71		var name string
 72		if len(args) > 0 {
 73			name = args[0]
 74		}
 75	
 76		// --from mode: create worktree from existing branch
 77		if newFromBranch != "" {
 78			if prNumber, ok := parsePRNumber(newFromBranch); ok {
 79				return newFromPR(ctx, name, prNumber)
 80			}
 81			return createFromBranch(ctx, name, newFromBranch)
 82		}
 83	
 84		if name == "" {
 85			return fmt.Errorf("name is required\n\nUsage: wt new <name>\n       wt new --from <branch>")
 86		}
 87		if err := validateName(ctx, name); err != nil {
 88			return err
 89		}
 90	
 91		return newFromBase(ctx, name)
 92	}
 93	
 94	// createFromBranch creates a worktree for an existing local or remote
 95	// branch. Used by `wt new --from` and `wt pull`.
 96	func createFromBranch(ctx *cmdContext, name, branch string) error {
 97		// Fetch so ResolveBranch can find remote branches
 98		spin := ui.NewSpinner("Fetching latest refs")
 99		err := git.FetchAll(ctx.Config.Remote)
100		spin.Stop()
101		if err != nil {
102			ui.Warn("Fetch failed: %v", err)
103		}
104	
105		ref, _, err := git.ResolveBranch(branch, ctx.Config.Remote)
106		if err != nil {
107			return err
108		}
109	
110		if name == "" {
111			name = nameFromBranch(ref, ctx.Config.Remote)
112		}
113		if err := validateName(ctx, name); err != nil {
114			return err
115		}
116	
117		return createWorktreeFromRemote(ctx, name, ref, 0)
118	}
119	
120	// parsePRNumber checks if s looks like a PR number ("#123" or "123")
121	// and returns the parsed number if so.
122	func parsePRNumber(s string) (int, bool) {
123		s = strings.TrimPrefix(s, "#")
124		n, err := strconv.Atoi(s)
125		if err != nil || n <= 0 {
126			return 0, false
127		}
128		return n, true
129	}
130	
131	func newFromPR(ctx *cmdContext, name string, number int) error {
132		if !github.IsAvailable() {
133			return fmt.Errorf("gh CLI is required to resolve PR numbers (brew install gh)")
134		}
135	
136		spin := ui.NewSpinner(fmt.Sprintf("Fetching PR #%d", number))
137		pr, err := github.GetPRByNumber(number)
138		spin.Stop()
139		if err != nil {
140			return fmt.Errorf("failed to fetch PR #%d: %w", number, err)
141		}
142	
143		fmt.Printf("PR #%d: %s\n", pr.Number, pr.Title)
144		fmt.Println()
145	
146		return checkoutPR(ctx, name, pr)
147	}
148	
149	// prBranch returns the local branch for a PR. A fork PR's head branch does not
150	// exist on our remote, so it gets its own pr/<N>-<head> name to avoid clashing
151	// with local branches.
152	func prBranch(pr *github.PRInfo) string {
153		if pr.IsCrossRepository {
154			return fmt.Sprintf("pr/%d-%s", pr.Number, pr.HeadRefName)
155		}
156		return pr.HeadRefName
157	}
158	
159	// checkoutPR fetches a PR's head and creates a worktree for it. Used by both
160	// `wt pr` and `wt new --from <number>`.
161	func checkoutPR(ctx *cmdContext, name string, pr *github.PRInfo) error {
162		branch := prBranch(pr)
163		if path := worktreeForBranch(branch); path != "" {
164			short := ctx.shortName(path)
165			return fmt.Errorf("PR #%d is already checked out as %s\n   Run wt switch %s", pr.Number, short, short)
166		}
167		if name == "" {
168			name = nameFromBranch(pr.HeadRefName, ctx.Config.Remote)
169		}
170		if err := validateName(ctx, name); err != nil {
171			return err
172		}
173	
174		// Fork PRs: GitHub mirrors every PR head at pull/<N>/head on the base repo.
175		ref := pr.HeadRefName
176		if pr.IsCrossRepository {
177			ref = fmt.Sprintf("pull/%d/head:%s", pr.Number, branch)
178		}
179		spin := ui.NewSpinner(fmt.Sprintf("Fetching PR #%d", pr.Number))
180		err := git.Fetch(ctx.Config.Remote, ref)
181		spin.Stop()
182		if err != nil {
183			ui.Warn("Fetch failed: %v", err)
184		}
185	
186		if pr.IsCrossRepository {
187			ui.Warn("PR #%d comes from the fork %s. Pushes from %s go nowhere until you add that fork as a remote.",
188				pr.Number, pr.HeadRepository.NameWithOwner, branch)
189			if pr.MaintainerCanModify {
190				owner, _, _ := strings.Cut(pr.HeadRepository.NameWithOwner, "/")
191				fmt.Printf("   The author allows edits: git remote add %s https://github.com/%s.git\n",
192					owner, pr.HeadRepository.NameWithOwner)
193				fmt.Printf("   then: git push %s HEAD:%s\n", owner, pr.HeadRefName)
194			}
195			fmt.Println()
196		}
197	
198		return createWorktreeFromRemote(ctx, name, branch, pr.Number)
199	}
200	
201	// worktreeForBranch returns the path of the worktree that has branch checked
202	// out, or "" if none does.
203	func worktreeForBranch(branch string) string {
204		wts, err := git.ListWorktrees()
205		if err != nil {
206			return ""
207		}
208		for _, wt := range wts {
209			if wt.Branch == branch {
210				return wt.Path
211			}
212		}
213		return ""
214	}
215	
216	// nameFromBranch derives a short worktree name from a branch ref.
217	// Takes the last segment after "/" and strips the remote prefix if present.
218	//
219	//	"origin/user/fix-login" → "fix-login"
220	//	"user/fix-login"        → "fix-login"
221	//	"fix-login"             → "fix-login"
222	func nameFromBranch(ref, remote string) string {
223		parts := strings.Split(ref, "/")
224		name := parts[len(parts)-1]
225		return strings.TrimPrefix(name, remote+"/")
226	}
227	
228	// createWorktreeFromRemote checks out an existing branch, local or remote,
229	// into a new worktree. Callers fetch first. pr is the PR number, or 0. Used by
230	// `wt new --from`, `wt pull` and `wt pr`.
231	func createWorktreeFromRemote(ctx *cmdContext, name, remoteBranch string, pr int) error {
232		wtPath := ctx.worktreePath(name)
233	
234		if isDir(wtPath) {
235			return fmt.Errorf("worktree already exists: %s\n   Use wt switch %s to switch to it", wtPath, name)
236		}
237	
238		localBranch := strings.TrimPrefix(remoteBranch, ctx.Config.Remote+"/")
239		remoteRef := ctx.Config.Remote + "/" + localBranch
240	
241		if path := worktreeForBranch(localBranch); path != "" {
242			short := ctx.shortName(path)
243			return fmt.Errorf("%s is already checked out as %s\n   Run wt switch %s", localBranch, short, short)
244		}
245	
246		fmt.Println("Creating worktree from existing branch…")
247		fmt.Printf("  Directory: %s\n", wtPath)
248		fmt.Printf("  Branch: %s\n", localBranch)
249		fmt.Println()
250	
251		var err error
252		if git.BranchExists(localBranch) {
253			err = git.AddWorktreeFromExisting(wtPath, localBranch)
254		} else {
255			err = git.AddWorktreeFromRemote(wtPath, localBranch, remoteRef)
256		}
257		if err != nil {
258			return fmt.Errorf("failed to create worktree: %w", err)
259		}
260	
261		fmt.Println()
262		ui.Success("Created worktree")
263		fmt.Println()
264	
265		return finishCreate(ctx, name, wtPath, localBranch, pr)
266	}
267	
268	// finishCreate runs the steps that follow a new worktree: finishNew (init,
269	// hooks, hint; the hint goes to stderr in JSON mode), then the JSON, --edit
270	// and --run.
271	func finishCreate(ctx *cmdContext, name, path, branch string, pr int) error {
272		if err := finishNew(ctx, name, path, createInit); err != nil {
273			return err
274		}
275		if jsonOut != nil {
276			cta := []string{"wt switch " + name}
277			if !createInit {
278				cta = append(cta, "wt init")
279			}
280			if err := printJSON(worktreeJSON{Name: name, Path: path, Branch: branch, Base: ctx.Config.BaseBranch, PR: pr, CTA: cta}); err != nil {
281				return err
282			}
283		}
284	
285		if createEdit {
286			if err := openEditor(path); err != nil {
287				return err
288			}
289		}
290		if createRun != "" {
291			return runCommandIn(path, createRun)
292		}
293		return nil
294	}
295	
296	// runCommandIn runs command with sh -c inside dir, attached to the terminal.
297	// It returns an exitCode error when the command fails, so wt exits with the
298	// same code.
299	func runCommandIn(dir, command string) error {
300		c := exec.Command("sh", "-c", command)
301		c.Dir = dir
302		c.Stdin, c.Stdout, c.Stderr = os.Stdin, os.Stdout, os.Stderr
303	
304		// Ctrl-C belongs to the command. Catching it here keeps wt alive until
305		// the command exits; the command still gets the signal.
306		sig := make(chan os.Signal, 1)
307		signal.Notify(sig, os.Interrupt)
308		defer signal.Stop(sig)
309	
310		err := c.Run()
311		var exitErr *exec.ExitError
312		if errors.As(err, &exitErr) {
313			return exitCode(max(exitErr.ExitCode(), 1))
314		}
315		return err
316	}
317	
318	// printSwitchHint prints the next-step command.
319	func printSwitchHint(name string) {
320		fmt.Printf("  → wt switch %s && wt init\n", name)
321		ui.PrintWrapperHint()
322		ui.PrintCTA("wt switch "+name, "wt init")
323	}
324	
325	// validateName rejects worktree names that would break git or hide the
326	// main checkout from 'wt switch'. Call it before doing any work.
327	func validateName(ctx *cmdContext, name string) error {
328		if strings.HasPrefix(name, "-") {
329			return fmt.Errorf("invalid name %q: it can't start with a dash", name)
330		}
331		if ctx.isBaseBranch(name) || name == ctx.RepoName {
332			return fmt.Errorf("invalid name %q: 'wt switch %s' would open this worktree instead of the main checkout\n   Pick another name", name, name)
333		}
334		if branch := ctx.branchName(name); !git.IsValidBranchName(branch) {
335			return fmt.Errorf("invalid name %q: %q is not a valid git branch name", name, branch)
336		}
337		return nil
338	}
339	
340	func newFromBase(ctx *cmdContext, name string) error {
341		branch := ctx.branchName(name)
342		wtPath := ctx.worktreePath(name)
343	
344		if isDir(wtPath) {
345			return fmt.Errorf("worktree already exists: %s\n   Use wt switch %s to switch to it", wtPath, name)
346		}
347	
348		if git.BranchExists(branch) {
349			return fmt.Errorf("branch already exists: %s\n   Use wt new --from %s to create a worktree for it\n   Or wt switch %s if the worktree already exists", branch, branch, name)
350		}
351	
352		fmt.Println("Creating worktree…")
353		fmt.Printf("  Directory: %s\n", wtPath)
354		fmt.Printf("  Branch: %s (from %s)\n", branch, ctx.Config.BaseBranch)
355		fmt.Println()
356	
357		// Fetch latest base branch
358		spin := ui.NewSpinner(fmt.Sprintf("Fetching %s", ctx.Config.BaseBranch))
359		if err := git.Fetch(ctx.Config.Remote, ctx.Config.BaseBranch); err != nil {
360			spin.Stop()
361			ui.Warn("Fetch failed: %v", err)
362		} else {
363			spin.Stop()
364		}
365	
366		if err := git.AddWorktree(wtPath, branch, ctx.baseRef()); err != nil {
367			return fmt.Errorf("failed to create worktree: %w", err)
368		}
369	
370		fmt.Println()
371		ui.Success("Created worktree")
372		fmt.Println()
373	
374		return finishCreate(ctx, name, wtPath, branch, 0)
375	}

