227			ui.Success("Already up to date")
228			return nil
229		}
230	
231		fmt.Printf("Fast-forwarding (%d commit(s) behind)...\n", ab.Behind)
232		if _, err := git.MergeFF(remoteRef); err != nil {
233			restoreStash(didStash)
234			return fmt.Errorf("cannot fast-forward %s: %w", branch, err)
235		}
236	
237		restoreStash(didStash)
238		autoInstallIfNeeded(ctx, preRef)
239		fmt.Println()
240		ui.Success("%s synced!", branch)
241		return nil
242	}
243	
244	func rebaseContinue(ctx *cmdContext) error {
245		if !git.StateFileExists(stateFileName) {
246			return fmt.Errorf("no rebase in progress\n   Start one with: wt rebase")
247		}
248	
249		didStash, preRef := parseRebaseState()
250	
251		inProgress, _ := git.IsRebaseInProgress()
252		if !inProgress {
253			// The rebase ended outside wt (e.g. plain `git rebase --continue`).
254			// Don't pop a stash this old: the stack may have changed since.
255			git.RemoveStateFile(stateFileName)
256			if didStash {
257				ui.Warn("wt stashed your changes before that rebase. Check `git stash list` for \"wt rebase: auto-stash\".")
258			}
259			return fmt.Errorf("no rebase in progress\n   Start one with: wt rebase")
260		}
261	
262		fmt.Println("Continuing rebase…")
263		if err := git.RebaseContinue(); err != nil {
264			fmt.Println()
265			ui.Warn("Still have conflicts. Resolve them and run:")
266			fmt.Printf("  %s\n", ui.Cyan("wt rebase --continue"))
267			return errSilent
268		}
269		restoreStash(didStash)
270		git.RemoveStateFile(stateFileName)
271	
272		if preRef != "" {
273			autoInstallIfNeeded(ctx, preRef)
274		}
275	
276		fmt.Println()
277		ui.Success("Synced with base branch")
278		return nil
279	}
280	
281	func rebaseAbort() error {
282		inProgress, _ := git.IsRebaseInProgress()
283		hasState := git.StateFileExists(stateFileName)
284	
285		if !inProgress && !hasState {
286			return fmt.Errorf("no rebase in progress\n   Start one with: wt rebase")
287		}
288	
289		if inProgress {
290			if err := git.RebaseAbort(); err != nil {
291				return fmt.Errorf("failed to abort rebase: %w", err)
292			}
293		}
294	
295		if hasState {
296			didStash, _ := parseRebaseState()
297			restoreStash(didStash)
298			git.RemoveStateFile(stateFileName)
299		}
300	
301		ui.Success("Rebase aborted")
302		return nil
303	}
304	
305	func rebaseAll(ctx *cmdContext) error {
306		worktrees, err := git.ListWorktrees()
307		if err != nil {
308			return err
309		}
310	
311		fmt.Println("Rebasing all worktrees onto", ctx.Config.BaseBranch+"…")
312		fmt.Println()
313	
314		spin := ui.NewSpinner(fmt.Sprintf("Fetching %s", ctx.baseRef()))
315		if err := git.Fetch(ctx.Config.Remote, ctx.Config.BaseBranch); err != nil {
316			spin.Stop()
317			ui.Warn("Fetch failed: %v", err)
318		} else {
319			spin.Stop()
320		}
321		fmt.Println()
322	
323		var rebased, skipped, uptodate, failed int
324		var conflicted []string
325		commits := func(n int) string {
326			if n == 1 {
327				return "1 commit"
328			}
329			return fmt.Sprintf("%d commits", n)
330		}
331	
332		for _, wt := range worktrees {
333			branch, _ := git.CurrentBranchIn(wt.Path)
334			if ctx.isBaseBranch(branch) {
335				short := ctx.shortName(wt.Path)
336				fmt.Printf("  %-25s ", short)
337				remoteRef := ctx.Config.Remote + "/" + ctx.Config.BaseBranch
338				ab, err := git.GetAheadBehindIn(wt.Path, remoteRef)
339				if err != nil || ab.Behind == 0 {
340					fmt.Printf("%s\n", ui.Green("✓ up to date"))
341					uptodate++
342				} else {
343					preRef, _ := git.RevParseHeadIn(wt.Path)
344					if err := git.MergeFFIn(wt.Path, remoteRef); err != nil {
345						fmt.Printf("%s\n", ui.Red("✗ fast-forward failed"))
346						failed++
347					} else {
348						msg := fmt.Sprintf("✓ fast-forwarded (%s)", commits(ab.Behind))
349						suffix := lockfileChangedSuffix(wt.Path, preRef)
350						fmt.Printf("%s%s\n", ui.Green(msg), suffix)
351						rebased++
352					}
353				}
354				continue
355			}
356	
357			short := ctx.shortName(wt.Path)
358			fmt.Printf("  %-25s ", short)
359	
360			if git.HasChangesIn(wt.Path) {
361				fmt.Printf("%s\n", ui.Yellow("⚠ has uncommitted changes (skipped)"))
362				skipped++
363				continue
364			}
365	
366			ab, err := git.GetAheadBehindIn(wt.Path, ctx.baseRef())
367			if err != nil || ab.Behind == 0 {
368				fmt.Printf("%s\n", ui.Green("✓ up to date"))
369				uptodate++
370				continue
371			}
372	
373			preRef, _ := git.RevParseHeadIn(wt.Path)
374			if err := git.RebaseIn(wt.Path, ctx.baseRef()); err != nil {
375				git.RebaseAbortIn(wt.Path)
376				fmt.Printf("%s\n", ui.Red("✗ conflicts (aborted)"))
377				conflicted = append(conflicted, short)
378				failed++
379			} else {
380				msg := fmt.Sprintf("✓ rebased (%s from %s)", commits(ab.Behind), ctx.Config.BaseBranch)
381				suffix := lockfileChangedSuffix(wt.Path, preRef)
382				fmt.Printf("%s%s\n", ui.Green(msg), suffix)
383				rebased++
384			}
385		}
386	
387		fmt.Println()
388		fmt.Println("Summary:")
389		if rebased > 0 {
390			fmt.Printf("  %s\n", ui.Green(fmt.Sprintf("✓ %d rebased", rebased)))
391		}
392		if uptodate > 0 {
393			fmt.Printf("  ✓ %d already up to date\n", uptodate)
394		}
395		if skipped > 0 {
396			fmt.Printf("  %s\n", ui.Yellow(fmt.Sprintf("⚠ %d skipped (uncommitted changes)", skipped)))
397		}
398		if failed > 0 {
399			fmt.Printf("  %s\n", ui.Red(fmt.Sprintf("✗ %d failed", failed)))
400		}
401		if len(conflicted) > 0 {
402			fmt.Println()
403			fmt.Println("Resolve conflicts one worktree at a time:")
404			var ctas []string
405			for _, name := range conflicted {
406				cmd := "wt switch " + name + " && wt rebase"
407				fmt.Printf("  %s\n", ui.Cyan(cmd))
408				ctas = append(ctas, cmd)
409			}
410			ui.PrintCTA(ctas...)
411		}
412		if failed > 0 {
413			return errSilent // scripts must see that not every worktree was rebased
414		}
415		return nil
416	}
417	
418	// parseRebaseState reads the state file and returns whether changes were stashed
419	// and the pre-rebase HEAD ref. Format: "stash_state:pre_ref" (e.g., "stashed:abc123").
420	// Backwards-compatible with old format that had no colon.
421	func parseRebaseState() (didStash bool, preRef string) {
422		state, _ := git.ReadStateFile(stateFileName)
423		parts := strings.SplitN(state, ":", 2)
424		didStash = parts[0] == "stashed"
425		if len(parts) == 2 {
426			preRef = parts[1]
427		}
428		return
429	}
430	
431	func restoreStash(didStash bool) {
432		if didStash {
433			fmt.Println("Restoring stashed changes…")
434			if err := git.StashPop(); err != nil {
435				ui.Warn("Failed to restore stash — run 'git stash pop' manually")
436			}
437		}
438	}
439	
440	// lockfileChangedSuffix checks if a lockfile changed in a worktree between
441	// preRef and HEAD. Returns a warning suffix string, or "" if unchanged.
442	func lockfileChangedSuffix(dir, preRef string) string {
443		if preRef == "" {
444			return ""
445		}
446		lockfile, _ := detectInstallCommand(dir)
447		if lockfile == "" {
448			return ""
449		}
450		changed, err := git.DiffNameOnlyIn(dir, preRef, "HEAD")
451		if err != nil {
452			return ""
453		}
454		if slices.Contains(changed, lockfile) {
455			return ui.Yellow(" — lockfile changed, run wt init")
456		}
457		return ""
458	}
459	
460	// autoInstallIfNeeded checks if a lockfile changed between preRef and HEAD,
461	// and if so, runs the detected install command. Warns on failure but never
462	// returns an error (the rebase already succeeded).
463	func autoInstallIfNeeded(ctx *cmdContext, preRef string) {
464		if !ctx.Config.EffectiveAutoInstall() {
465			return
466		}
467	
468		cwd, err := os.Getwd()
469		if err != nil {
470			return
471		}
472	
473		lockfile, command := detectInstallCommand(cwd)
474		if lockfile == "" {
475			return
476		}
477	
478		changed, err := git.DiffNameOnly(preRef, "HEAD")
479		if err != nil {
480			return
481		}
482	
483		if !slices.Contains(changed, lockfile) {
484			return
485		}
486	
487		fmt.Println()
488		fmt.Printf("Lockfile changed (%s) — running install...\n", lockfile)
489		fmt.Printf("  %s %s\n", ui.Dim("$"), command)
490		if err := runShellString(cwd, command); err != nil {
491			fmt.Println()
492			ui.Warn("Install failed — run manually: %s", command)
493		}
494	}
  1	package cmd
  2	
  3	import (
  4		"fmt"
  5	
  6		"github.com/mvwi/wt/internal/git"
  7		"github.com/mvwi/wt/internal/github"
  8		"github.com/mvwi/wt/internal/ui"
  9		"github.com/spf13/cobra"
 10	)
 11	
 12	var submitCmd = &cobra.Command{
 13		Use:     "submit",
 14		GroupID: groupSync,
 15		Short:   "Rebase on base branch + push to remote",
 16		Long: `Rebase the current branch onto the base branch, then push to remote.
 17	
 18	Uses --force-with-lease for safety (fails if remote has unexpected commits).
 19	Cannot submit the base branch (use git push directly).`,
 20		Example: `  wt submit              Rebase + push current branch
 21	  wt submit --continue   Resume after resolving rebase conflicts
 22	  wt submit --abort      Abort rebase and cancel push`,
 23		RunE: runSubmit,
 24	}
 25	
 26	var (
 27		submitContinueFlag bool
 28		submitAbortFlag    bool
 29	)
 30	
 31	func init() {
 32		submitCmd.Flags().BoolVar(&submitContinueFlag, "continue", false, "resume after resolving conflicts")
 33		submitCmd.Flags().BoolVar(&submitAbortFlag, "abort", false, "abort and restore state")
 34		addOutputFlag(submitCmd)
 35		rootCmd.AddCommand(submitCmd)
 36	}
 37	
 38	// submitJSON is what submit prints with --output json.
 39	type submitJSON struct {
 40		Branch string   `json:"branch"`
 41		Pushed bool     `json:"pushed"`
 42		PR     int      `json:"pr,omitempty"`
 43		CTA    []string `json:"cta,omitempty"`
 44	}
 45	
 46	func runSubmit(cmd *cobra.Command, args []string) error {
 47		if err := startOutput(); err != nil {
 48			return err
 49		}
 50		ctx, err := newContext()
 51		if err != nil {
 52			return err
 53		}
 54	
 55		branch, err := git.CurrentBranch()
 56		if err != nil {
 57			return fmt.Errorf("not in a git repository or detached HEAD\n   Run this from inside a worktree")
 58		}
 59	
 60		if ctx.isBaseBranch(branch) {
 61			return fmt.Errorf("cannot submit the base branch (%s)\n   Switch to a feature worktree, or use git push directly", branch)
 62		}
 63	
 64		// Delegate to rebase first
 65		if err := runRebaseWith(rebaseOpts{
 66			continueRebase: submitContinueFlag,
 67			abort:          submitAbortFlag,
 68		}); err != nil {
 69			return err
 70		}
 71	
 72		// After --abort there is nothing to push. A rebase that stops on
 73		// conflicts returns an error above, so nothing is pushed then either.
 74		if submitAbortFlag {
 75			if jsonOut != nil {
 76				return printJSON(submitJSON{Branch: branch})
 77			}
 78			return nil
 79		}
 80	
 81		expectedUpstream := ctx.Config.Remote + "/" + branch
 82		actualUpstream := git.Upstream()
 83	
 84		// Push
 85		fmt.Println()
 86		head, _ := git.RevParseHead()
 87		remoteHead, _ := git.Run("rev-parse", "--verify", "--quiet", expectedUpstream)
 88		pushed := true
 89		switch {
 90		case actualUpstream == expectedUpstream && head != "" && head == remoteHead:
 91			pushed = false
 92			fmt.Printf("Nothing to push %s %s already matches your branch\n", ui.Dash, expectedUpstream)
 93		case actualUpstream == expectedUpstream:
 94			fmt.Println("Pushing to remote…")
 95			if err := git.PushForceWithLease(); err != nil {
 96				// Likely "stale info": the remote moved since we last fetched.
 97				// After the fetch, a retry overwrites those remote commits.
 98				fmt.Println()
 99				ui.Warn("Push rejected %s the remote branch has commits you haven't fetched", ui.Dash)
100				fmt.Println("  Fetching latest remote state…")
101				if fetchErr := git.Fetch(ctx.Config.Remote, branch); fetchErr != nil {
102					return fmt.Errorf("failed to fetch: %w", fetchErr)
103				}
104				if ok, err := ui.ConfirmDiscard("Overwrite the remote commits?", false); !ok {
105					if err != nil {
106						return fmt.Errorf("push rejected: %s has commits you don't have\n   Check them with: git log HEAD..%s", expectedUpstream, expectedUpstream)
107					}
108					return fmt.Errorf("push cancelled")
109				}
110				fmt.Println()
111				fmt.Println("Pushing to remote…")
112				if err := git.PushForceWithLease(); err != nil {
113					return fmt.Errorf("failed to push to remote: %w", err)
114				}
115			}
116		default:
117			fmt.Println("Pushing to remote…")
118			if actualUpstream != "" {
119				fmt.Printf("(fixing upstream: %s → %s)\n", actualUpstream, expectedUpstream)
120			} else {
121				fmt.Println("(setting upstream for new branch)")
122			}
123			if err := git.PushSetUpstream(ctx.Config.Remote); err != nil {
124				return fmt.Errorf("failed to push to remote: %w", err)
125			}
126		}
127		if pushed {
128			fmt.Println()
129			ui.Success("Submitted!")
130		}
131	
132		if git.HasChanges() {
133			fmt.Println("Note: uncommitted changes stay local. Commit them to include them.")
134		}
135	
136		if jsonOut != nil {
137			out := submitJSON{Branch: branch, Pushed: pushed}
138			if pr, err := github.GetPRForBranch(branch); err == nil && github.IsAvailable() {
139				out.CTA = []string{"gh pr create"}
140				if pr != nil {
141					out.PR, out.CTA = pr.Number, []string{"wt watch"}
142				}
143			}
144			return printJSON(out)
145		}
146	
147		if !github.IsAvailable() {
148			return nil
149		}
150		pr, err := github.GetPRForBranch(branch)
151		switch {
152		case err != nil:
153			// No PR info (e.g. not a GitHub remote); say nothing.
154		case pr == nil:
155			fmt.Println()
156			fmt.Printf("No open PR for this branch. Create one: %s\n", ui.Cyan("gh pr create"))
157			ui.PrintCTA("gh pr create")
158		case ui.IsTTY():
159			fmt.Println()
160			if ui.Confirm("Watch PR status?", true) {
161				fmt.Println()
162				return runWatch(cmd, nil)
163			}
164		default:
165			ui.PrintCTA("wt watch")
166		}
167		return nil
168	}

