  1	package cmd
  2	
  3	import (
  4		"fmt"
  5		"os"
  6		"os/exec"
  7		"path/filepath"
  8		"strings"
  9	
 10		"github.com/mattn/go-isatty"
 11		"github.com/mvwi/wt/internal/git"
 12		"github.com/mvwi/wt/internal/ui"
 13		"github.com/spf13/cobra"
 14	)
 15	
 16	const prevWorktreeStateFile = "wt-prev-worktree"
 17	
 18	var switchCmd = &cobra.Command{
 19		Use:     "switch [name]",
 20		Aliases: []string{"sw", "cd", "checkout", "co"},
 21		GroupID: groupWorkflow,
 22		Short:   "Switch to a worktree",
 23		Long: `Switch to a different worktree.
 24	
 25	Without arguments, opens an interactive picker (requires fzf).
 26	With a name, resolves the worktree using fuzzy matching.
 27	Use "-" to switch back to the previous worktree.
 28	
 29	Resolution order:
 30	  1. Exact match: wt-<repo>-<name>
 31	  2. Main repo: 'main', base branch name, or repo name
 32	  3. Branch name: exact match against the git branch
 33	  4. Suffix match: any worktree ending with -<name>
 34	  5. Fuzzy match: worktree or branch containing the search term
 35	
 36	If a step matches more than one worktree, wt opens fzf on just those
 37	(or lists them when fzf or a terminal isn't available).`,
 38		Example: `  wt switch           Interactive picker (requires fzf)
 39	  wt switch sidebar   Switch to "sidebar" worktree (fuzzy match)
 40	  wt switch -         Switch back to previous worktree
 41	  wt switch main      Switch to main repository`,
 42		Args:              cobra.MaximumNArgs(1),
 43		ValidArgsFunction: completeWorktreeNames,
 44		RunE:              runSwitch,
 45	}
 46	
 47	func init() {
 48		addOutputFlag(switchCmd)
 49		rootCmd.AddCommand(switchCmd)
 50	}
 51	
 52	func runSwitch(cmd *cobra.Command, args []string) error {
 53		if err := startOutput(); err != nil {
 54			return err
 55		}
 56		ctx, err := newContext()
 57		if err != nil {
 58			return err
 59		}
 60	
 61		worktrees, err := git.ListWorktrees()
 62		if err != nil {
 63			return err
 64		}
 65	
 66		cwd, err := os.Getwd()
 67		if err != nil {
 68			return fmt.Errorf("cannot determine current directory: %w", err)
 69		}
 70	
 71		// Handle "wt switch -" — toggle to previous worktree
 72		if len(args) == 1 && args[0] == "-" {
 73			return switchPrevious(ctx, cwd)
 74		}
 75	
 76		// No args: interactive fzf picker
 77		if len(args) == 0 {
 78			return switchInteractive(ctx, worktrees, cwd)
 79		}
 80	
 81		return switchByName(ctx, worktrees, cwd, args[0])
 82	}
 83	
 84	func switchPrevious(ctx *cmdContext, cwd string) error {
 85		prev, err := git.ReadStateFile(prevWorktreeStateFile)
 86		if err != nil {
 87			return fmt.Errorf("no previous worktree to switch to\n   Use wt switch <name> to specify one")
 88		}
 89	
 90		prev = strings.TrimSpace(prev)
 91		if !isDir(prev) {
 92			return fmt.Errorf("previous worktree no longer exists: %s\n   It may have been closed. Run wt list to see available worktrees", prev)
 93		}
 94	
 95		return finishSwitch(ctx, cwd, prev)
 96	}
 97	
 98	func savePreviousWorktree(cwd string) {
 99		_ = git.SaveStateFile(prevWorktreeStateFile, cwd)
100	}
101	
102	func switchInteractive(ctx *cmdContext, worktrees []git.Worktree, cwd string) error {
103		if jsonOut != nil {
104			return fmt.Errorf("no worktree name given, and --output json never opens the picker\n   Run wt switch <name> --output json")
105		}
106		if _, err := exec.LookPath("fzf"); err != nil {
107			return fmt.Errorf("no worktree name given, and fzf isn't installed for the picker\n   Run wt switch <name>, or install fzf (brew install fzf)")
108		}
109	
110		target, err := pickWorktree(ctx, worktrees, cwd, "")
111		if err != nil {
112			return err
113		}
114		if target == "" {
115			fmt.Println("Cancelled")
116			return nil
117		}
118	
119		return finishSwitch(ctx, cwd, target)
120	}
121	
122	// pickWorktree opens fzf over worktrees, starting with query typed in.
123	// Returns "" when the user cancels.
124	func pickWorktree(ctx *cmdContext, worktrees []git.Worktree, cwd, query string) (string, error) {
125		var lines []string
126		for _, wt := range worktrees {
127			short := ctx.shortName(wt.Path)
128			branch, _ := git.CurrentBranchIn(wt.Path)
129			marker := "  "
130			if wt.Path == cwd || isSubpath(cwd, wt.Path) {
131				marker = ui.Current + " "
132			}
133			lines = append(lines, fmt.Sprintf("%s%s|%s|%s", marker, short, branch, wt.Path))
134		}
135	
136		fzfCmd := exec.Command("fzf", "--ansi", "--no-sort", "--reverse",
137			"--prompt=Switch to: ",
138			"--header=↑↓ navigate  enter select  esc cancel",
139			"--delimiter=|",
140			"--with-nth=1,2",
141			"--preview-window=hidden",
142			"--query="+query)
143		fzfCmd.Stdin = strings.NewReader(strings.Join(lines, "\n"))
144		fzfCmd.Stderr = os.Stderr
145	
146		out, err := fzfCmd.Output()
147		if err != nil {
148			if exitErr, ok := err.(*exec.ExitError); ok {
149				// exit code 130 = interrupted (Ctrl-C/Esc), 1 = no match
150				if exitErr.ExitCode() == 130 || exitErr.ExitCode() == 1 {
151					return "", nil
152				}
153			}
154			return "", fmt.Errorf("fzf error: %w", err)
155		}
156	
157		parts := strings.Split(strings.TrimSpace(string(out)), "|")
158		if len(parts) < 3 {
159			return "", fmt.Errorf("unexpected fzf output")
160		}
161		return parts[2], nil
162	}
163	
164	func switchByName(ctx *cmdContext, worktrees []git.Worktree, cwd, name string) error {
165		target, _, err := resolveWorktree(ctx, worktrees, name)
166		if err != nil {
167			return err
168		}
169		if target == "" {
170			return fmt.Errorf("worktree not found: %s\n   Run wt list to see available worktrees", name)
171		}
172	
173		return finishSwitch(ctx, cwd, target)
174	}
175	
176	// finishSwitch records where we came from, hands target to the shell
177	// wrapper, then prints the summary or JSON.
178	func finishSwitch(ctx *cmdContext, cwd, target string) error {
179		savePreviousWorktree(cwd)
180		ui.PrintCdHint(target)
181		if jsonOut == nil {
182			showSwitchSummary(target, ctx)
183			return nil
184		}
185	
186		branch, _ := git.CurrentBranchIn(target)
187		var cta []string
188		if !ctx.isBaseBranch(branch) {
189			cta = []string{"wt init"}
190			if ab, err := git.GetAheadBehindIn(target, ctx.baseRef()); err == nil && ab.Behind > 0 {
191				cta = []string{"wt rebase", "wt init"}
192			}
193		}
194		return printJSON(worktreeJSON{
195			Name:   ctx.shortName(target),
196			Path:   target,
197			Branch: branch,
198			Base:   ctx.Config.BaseBranch,
199			PR:     readPRCache()[ctx.MainWorktree][branch].Number,
200			CTA:    cta,
201		})
202	}
