 14	var closeCmd = &cobra.Command{
 15		Use:     "close [name]",
 16		Aliases: []string{"rm"},
 17		GroupID: groupManage,
 18		Short:   "Close and clean up a worktree",
 19		Long: `Close a worktree by removing the directory and deleting the local branch.
 20	
 21	Without arguments, closes the current worktree.
 22	With a name, closes the specified worktree.
 23	
 24	Safety checks:
 25	  - Asks before discarding uncommitted changes or unpushed commits
 26	    (--yes does not skip this; --force does)
 27	  - Warns if PR is still open
 28	  - Cannot close the main repository worktree`,
 29		Example: `  wt close                 Close current worktree
 30	  wt close sidebar         Close the "sidebar" worktree
 31	  wt close sidebar --yes   Skip prompts that lose no work
 32	  wt close sidebar --force Discard uncommitted changes and unpushed commits`,
 33		Args:              cobra.MaximumNArgs(1),
 34		ValidArgsFunction: completeWorktreeNames,
