 40	func init() {
 41		closeCmd.Flags().BoolVarP(&closeForceFlag, "force", "f", false, "discard uncommitted changes and unpushed commits")
 42		addOutputFlag(closeCmd)
 43		rootCmd.AddCommand(closeCmd)
