 52	func runSwitch(cmd *cobra.Command, args []string) error {
 53		if err := startOutput(); err != nil {
 54			return err
 55		}
 56		ctx, err := newContext()
 57		if err != nil {
 58			return err
 59		}
 60	
 61		worktrees, err := git.ListWorktrees()
 62		if err != nil {
 63			return err
 64		}
 65	
 66		cwd, err := os.Getwd()
 67		if err != nil {
 68			return fmt.Errorf("cannot determine current directory: %w", err)
 69		}
 70	
 71		// Handle "wt switch -" — toggle to previous worktree
 72		if len(args) == 1 && args[0] == "-" {
 73			return switchPrevious(ctx, cwd)
 74		}
 75	
 76		// No args: interactive fzf picker
 77		if len(args) == 0 {
