122	// pickWorktree opens fzf over worktrees, starting with query typed in.
123	// Returns "" when the user cancels.
124	func pickWorktree(ctx *cmdContext, worktrees []git.Worktree, cwd, query string) (string, error) {
125		var lines []string
126		for _, wt := range worktrees {
127			short := ctx.shortName(wt.Path)
128			branch, _ := git.CurrentBranchIn(wt.Path)
129			marker := "  "
130			if wt.Path == cwd || isSubpath(cwd, wt.Path) {
131				marker = ui.Current + " "
132			}
133			lines = append(lines, fmt.Sprintf("%s%s|%s|%s", marker, short, branch, wt.Path))
134		}
135	
136		fzfCmd := exec.Command("fzf", "--ansi", "--no-sort", "--reverse",
137			"--prompt=Switch to: ",
138			"--header=↑↓ navigate  enter select  esc cancel",
139			"--delimiter=|",
140			"--with-nth=1,2",
141			"--preview-window=hidden",
142			"--query="+query)
143		fzfCmd.Stdin = strings.NewReader(strings.Join(lines, "\n"))
144		fzfCmd.Stderr = os.Stderr
145	
146		out, err := fzfCmd.Output()
147		if err != nil {
148			if exitErr, ok := err.(*exec.ExitError); ok {
149				// exit code 130 = interrupted (Ctrl-C/Esc), 1 = no match
150				if exitErr.ExitCode() == 130 || exitErr.ExitCode() == 1 {
151					return "", nil
152				}
153			}
154			return "", fmt.Errorf("fzf error: %w", err)
155		}
156	
157		parts := strings.Split(strings.TrimSpace(string(out)), "|")
158		if len(parts) < 3 {
159			return "", fmt.Errorf("unexpected fzf output")
160		}
161		return parts[2], nil
162	}
