204	// resolveWorktree finds a worktree path by name using the resolution chain.
205	// Returns (path, fuzzy, nil) on success — fuzzy=true when the match came from
206	// the substring-contains step (step 5), meaning the caller should confirm
207	// before destructive actions. Returns ("", false, nil) when no match is found.
208	// When several worktrees match, it opens fzf on them if it can, and
209	// otherwise returns an error that lists them.
210	func resolveWorktree(ctx *cmdContext, worktrees []git.Worktree, name string) (string, bool, error) {
211		matches, fuzzy := matchWorktrees(ctx, worktrees, name)
212		switch len(matches) {
213		case 0:
214			return "", false, nil
215		case 1:
216			if fuzzy {
217				ui.DimF("Fuzzy matched: %s → %s\n", name, ctx.shortName(matches[0].Path))
218			}
219			return matches[0].Path, fuzzy, nil
220		}
221	
222		_, fzfErr := exec.LookPath("fzf")
223		if fzfErr == nil && jsonOut == nil && isatty.IsTerminal(os.Stdin.Fd()) {
224			target, err := pickWorktree(ctx, matches, "", name)
225			if err != nil {
226				return "", false, err
227			}
228			if target == "" {
229				fmt.Println("Cancelled")
230				return "", false, errSilent
231			}
232			return target, false, nil
233		}
234	
235		var names []string
236		for _, m := range matches {
237			names = append(names, "     "+ctx.shortName(m.Path))
238		}
239		return "", false, fmt.Errorf("%q matches more than one worktree:\n%s\n   Use a longer name", name, strings.Join(names, "\n"))
240	}
241	
242	// matchWorktrees returns the worktrees that match name at the first step of
243	// the resolution chain that matches any. fuzzy is true for step 5 matches.
244	func matchWorktrees(ctx *cmdContext, worktrees []git.Worktree, name string) ([]git.Worktree, bool) {
245		// 1. Exact match with configured prefix
246		if exact := ctx.worktreePath(name); isDir(exact) {
247			return []git.Worktree{{Path: exact}}, false
248		}
249	
250		// 2. Main repo match (base branch name, "main", "master", or repo name)
251		if name == ctx.RepoName || ctx.isBaseBranch(name) {
252			return []git.Worktree{{Path: ctx.MainWorktree}}, false
253		}
254	
255		// 3. Branch name match (exact match against git branch)
256		for _, wt := range worktrees {
257			if wt.Branch == name {
258				return []git.Worktree{wt}, false
259			}
260		}
261	
262		// 4. Suffix match
263		var matches []git.Worktree
264		for _, wt := range worktrees {
265			base := filepath.Base(wt.Path)
266			if strings.HasSuffix(base, "-"+name) || strings.HasSuffix(base, "/"+name) {
267				matches = append(matches, wt)
268			}
269		}
270		if len(matches) > 0 {
271			return matches, false
272		}
273	
274		// 5. Fuzzy match (contains) — checks both short name and branch
275		nameLower := strings.ToLower(name)
276		for _, wt := range worktrees {
277			short := ctx.shortName(wt.Path)
278			if strings.Contains(strings.ToLower(short), nameLower) ||
279				strings.Contains(strings.ToLower(wt.Branch), nameLower) {
280				matches = append(matches, wt)
281			}
282		}
283		return matches, true
284	}
