286	func showSwitchSummary(path string, ctx *cmdContext) {
287		short := ctx.shortName(path)
288		branch, _ := git.CurrentBranchIn(path)
289		isBase := ctx.isBaseBranch(branch)
290	
291		fmt.Printf("%s %s", ui.Yellow(ui.Current), short)
292	
293		if branch != short && !isBase {
294			fmt.Printf("  %s", ui.Dim(branch))
295		}
296	
297		isBehind := false
298		if !isBase {
299			ab, err := git.GetAheadBehindIn(path, ctx.baseRef())
300			if err == nil {
301				if ab.Behind > 0 {
302					fmt.Printf("  %s", ui.Yellow(fmt.Sprintf("⚠ %d behind", ab.Behind)))
303					isBehind = true
304				} else if ab.Ahead > 0 {
