 54	func runClose(cmd *cobra.Command, args []string) error {
 55		if err := startOutput(); err != nil {
 56			return err
 57		}
 58		ctx, err := newContext()
 59		if err != nil {
 60			return err
 61		}
 62	
 63		cwd, err := os.Getwd()
 64		if err != nil {
 65			return fmt.Errorf("cannot determine current directory: %w", err)
 66		}
 67		worktrees, err := git.ListWorktrees()
 68		if err != nil {
 69			return err
 70		}
 71	
 72		// Determine target
 73		var targetPath, targetBranch string
 74	
 75		if len(args) > 0 {
 76			var (
 77				fuzzy      bool
 78				resolveErr error
 79			)
 80			targetPath, fuzzy, resolveErr = resolveWorktree(ctx, worktrees, args[0])
 81			if resolveErr != nil {
 82				return resolveErr
 83			}
 84			if targetPath == "" {
 85				return fmt.Errorf("worktree not found: %s\n   Run wt list to see available worktrees", args[0])
 86			}
 87			if fuzzy {
 88				if !ui.Confirm(fmt.Sprintf("Close %s?", ctx.shortName(targetPath)), false) {
 89					return cancelled(nil)
 90				}
 91			}
 92		} else {
 93			// Close current worktree
 94			if cwd == ctx.MainWorktree || isSubpath(cwd, ctx.MainWorktree) {
 95				return fmt.Errorf("cannot close the main repository worktree\n   Specify a worktree name: wt close <name>")
 96			}
 97			targetPath = cwd
 98		}
 99	
100		if targetPath == ctx.MainWorktree {
101			return fmt.Errorf("cannot close the main repository worktree")
102		}
103	
104		targetBranch, _ = git.CurrentBranchIn(targetPath)
105	
106		// Safety: uncommitted changes
107		if git.HasChangesIn(targetPath) {
108			ui.Warn("Worktree has uncommitted changes:")
109			short, _ := git.StatusShortIn(targetPath)
110			fmt.Println(short)
111			fmt.Println()
112			if ok, err := ui.ConfirmDiscard("Discard changes and close?", closeForceFlag); !ok {
113				return cancelled(err)
114			}
115		}
116	
117		// Safety: unpushed commits
118		if unpushed := git.UnpushedCountIn(targetPath); unpushed > 0 {
119			ui.Warn("Branch has %d unpushed commit(s)", unpushed)
120			if ok, err := ui.ConfirmDiscard("Discard commits and close?", closeForceFlag); !ok {
121				return cancelled(err)
122			}
123		}
124	
125		// Safety: open PR
126		if github.IsAvailable() && targetBranch != "" {
127			pr, err := github.GetPRForBranch(targetBranch)
128			if err != nil && !isNotGitHubRemote(err) {
129				fmt.Fprintln(os.Stderr, ui.Dim("Skipped the open-PR check: "+firstLine(err.Error())))
130			}
131			if pr != nil && pr.State == "OPEN" {
132				ui.Warn("PR #%d is still open", pr.Number)
133				if !ui.Confirm("Close worktree anyway?", false) {
134					return cancelled(nil)
135				}
136			}
137		}
138	
139		warnRepoHooks(ctx)
140		// Read the env now: the index file goes away with the worktree.
141		var hookEnv []string
142		if len(ctx.Config.Hooks.PreClose)+len(ctx.Config.Hooks.PostClose) > 0 {
143			hookEnv = worktreeEnv(worktreeVars(ctx, targetPath))
144		}
145		if err := runHooks("pre_close", ctx.Config.Hooks.PreClose, targetPath, hookEnv); err != nil {
146			return fmt.Errorf("%w\n   Close cancelled", err)
147		}
148	
149		fmt.Printf("Closing worktree: %s\n", targetPath)
150		fmt.Printf("Branch: %s\n", targetBranch)
151		fmt.Println()
152	
153		// Check if we need to cd out before removal
154		needsCd := cwd == targetPath || isSubpath(cwd, targetPath)
155	
156		// Remove worktree
157		if err := git.RemoveWorktree(targetPath); err != nil {
158			return fmt.Errorf("failed to remove worktree: %w", err)
159		}
160	
161		// Our cwd may be gone now, and git refuses to run from a deleted dir.
162		if err := os.Chdir(ctx.MainWorktree); err != nil {
163			return fmt.Errorf("cannot enter main worktree: %w", err)
164		}
165	
166		// cd out after successful removal
167		if needsCd {
168			ui.PrintCdHint(ctx.MainWorktree)
169			fmt.Printf("Moved to main repo: %s\n", ctx.MainWorktree)
170		}
171	
172		if err := runHooks("post_close", ctx.Config.Hooks.PostClose, ctx.MainWorktree, hookEnv); err != nil {
173			ui.Warn("%v", err)
174		}
175	
176		// Delete local branch
177		branchKept, branchDeleted := false, false
178		if targetBranch != "" && git.BranchExists(targetBranch) {
179			if err := git.DeleteBranch(targetBranch); err != nil {
180				ui.Warn("Could not delete local branch %s: %v", targetBranch, err)
181				branchKept = true
182			} else {
183				ui.Success("Deleted local branch: %s", targetBranch)
184				branchDeleted = true
185			}
186		}
187	
188		fmt.Println()
189		if branchKept {
190			ui.Warn("Closed worktree, but branch %s is still there", targetBranch)
191		} else {
192			ui.Success("Closed worktree")
193		}
194		ui.PrintCTA("wt list")
195		if jsonOut != nil {
196			return printJSON(closeJSON{Name: ctx.shortName(targetPath), Path: targetPath, Branch: targetBranch, BranchDeleted: branchDeleted})
197		}
198		return nil
199	}
