 40	type staleWorktree struct {
 41		Path   string
 42		Branch string
 43		Reason string
 44	}
 45	
 46	func runPrune(cmd *cobra.Command, args []string) error {
 47		ctx, err := newContext()
 48		if err != nil {
 49			return err
 50		}
 51	
 52		cwd, err := os.Getwd()
 53		if err != nil {
 54			return fmt.Errorf("cannot determine current directory: %w", err)
 55		}
 56	
 57		worktrees, err := git.ListWorktrees()
 58		if err != nil {
 59			return err
 60		}
 61	
 62		// Candidates: feature worktrees other than main and the current one.
 63		var candidates []git.Worktree
 64		var branches []string
 65		for _, wt := range worktrees {
 66			if wt.Path == ctx.MainWorktree || wt.Path == cwd || isSubpath(cwd, wt.Path) {
 67				continue
 68			}
 69			branch := wt.Branch
 70			if branch == "" {
 71				branch, _ = git.CurrentBranchIn(wt.Path)
 72			}
 73			if ctx.isBaseBranch(branch) {
 74				continue
 75			}
 76			candidates = append(candidates, git.Worktree{Path: wt.Path, Branch: branch})
 77			branches = append(branches, branch)
 78		}
 79	
 80		spin := ui.NewSpinner("Scanning for stale worktrees")
 81	
 82		reasons, partial, ghErr := prReasons(branches)
 83		local := !github.IsAvailable() || ghErr != nil
 84		if local {
 85			reasons, err = mergedReasons(ctx, branches)
 86			if err != nil {
 87				spin.Stop()
 88				return err
 89			}
 90		}
 91	
 92		var stale []staleWorktree
 93		var skippedDirty []staleWorktree
 94	
 95		for _, wt := range candidates {
 96			reason := reasons[wt.Branch]
 97			if reason == "" {
 98				continue
 99			}
100	
101			// Stale but has uncommitted changes — track separately
102			if git.HasChangesIn(wt.Path) {
103				skippedDirty = append(skippedDirty, staleWorktree{wt.Path, wt.Branch, reason})
104				continue
105			}
106	
107			stale = append(stale, staleWorktree{wt.Path, wt.Branch, reason})
108		}
109	
110		git.PruneWorktrees()
111	
112		spin.Stop()
113	
114		if local {
115			why := "gh is not installed"
116			switch {
117			case ghErr != nil && isNotGitHubRemote(ghErr):
118				why = "the remote isn't on GitHub"
119			case ghErr != nil:
120				why = fmt.Sprintf("could not fetch PR data (%s)", ui.Truncate(ghErr.Error(), 80))
121			}
122			ui.Warn("%s, so only branches merged into %s count as stale.", why, ctx.baseRef())
123			fmt.Println("   Squash-merged branches can't be detected without gh.")
124			fmt.Println()
125		} else if partial {
126			ui.Warn("Could not fetch some PR data %s results may be incomplete", ui.Dash)
127		}
128	
129		if len(stale) == 0 {
130			ui.Success("No stale worktrees found")
131			printSkippedDirty(skippedDirty)
132			return nil
133		}
134	
135		fmt.Printf("Found %d stale worktree(s):\n\n", len(stale))
136	
137		// Dry-run: list what would be removed and exit
138		if pruneDryRun {
139			for _, s := range stale {
140				short := filepath.Base(s.Path)
141				fmt.Printf("  %s  %s\n", ui.Yellow(short), s.Reason)
142				fmt.Printf("     %s\n", ui.Dim(s.Branch))
143			}
144			printSkippedDirty(skippedDirty)
145			fmt.Println()
146			fmt.Println("No changes made (--dry-run)")
147			return nil
148		}
149	
150		// Phase 1: collect decisions
151		toRemove, cancelled, err := selectPruneTargets(stale)
152		if err != nil {
153			return err
154		}
155		if cancelled {
156			fmt.Println("Cancelled")
157			return nil
158		}
159	
160		// Phase 2: execute removals
161		if len(toRemove) == 0 {
162			fmt.Println("No worktrees to remove")
163			return nil
164		}
165	
166		fmt.Printf("Removing %d worktree(s)...\n", len(toRemove))
167	
168		removedCount := 0
169		for _, i := range toRemove {
170			s := stale[i]
171			short := filepath.Base(s.Path)
172	
173			if err := git.RemoveWorktree(s.Path); err != nil {
174				fmt.Printf("  %s %s (failed)\n", ui.Red(ui.Fail), short)
175				continue
176			}
177	
178			if git.BranchExists(s.Branch) {
179				_ = git.DeleteBranch(s.Branch)
180			}
181			fmt.Printf("  %s %s\n", ui.Green(ui.Pass), short)
182			removedCount++
183		}
184	
185		fmt.Println()
186		ui.Success("Removed %d worktree(s)", removedCount)
187		printSkippedDirty(skippedDirty)
188		ui.PrintCTA("wt list")
189		return nil
190	}
191	
192	// prReasons maps each branch with a merged or closed PR to a reason. partial
193	// is true when one of the two lookups failed; err is set only when both did.
194	func prReasons(branches []string) (reasons map[string]string, partial bool, err error) {
195		reasons = make(map[string]string)
196		if !github.IsAvailable() || len(branches) == 0 {
197			return reasons, false, nil
198		}
199	
200		var mergedPRs, closedPRs []github.PR
201		var mergedErr, closedErr error
202		var wg sync.WaitGroup
203		wg.Add(2)
204		go func() { defer wg.Done(); mergedPRs, mergedErr = github.ListPRs("merged", branches...) }()
205		go func() { defer wg.Done(); closedPRs, closedErr = github.ListPRs("closed", branches...) }()
206		wg.Wait()
207	
208		if mergedErr != nil && closedErr != nil {
209			return nil, false, mergedErr
210		}
211	
212		for _, b := range branches {
213			if pr := github.FindPRForBranch(mergedPRs, b); pr != nil {
214				reasons[b] = fmt.Sprintf("PR #%d merged", pr.Number)
215			} else if pr := github.FindPRForBranch(closedPRs, b); pr != nil {
216				reasons[b] = fmt.Sprintf("PR #%d closed", pr.Number)
217			}
218		}
219		return reasons, mergedErr != nil || closedErr != nil, nil
220	}
221	
222	// mergedReasons is the fallback without gh: a branch is stale when the base
223	// branch already contains it. Branches with no commits since creation are
224	// skipped, since git also counts them as merged.
225	func mergedReasons(ctx *cmdContext, branches []string) (map[string]string, error) {
226		_ = git.Fetch(ctx.Config.Remote, ctx.Config.BaseBranch) // best effort; a stale base only misses branches
227		merged, err := git.MergedBranches(ctx.baseRef())
228		if err != nil {
229			return nil, err
230		}
231		reasons := make(map[string]string)
232		for _, b := range branches {
233			if merged[b] && git.BranchMoved(b) {
234				reasons[b] = "merged into " + ctx.baseRef()
235			}
236		}
237		return reasons, nil
238	}
239	
240	// selectPruneTargets returns the indices of stale worktrees the user wants to remove.
241	//
242	//   - With --yes: all stale worktrees.
243	//   - With a TTY: interactive multi-select via the TUI picker.
244	//   - Without a TTY and no --yes: nothing selected (preserves existing
245	//     non-interactive behavior, where each Confirm() returned false).
246	func selectPruneTargets(stale []staleWorktree) (indices []int, cancelled bool, err error) {
247		if ui.YesFlag {
248			all := make([]int, len(stale))
249			for i := range stale {
250				all[i] = i
251			}
252			return all, false, nil
253		}
254	
255		if !ui.IsTTY() {
256			return nil, false, nil
257		}
258	
259		items := make([]tui.PruneItem, len(stale))
260		for i, s := range stale {
261			items[i] = tui.PruneItem{Path: s.Path, Branch: s.Branch, Reason: s.Reason}
262		}
263	
264		result, err := tui.RunPrunePicker(items)
265		if err != nil {
266			return nil, false, err
267		}
268		return result.Selected, result.Cancelled, nil
269	}
270	
271	func printSkippedDirty(skipped []staleWorktree) {
272		if len(skipped) == 0 {
273			return
274		}
275		fmt.Println()
276		for _, s := range skipped {
277			short := filepath.Base(s.Path)
278			fmt.Printf("  %s %s — %s, skipped (has uncommitted changes)\n", ui.Yellow("!"), short, s.Reason)
279		}
280	}

