  1	package cmd
  2	
  3	import (
  4		"fmt"
  5		"os"
  6		"os/exec"
  7		"os/signal"
  8		"runtime"
  9		"time"
 10	
 11		"github.com/mvwi/wt/internal/git"
 12		"github.com/mvwi/wt/internal/github"
 13		"github.com/mvwi/wt/internal/ui"
 14		"github.com/spf13/cobra"
 15	)
 16	
 17	const watchCheckColWidth = 28
 18	
 19	var watchCmd = &cobra.Command{
 20		Use:     "watch [branch or PR number]",
 21		GroupID: groupSync,
 22		Short:   "Watch PR until mergeable or blocked",
 23		Long: `Poll the GitHub API every 15 seconds, showing a live table with CI and
 24	review status, and exit when the PR reaches a terminal state.
 25	
 26	Optionally pass a branch name or PR number to watch any PR in the repo,
 27	even if the branch isn't checked out locally.
 28	
 29	Exits successfully when the PR is ready to merge. Exits with an error on
 30	merge conflicts, CI failures, or changes requested.
 31	
 32	Requires the GitHub CLI (gh) to be installed.`,
 33		Example: `  wt watch           Watch PR for current branch
 34	  wt watch sidebar   Watch PR for "sidebar" worktree
 35	  wt watch 42        Watch PR #42
 36	  wt watch --merge   Watch and auto-merge when ready`,
 37		Args:              cobra.MaximumNArgs(1),
 38		ValidArgsFunction: completeWorktreeNames,
 39		RunE:              runWatch,
 40	}
 41	
 42	var watchMergeFlag bool
 43	
 44	func init() {
 45		watchCmd.Flags().BoolVar(&watchMergeFlag, "merge", false, "merge PR automatically when ready")
 46		rootCmd.AddCommand(watchCmd)
 47	}
 48	
 49	// isAllDigits reports whether s is non-empty and contains only ASCII digits.
 50	func isAllDigits(s string) bool {
 51		if s == "" {
 52			return false
 53		}
 54		for _, c := range s {
 55			if c < '0' || c > '9' {
 56				return false
 57			}
 58		}
 59		return true
 60	}
 61	
 62	// watchResult describes why the watch loop ended.
 63	type watchResult struct {
 64		success bool
 65		message string
 66	}
 67	
 68	func runWatch(cmd *cobra.Command, args []string) error {
 69		if !github.IsAvailable() {
 70			return fmt.Errorf("gh CLI is required for this command (brew install gh)")
 71		}
 72	
 73		ctx, err := newContext()
 74		if err != nil {
 75			return err
 76		}
 77	
 78		// Resolve what to watch: PR number, worktree name, or current branch
 79		var ref string
 80		if len(args) > 0 {
 81			if isAllDigits(args[0]) {
 82				// PR number — use directly
 83				ref = args[0]
 84			} else {
 85				// Fuzzy-match against worktrees
 86				worktrees, err := git.ListWorktrees()
 87				if err != nil {
 88					return err
 89				}
 90				target, _, resolveErr := resolveWorktree(ctx, worktrees, args[0])
 91				if resolveErr != nil {
 92					return resolveErr
 93				}
 94				if target == "" {
 95					return fmt.Errorf("worktree not found: %s\n   Run wt list to see available worktrees", args[0])
 96				}
 97				branch, err := git.CurrentBranchIn(target)
 98				if err != nil {
 99					return fmt.Errorf("could not determine branch for worktree: %s", args[0])
100				}
101				ref = branch
102			}
103		} else {
104			branch, err := git.CurrentBranch()
105			if err != nil {
106				return fmt.Errorf("not in a git repository or detached HEAD\n   Run this from inside a worktree")
107			}
108	
109			if ctx.isBaseBranch(branch) {
110				return fmt.Errorf("can't watch the base branch (%s) %s it has no associated PR\n   Switch to a feature worktree first", branch, ui.Dash)
111			}
112			ref = branch
113		}
114	
115		// Initial fetch to verify PR exists
116		ws, err := github.GetWatchStatus(ref)
117		if err != nil {
118			return fmt.Errorf("could not fetch PR status for %s: %w", ref, err)
119		}
120		cacheWatchStatus(ws)
121	
122		// Resolve merge method once up front (2 gh calls — no need to repeat per poll)
123		mergeMethod := ""
124		if watchMergeFlag {
125			m, err := github.GetDefaultMergeMethod()
126			if err != nil {
127				ui.Warn("Could not determine merge method, defaulting to merge: %v", err)
128				m = "merge"
129			}
130			mergeMethod = m
131		}
132	
133		// Print header (once)
134		printWatchHeader(ws)
135	
136		// Check if already resolved
137		if res := checkResolved(ws); res != nil {
138			renderWatchTable(ws)
139			printWatchVerdict(ws)
140			if err := mergeIfRequested(ws, mergeMethod); err != nil {
141				return err
142			}
143			printWatchCTA(ws)
144			if res.success {
145				return nil
146			}
147			return errSilent
148		}
149	
150		// Set up Ctrl+C handler
151		sigCh := make(chan os.Signal, 1)
152		signal.Notify(sigCh, os.Interrupt)
153		defer signal.Stop(sigCh)
154	
155		// Poll loop
156		ticker := time.NewTicker(15 * time.Second)
157		defer ticker.Stop()
158	
159		tableLines := renderWatchTable(ws)
160		spin := ui.NewSpinnerRich(buildSpinnerMessage(ws))
161	
162		for {
163			select {
164			case <-sigCh:
165				spin.Stop()
166				fmt.Println()
167				return nil
168	
169			case <-ticker.C:
170				ws, err = github.GetWatchStatus(ref)
171				if err != nil {
172					spin.Stop()
173					return fmt.Errorf("failed to fetch PR status: %w", err)
174				}
175				cacheWatchStatus(ws)
176	
177				// Clear and redraw
178				spin.Stop()
179				ui.ClearLines(tableLines)
180	
181				if res := checkResolved(ws); res != nil {
182					renderWatchTable(ws)
183					printWatchVerdict(ws)
184					if err := mergeIfRequested(ws, mergeMethod); err != nil {
185						return err
186					}
187					printWatchCTA(ws)
188					sendNotification(ws)
189					if res.success {
190						return nil
191					}
192					return errSilent
193				}
194	
195				tableLines = renderWatchTable(ws)
196				spin = ui.NewSpinnerRich(buildSpinnerMessage(ws))
197			}
198		}
199	}
200	
201	// checkResolved returns a result if the PR has reached a terminal state, or nil to keep polling.
202	func checkResolved(ws *github.WatchStatus) *watchResult {
203		// Already merged
204		if ws.State == "MERGED" {
205			return &watchResult{success: true, message: "Already merged"}
206		}
207	
208		// Closed without merge
209		if ws.State == "CLOSED" {
210			return &watchResult{success: false, message: "PR was closed"}
211		}
212	
213		// Draft PR — always terminal, but verdict prints all concurrent issues
214		if ws.MergeStateStatus == "DRAFT" {
215			return &watchResult{success: false, message: "PR is a draft " + ui.Dash + " mark as ready first"}
216		}
217	
218		// Ready to merge
219		if ws.MergeStateStatus == "CLEAN" {
220			return &watchResult{success: true, message: "Ready to merge"}
221		}
222	
223		// Merge conflict
224		if ws.Mergeable == "CONFLICTING" {
225			return &watchResult{success: false, message: "Merge conflict " + ui.Dash + " run wt rebase"}
226		}
227	
228		// Changes requested
229		if ws.ReviewDecision == "CHANGES_REQUESTED" {
230			return &watchResult{success: false, message: "Changes requested"}
231		}
232	
233		// All CI resolved with failures
234		cs := ws.GetCISummary()
235		if cs.Total > 0 && cs.Pending == 0 && cs.Fail > 0 {
236			return &watchResult{
237				success: false,
238				message: fmt.Sprintf("%d check(s) failed", cs.Fail),
239			}
240		}
241	
242		// All CI resolved, all passed, but still BLOCKED (branch protection rules)
243		if cs.Total > 0 && cs.Pending == 0 && cs.Fail == 0 && ws.MergeStateStatus == "BLOCKED" {
244			return &watchResult{success: false, message: "Blocked by branch protection"}
245		}
246	
247		return nil
248	}
249	
250	// printWatchHeader prints the PR title and branch (called once at start).
251	func printWatchHeader(ws *github.WatchStatus) {
252		fmt.Println()
253		title := ws.Title
254		if title == "" {
255			title = fmt.Sprintf("PR #%d", ws.Number)
256		} else {
257			title = fmt.Sprintf("PR #%d %s %s", ws.Number, ui.Dash, title)
258		}
259		fmt.Printf("  %s\n", ui.Bold(title))
260		fmt.Printf("  %s\n", ui.Dim(ws.HeadRefName))
261	}
262	
263	// renderWatchTable prints the CI and Review sections and returns the number of lines printed.
264	func renderWatchTable(ws *github.WatchStatus) int {
265		lines := 0
266	
267		// CI section
268		pass, fail, pending := ws.ChecksByStatus()
269		total := len(pass) + len(fail) + len(pending)
270		if total > 0 {
271			fmt.Println()
272			lines++
273	
274			fmt.Printf("  %s  %s\n", ui.Bold("CI"), ui.Dim(fmt.Sprintf("%d/%d", len(pass), total)))
275			lines++
276	
277			// Build sorted list: pass, fail, pending
278			type checkEntry struct {
279				glyph string
280				name  string
281			}
282			var entries []checkEntry
283			for _, c := range pass {
284				entries = append(entries, checkEntry{glyph: ui.Green(ui.Pass), name: c.Name})
285			}
286			for _, c := range fail {
287				entries = append(entries, checkEntry{glyph: ui.Red(ui.Fail), name: c.Name})
288			}
289			for _, c := range pending {
290				entries = append(entries, checkEntry{glyph: ui.Yellow(ui.Pending), name: c.Name})
291			}
292	
293			// Render in two columns
294			for i := 0; i < len(entries); i += 2 {
295				left := entries[i]
296				leftName := ui.Truncate(left.name, watchCheckColWidth)
297				if i+1 < len(entries) {
298					right := entries[i+1]
299					rightName := ui.Truncate(right.name, watchCheckColWidth)
300					fmt.Printf("    %s  %-*s  %s  %s\n", left.glyph, watchCheckColWidth, leftName, right.glyph, rightName)
301				} else {
302					fmt.Printf("    %s  %s\n", left.glyph, leftName)
303				}
304				lines++
305			}
306		}
307	
308		// Review section
309		items := ws.ReviewItems()
310		showReview := len(items) > 0 || ws.ReviewDecision == "REVIEW_REQUIRED"
311		if showReview {
312			fmt.Println()
313			lines++
314	
315			fmt.Printf("  %s\n", ui.Bold("Review"))
316			lines++
317	
318			if len(items) == 0 {
319				fmt.Printf("    %s  %s\n", ui.Blue(ui.Pending), ui.Dim("review required"))
320				lines++
321			} else {
322				for i := 0; i < len(items); i += 2 {
323					lg, lt := formatReviewItem(items[i])
324					if i+1 < len(items) {
325						rg, rt := formatReviewItem(items[i+1])
326						fmt.Printf("    %s  %-*s  %s  %s\n", lg, watchCheckColWidth, lt, rg, rt)
327					} else {
328						fmt.Printf("    %s  %s\n", lg, lt)
329					}
330					lines++
331				}
332			}
333		}
334	
335		fmt.Println()
336		lines++
337		return lines
338	}
339	
340	// formatReviewItem returns the glyph and text for a review item separately,
341	// so the caller can pad the text correctly (ANSI codes break %-*s alignment).
342	func formatReviewItem(item github.ReviewItem) (glyph, text string) {
343		login := ui.Truncate(item.Login, 16)
344		switch item.State {
345		case "approved":
346			return ui.Green(ui.Pass), login + "  " + ui.Dim("approved")
347		case "changes_requested":
348			return ui.Red(ui.Fail), login + "  " + ui.Dim("changes")
349		default:
350			return ui.Blue(ui.Pending), login + "  " + ui.Dim("pending")
351		}
352	}
353	
354	// buildSpinnerMessage creates a concise status message for the spinner line.
355	func buildSpinnerMessage(ws *github.WatchStatus) string {
356		cs := ws.GetCISummary()
357	
358		ciWaiting := cs.Pending > 0 || cs.Total == 0
359		reviewWaiting := ws.ReviewDecision == "REVIEW_REQUIRED"
360	
361		switch {
362		case cs.Total == 0 && ws.MergeStateStatus == "BLOCKED":
363			// Typical for fork PRs whose workflows wait for a maintainer to approve them.
364			return ui.Dim("Blocked, no checks have started " + ui.Dash + " workflows may need maintainer approval…")
365		case ciWaiting && reviewWaiting:
366			return ui.Dim("Waiting for checks and review…")
367		case ciWaiting:
368			if cs.Total > 0 {
369				noun := "checks"
370				if cs.Pending == 1 {
371					noun = "check"
372				}
373				return ui.Dim(fmt.Sprintf("Waiting for %d %s…", cs.Pending, noun))
374			}
375			return ui.Dim("Waiting for status…")
376		case reviewWaiting:
377			return ui.Dim("Waiting for review…")
378		default:
379			return ui.Dim("Waiting for status…")
380		}
381	}
382	
383	// printWatchVerdict outputs the final success/error line after resolution.
384	func printWatchVerdict(ws *github.WatchStatus) {
385		cs := ws.GetCISummary()
386	
387		// Terminal bell
388		fmt.Print("\a")
389	
390		// Draft PRs: show all concurrent issues so the user sees everything to fix
391		if ws.MergeStateStatus == "DRAFT" {
392			if ws.Mergeable == "CONFLICTING" {
393				ui.Error("Merge conflict %s run wt rebase", ui.Dash)
394			}
395			if ws.ReviewDecision == "CHANGES_REQUESTED" {
396				ui.Error("Changes requested")
397			}
398			if cs.Fail > 0 {
399				ui.Error("%d check(s) failed", cs.Fail)
400			}
401			ui.Error("PR is a draft %s mark as ready first", ui.Dash)
402			return
403		}
404	
405		switch {
406		case ws.State == "MERGED":
407			ui.Success("Already merged")
408		case ws.State == "CLOSED":
409			ui.Error("PR was closed")
410		case ws.MergeStateStatus == "CLEAN":
411			ui.Success("Ready to merge")
412		case ws.Mergeable == "CONFLICTING":
413			ui.Error("Merge conflict %s run wt rebase", ui.Dash)
414		case ws.ReviewDecision == "CHANGES_REQUESTED":
415			ui.Error("Changes requested")
416		case cs.Fail > 0:
417			ui.Error("%d check(s) failed", cs.Fail)
418		case ws.MergeStateStatus == "BLOCKED":
419			ui.Error("Blocked by branch protection")
420		}
421	}
422	
423	// mergeIfRequested merges the PR when --merge is set and the PR is CLEAN.
424	// method is the merge strategy resolved once before the poll loop.
425	func mergeIfRequested(ws *github.WatchStatus, method string) error {
426		if !watchMergeFlag || ws.MergeStateStatus != "CLEAN" {
427			return nil
428		}
429		fmt.Printf("\nMerging PR #%d (%s)...\n", ws.Number, method)
430		if err := github.MergePR(ws.Number, method); err != nil {
431			return fmt.Errorf("merge failed: %w", err)
432		}
433		fmt.Println()
434		ui.Success("Merged PR #%d", ws.Number)
435		ui.PrintCTA("wt close")
436		return nil
437	}
438	
439	// printWatchCTA emits agent call-to-action hints based on the terminal PR state.
440	func printWatchCTA(ws *github.WatchStatus) {
441		switch {
442		case ws.State == "MERGED", ws.State == "CLOSED":
443			ui.PrintCTA("wt close")
444		case ws.MergeStateStatus == "CLEAN" && !watchMergeFlag:
445			ui.PrintCTA("wt open")
446		case ws.Mergeable == "CONFLICTING":
447			ui.PrintCTA("wt rebase")
448		}
449	}
450	
451	// sendNotification sends a desktop notification on macOS.
452	func sendNotification(ws *github.WatchStatus) {
453		if runtime.GOOS != "darwin" {
454			return
455		}
456	
457		title := fmt.Sprintf("PR #%d", ws.Number)
458		var message string
459		switch {
460		case ws.State == "MERGED":
461			message = "Already merged"
462		case ws.State == "CLOSED":
463			message = "PR was closed"
464		case ws.MergeStateStatus == "CLEAN":
465			message = "Ready to merge"
466		case ws.Mergeable == "CONFLICTING":
467			message = "Merge conflict"
468		case ws.ReviewDecision == "CHANGES_REQUESTED":
469			message = "Changes requested"
470		default:
471			cs := ws.GetCISummary()
472			if cs.Fail > 0 {
473				message = fmt.Sprintf("%d check(s) failed", cs.Fail)
474			} else {
475				message = "Status resolved"
476			}
477		}
478	
479		_ = exec.Command("osascript", "-e",
480			"on run {t, m}\ndisplay notification m with title t\nend run",
481			title, message).Run()
482	}
  1	package cmd
  2	
  3	import (
  4		"encoding/json"
  5		"fmt"
  6		"os"
  7		"path/filepath"
  8		"strconv"
  9		"strings"
 10	
 11		"github.com/mvwi/wt/internal/config"
 12		"github.com/mvwi/wt/internal/git"
 13		"github.com/mvwi/wt/internal/github"
 14		"github.com/mvwi/wt/internal/ui"
 15		"github.com/spf13/cobra"
 16	)
