 18	var promptCmd = &cobra.Command{
 19		Use:   "prompt",
 20		Short: "Print a short worktree status for your shell prompt",
 21		Long: `Print a one-line status of the current worktree for a shell prompt:
 22	
 23	  login-form ⇡2 ⇣5 #123 ✓
 24	
 25	⇡ and ⇣ count commits ahead of and behind the base branch, from local refs
 26	(no fetch). The PR number and CI result come from a cache that wt list,
 27	wt dash and wt watch refresh, so wt prompt never calls gh or the network.
 28	Prints nothing outside a worktree or in the main checkout.`,
 29		Example: `  # starship.toml
 30	  [custom.wt]
 31	  command = "wt prompt"
 32	  when = true
 33	  format = "[$output]($style) "
 34	
 35	  # fish_prompt
 36	  echo -n (wt prompt)`,
 37		Args: cobra.NoArgs,
 38		RunE: func(cmd *cobra.Command, args []string) error {
 39			if s := promptSegment(); s != "" {
 40				fmt.Println(s)
 41			}
 42			return nil
 43		},
 44	}
 45	
 46	func init() {
 47		rootCmd.AddCommand(promptCmd)
 48	}
 49	
 50	// cachedPR is the open PR for a branch, as wt prompt shows it.
 51	type cachedPR struct {
 52		Number int    `json:"number"`
 53		CI     string `json:"ci,omitempty"` // pass, fail, pending, or "" for no checks
 54	}
 55	
 56	// prCache maps main worktree path → branch → open PR.
 57	type prCache map[string]map[string]cachedPR
 58	
 59	// promptSegment builds the prompt text, or "" when there is nothing to show.
 60	// It runs two git commands and reads two small files, nothing more.
 61	func promptSegment() string {
 62		out, err := git.Run("rev-parse", "--path-format=absolute", "--show-toplevel", "--git-common-dir", "--abbrev-ref", "HEAD")
 63		lines := strings.Split(out, "\n")
 64		if err != nil || len(lines) != 3 {
 65			return ""
 66		}
 67		top, branch := lines[0], lines[2]
 68		main := filepath.Dir(lines[1])
 69		if top == main {
 70			return ""
 71		}
 72	
 73		repo := filepath.Base(main)
 74		cfg, err := config.Load(main, repo)
 75		if err != nil {
 76			return ""
 77		}
 78		ctx := &cmdContext{Config: cfg, RepoName: repo, MainWorktree: main, ParentDir: filepath.Dir(main)}
 79	
 80		var ahead, behind int
 81		if counts, err := git.Run("rev-list", "--left-right", "--count", "HEAD..."+ctx.baseRef()); err == nil {
 82			if a, b, ok := strings.Cut(counts, "\t"); ok {
 83				ahead, _ = strconv.Atoi(a)
 84				behind, _ = strconv.Atoi(b)
 85			}
 86		}
 87		return formatPrompt(ctx.shortName(top), ahead, behind, readPRCache()[main][branch])
 88	}
 89	
 90	func formatPrompt(name string, ahead, behind int, pr cachedPR) string {
 91		parts := []string{name}
 92		if ahead > 0 {
 93			parts = append(parts, fmt.Sprintf("%s%d", ui.ArrowUp, ahead))
 94		}
 95		if behind > 0 {
 96			parts = append(parts, fmt.Sprintf("%s%d", ui.ArrowDown, behind))
 97		}
 98		if pr.Number > 0 {
 99			parts = append(parts, fmt.Sprintf("#%d", pr.Number))
100			switch pr.CI {
101			case "pass":
102				parts = append(parts, ui.Pass)
103			case "fail":
104				parts = append(parts, ui.Fail)
105			case "pending":
106				parts = append(parts, ui.Pending)
107			}
108		}
109		return strings.Join(parts, " ")
110	}
111	
112	func ciState(cs github.CISummary) string {
113		switch {
114		case cs.Fail > 0:
115			return "fail"
116		case cs.Pending > 0:
117			return "pending"
118		case cs.Pass > 0:
119			return "pass"
120		}
121		return ""
122	}
123	
124	func prCachePath() (string, error) {
125		dir, err := os.UserCacheDir()
126		return filepath.Join(dir, "wt", "prompt.json"), err
127	}
128	
129	func readPRCache() prCache {
130		c := prCache{}
131		if path, err := prCachePath(); err == nil {
132			if data, err := os.ReadFile(path); err == nil {
133				_ = json.Unmarshal(data, &c)
134			}
135		}
136		return c
137	}
138	
139	// cacheOpenPRs records the open PRs among branches for wt prompt and drops
140	// cached PRs for the branches that have none now. The cache is only a
141	// convenience, so errors are ignored.
142	func cacheOpenPRs(branches []string, open []github.PR) {
143		found := map[string]cachedPR{}
144		for _, pr := range open {
145			found[pr.HeadRefName] = cachedPR{Number: pr.Number, CI: ciState(pr.GetCISummary())}
146		}
147		writePRCache(branches, found)
148	}
149	
150	// cacheWatchStatus records the PR that wt watch polled.
151	func cacheWatchStatus(ws *github.WatchStatus) {
152		found := map[string]cachedPR{}
153		if ws.State == "OPEN" {
154			found[ws.HeadRefName] = cachedPR{Number: ws.Number, CI: ciState(ws.GetCISummary())}
155		}
156		writePRCache([]string{ws.HeadRefName}, found)
157	}
158	
159	func writePRCache(branches []string, found map[string]cachedPR) {
160		main, err := git.MainWorktree()
161		if err != nil {
162			return
163		}
164		path, err := prCachePath()
165		if err != nil {
166			return
167		}
168		c := readPRCache()
169		if c[main] == nil {
170			c[main] = map[string]cachedPR{}
171		}
172		for _, b := range branches {
173			if pr, ok := found[b]; ok {
174				c[main][b] = pr
175			} else {
176				delete(c[main], b)
177			}
178		}
179		data, err := json.Marshal(c)
180		if err != nil || os.MkdirAll(filepath.Dir(path), 0o755) != nil {
181			return
182		}
183		// Write then rename, so a prompt never reads half a file.
184		tmp := path + ".tmp"
185		if os.WriteFile(tmp, data, 0o644) == nil {
186			_ = os.Rename(tmp, path)
187		}
188	}

