250	// printWatchHeader prints the PR title and branch (called once at start).
251	func printWatchHeader(ws *github.WatchStatus) {
252		fmt.Println()
253		title := ws.Title
254		if title == "" {
255			title = fmt.Sprintf("PR #%d", ws.Number)
256		} else {
257			title = fmt.Sprintf("PR #%d %s %s", ws.Number, ui.Dash, title)
258		}
259		fmt.Printf("  %s\n", ui.Bold(title))
260		fmt.Printf("  %s\n", ui.Dim(ws.HeadRefName))
261	}
