 14	var editCmd = &cobra.Command{
 15		Use:     "edit [name]",
 16		GroupID: groupWorkflow,
 17		Short:   "Open a worktree in your editor",
 18		Long: `Open a worktree in your editor. Without a name, opens the current worktree.
 19	
 20	wt uses $WT_EDITOR, then $VISUAL, then the first of cursor, code or zed
 21	on your PATH. A terminal editor (vim, nvim, hx, ...) runs in the
 22	foreground inside the worktree; a GUI editor opens and wt returns at once.`,
 23		Example: `  wt edit            Open the current worktree
 24	  wt edit sidebar    Open the "sidebar" worktree
 25	  WT_EDITOR="code -n" wt edit sidebar`,
 26		Args:              cobra.MaximumNArgs(1),
 27		ValidArgsFunction: completeWorktreeNames,
 28		RunE:              runEdit,
 29	}
 30	
 31	func init() {
 32		rootCmd.AddCommand(editCmd)
 33	}
 34	
 35	func runEdit(cmd *cobra.Command, args []string) error {
 36		ctx, err := newContext()
 37		if err != nil {
 38			return err
 39		}
 40		if len(args) == 0 {
 41			top, err := git.TopLevel()
 42			if err != nil {
 43				return err
 44			}
 45			return openEditor(top)
 46		}
 47	
 48		worktrees, err := git.ListWorktrees()
 49		if err != nil {
 50			return err
 51		}
 52		path, _, err := resolveWorktree(ctx, worktrees, args[0])
 53		if err != nil {
 54			return err
 55		}
 56		if path == "" {
 57			return fmt.Errorf("worktree not found: %s\n   Run wt list to see available worktrees", args[0])
 58		}
 59		return openEditor(path)
 60	}
 61	
 62	// terminalEditors run in the foreground; anything else counts as a GUI editor.
 63	var terminalEditors = map[string]bool{
 64		"vi": true, "vim": true, "nvim": true, "hx": true, "helix": true,
 65		"nano": true, "emacs": true, "micro": true, "kak": true,
 66	}
 67	
 68	// resolveEditor picks the editor command line: $WT_EDITOR, $VISUAL, then the
 69	// first of cursor, code, zed on PATH.
 70	func resolveEditor(getenv func(string) string, lookPath func(string) (string, error)) (string, error) {
 71		for _, env := range []string{"WT_EDITOR", "VISUAL"} {
 72			if e := strings.TrimSpace(getenv(env)); e != "" {
 73				return e, nil
 74			}
 75		}
 76		for _, e := range []string{"cursor", "code", "zed"} {
 77			if _, err := lookPath(e); err == nil {
 78				return e, nil
 79			}
 80		}
 81		return "", fmt.Errorf("no editor found\n   Set $WT_EDITOR (e.g. export WT_EDITOR=code), or install cursor, code or zed")
 82	}
 83	
 84	func isTerminalEditor(editor string) bool {
 85		fields := strings.Fields(editor)
 86		return len(fields) > 0 && terminalEditors[filepath.Base(fields[0])]
 87	}
 88	
 89	// openEditor opens path in the user's editor.
 90	func openEditor(path string) error {
 91		editor, err := resolveEditor(os.Getenv, exec.LookPath)
 92		if err != nil {
 93			return err
 94		}
 95		// sh -c lets the editor setting carry flags, such as "code -n".
 96		c := exec.Command("sh", "-c", editor+` "$1"`, "sh", path)
 97		if isTerminalEditor(editor) {
 98			c.Dir = path
 99			c.Stdin, c.Stdout, c.Stderr = os.Stdin, os.Stdout, os.Stderr
100			return c.Run()
101		}
102		if err := c.Start(); err != nil {
103			return fmt.Errorf("failed to start %s: %w", editor, err)
104		}
105		fmt.Printf("Opened %s in %s\n", path, editor)
106		return nil
107	}

