 14	var moveCmd = &cobra.Command{
 15		Use:     "move <name>",
 16		Aliases: []string{"mv", "teleport", "tp"},
 17		GroupID: groupManage,
 18		Short:   "Move uncommitted changes to another worktree",
 19		Long: `Move all uncommitted changes (modified, new, deleted files) to another worktree.
 20	
 21	If the target worktree doesn't exist, offers to create a new one from the base branch.
 22	Asks before overwriting files the destination has its own changes to
 23	(--yes does not skip this; --force does).`,
 24		Example: `  wt move sidebar         Move changes to existing "sidebar" worktree
 25	  wt move new-feature     Move changes (creates worktree if needed)
 26	  wt move sidebar --yes   Skip prompts that lose no work
 27	  wt move sidebar --force Also overwrite the destination's own changes`,
 28		Args:              cobra.ExactArgs(1),
 29		ValidArgsFunction: completeWorktreeNames,
 30		RunE:              runMove,
 31	}
 32	
 33	var moveForceFlag bool
 34	
 35	func init() {
 36		moveCmd.Flags().BoolVarP(&moveForceFlag, "force", "f", false, "overwrite the destination's own changes")
 37		rootCmd.AddCommand(moveCmd)
 38	}
 39	
 40	func runMove(cmd *cobra.Command, args []string) error {
 41		ctx, err := newContext()
 42		if err != nil {
 43			return err
 44		}
 45	
 46		targetName := args[0]
 47	
 48		sourceRoot, err := git.TopLevel()
 49		if err != nil {
 50			return err
 51		}
 52	
 53		// Get changes
 54		changes, err := git.StatusPorcelain()
 55		if err != nil {
 56			return err
 57		}
 58		if len(changes) == 0 {
 59			return fmt.Errorf("no changes to move\n   Nothing modified, staged, or untracked in current worktree")
 60		}
 61	
 62		// Categorize: copy vs delete
 63		var filesToCopy, filesToDelete []string
 64		for _, c := range changes {
 65			switch {
 66			case c.IsRename():
 67				filesToDelete = append(filesToDelete, c.OldPath)
 68				src := filepath.Join(sourceRoot, c.Path)
 69				if fileExists(src) {
 70					filesToCopy = append(filesToCopy, c.Path)
 71				}
 72			case fileExists(filepath.Join(sourceRoot, c.Path)):
 73				filesToCopy = append(filesToCopy, c.Path)
 74			default:
 75				filesToDelete = append(filesToDelete, c.Path)
 76			}
 77		}
 78	
 79		totalCount := len(filesToCopy) + len(filesToDelete)
 80		if totalCount == 0 {
 81			return fmt.Errorf("no files to move")
 82		}
 83	
 84		// Resolve target worktree
 85		targetPath, createdNew, err := resolveOrCreateTarget(ctx, targetName)
 86		if err != nil {
 87			return err
 88		}
 89	
 90		// Prevent moving to self
 91		if sourceRoot == targetPath {
 92			return fmt.Errorf("can't move changes to the same worktree\n   Specify a different worktree: wt move <name>")
 93		}
 94	
 95		targetShort := ctx.shortName(targetPath)
 96	
 97		// Safety: check for conflicting changes in destination
 98		destChanges, err := git.StatusPorcelainIn(targetPath)
 99		if err != nil {
100			return fmt.Errorf("failed to check destination for conflicts: %w", err)
101		}
102		if len(destChanges) > 0 {
103			var destFiles []string
104			for _, dc := range destChanges {
105				destFiles = append(destFiles, dc.Path)
106			}
107	
108			var conflicts []string
109			allFiles := make([]string, 0, len(filesToCopy)+len(filesToDelete))
110			allFiles = append(allFiles, filesToCopy...)
111			allFiles = append(allFiles, filesToDelete...)
112			for _, f := range allFiles {
113				for _, df := range destFiles {
114					if f == df {
115						conflicts = append(conflicts, f)
116					}
117				}
118			}
119	
120			if len(conflicts) > 0 {
121				ui.Warn("Destination has its own changes to %d file(s):", len(conflicts))
122				for _, f := range conflicts {
123					fmt.Printf("   • %s\n", f)
124				}
125				fmt.Println()
126				if ok, err := ui.ConfirmDiscard("Overwrite?", moveForceFlag); !ok {
127					return cancelled(err)
128				}
129				fmt.Println()
130			}
131		}
132	
133		// Move files
134		fmt.Printf("Moving %d file(s) → %s\n", totalCount, targetShort)
135	
136		var copied, deleted, errors int
137	
138		for _, file := range filesToCopy {
139			destDir := filepath.Dir(filepath.Join(targetPath, file))
140			if err := os.MkdirAll(destDir, 0755); err != nil {
141				return fmt.Errorf("failed to create directory %s: %w", destDir, err)
142			}
143	
144			if err := copyFile(filepath.Join(sourceRoot, file), filepath.Join(targetPath, file)); err != nil {
145				fmt.Printf("  %s Failed to copy: %s\n", ui.Red(ui.Fail), file)
146				errors++
147			} else {
148				copied++
149			}
150		}
151	
152		for _, file := range filesToDelete {
153			dest := filepath.Join(targetPath, file)
154			if fileExists(dest) {
155				if err := os.Remove(dest); err != nil {
156					fmt.Printf("  %s Failed to delete: %s\n", ui.Red(ui.Fail), file)
157					errors++
158				} else {
159					deleted++
160				}
161			}
162		}
163	
164		// Clean up source worktree
165		if errors == 0 {
166			_ = git.RunSilentIn(sourceRoot, "reset", ".")
167			if err := git.RunSilentIn(sourceRoot, "checkout", "."); err != nil {
168				ui.Warn("Could not restore source worktree: %v", err)
169			}
170			if err := git.RunSilentIn(sourceRoot, "clean", "-fd"); err != nil {
171				ui.Warn("Could not clean source untracked files: %v", err)
172			}
173		}
174	
175		// Summary
176		fmt.Println()
177		if errors == 0 {
178			ui.Success("Moved %d change(s) to %s", copied+deleted, targetShort)
179		} else {
180			ui.Warn("Done with %d error(s) — source worktree not cleaned up", errors)
181		}
182	
183		fmt.Println()
184		fmt.Println("To continue working there:")
185		fmt.Printf("  %s\n", ui.Cyan("wt switch "+targetName))
186		if createdNew {
187			fmt.Println("  wt init    # run init commands from .wt.toml")
188		}
189		return nil
190	}
