192	func resolveOrCreateTarget(ctx *cmdContext, name string) (string, bool, error) {
193		worktrees, err := git.ListWorktrees()
194		if err != nil {
195			return "", false, err
196		}
197	
198		// Try to resolve existing worktree
199		target, fuzzy, resolveErr := resolveWorktree(ctx, worktrees, name)
200		if resolveErr != nil {
201			return "", false, resolveErr
202		}
203		if target != "" {
204			if fuzzy {
205				if !ui.Confirm(fmt.Sprintf("Move changes into %s?", ctx.shortName(target)), false) {
206					fmt.Println("Cancelled")
207					return "", false, errSilent
208				}
209			}
210			return target, false, nil
211		}
212	
213		// Not found — offer to create
214		branch := ctx.branchName(name)
215		wtPath := ctx.worktreePath(name)
216	
217		fmt.Printf("No worktree '%s' found.\n", name)
218		fmt.Printf("  Branch: %s\n", branch)
219		fmt.Printf("  Path:   %s\n", wtPath)
220		if !ui.Confirm("Create new worktree?", false) {
221			fmt.Println("Cancelled")
222			return "", false, errSilent
223		}
224		fmt.Println()
225	
226		if isDir(wtPath) {
227			return "", false, fmt.Errorf("directory already exists: %s", wtPath)
228		}
229		if git.BranchExists(branch) {
230			return "", false, fmt.Errorf("branch already exists: %s\n   Use 'wt new --from %s' first, then 'wt move' to it", branch, branch)
231		}
232	
233		if err := git.Fetch(ctx.Config.Remote, ctx.Config.BaseBranch); err != nil {
234			ui.Warn("Fetch failed: %v", err)
235		}
236	
237		if err := git.AddWorktree(wtPath, branch, ctx.baseRef()); err != nil {
238			return "", false, fmt.Errorf("failed to create worktree: %w", err)
239		}
240	
241		ui.Success("Created worktree")
242		fmt.Printf("  Path: %s\n", wtPath)
243		fmt.Printf("  Branch: %s (from %s)\n", branch, ctx.Config.BaseBranch)
244		fmt.Println()
245	
246		return wtPath, true, nil
247	}
248	
249	func copyFile(src, dst string) error {
250		info, err := os.Stat(src)
251		if err != nil {
252			return err
253		}
254		if info.IsDir() {
255			return fmt.Errorf("cannot copy directory: %s", src)
256		}
257	
258		in, err := os.Open(src)
259		if err != nil {
260			return err
261		}
262		defer in.Close() //nolint:errcheck // best-effort close on read-only file
263	
264		out, err := os.OpenFile(dst, os.O_CREATE|os.O_WRONLY|os.O_TRUNC, info.Mode())
265		if err != nil {
266			return err
267		}
268		defer out.Close() //nolint:errcheck // closed explicitly below on success
269	
270		if _, err = io.Copy(out, in); err != nil {
271			_ = out.Close()
272			_ = os.Remove(dst)
273			return err
274		}
275		return out.Sync()
276	}
