 14	var renameCmd = &cobra.Command{
 15		Use:     "rename <name>",
 16		Aliases: []string{"rn"},
 17		GroupID: groupManage,
 18		Short:   "Rename worktree, branch, and remote",
 19		Long: `Rename the current worktree's directory, branch, and remote branch to match conventions.
 20	
 21	Renames:
 22	  - Local branch: <old> → <prefix>/<name>
 23	  - Worktree directory: wt-<repo>/<old> → wt-<repo>/<name>
 24	  - Remote branch: origin/<old> → origin/<prefix>/<name> (recreates open PRs)`,
 25		Example: `  wt rename sidebar-v2    Rename branch, directory, and remote
 26	  wt rename fix --local   Rename locally only (skip remote)
 27	  wt rename fix --yes     Rename without confirmation prompt`,
 28		Args:              cobra.ExactArgs(1),
 29		ValidArgsFunction: completeWorktreeNames,
 30		RunE:              runRename,
 31	}
 32	
 33	var renameLocalOnly bool
 34	
 35	func init() {
 36		renameCmd.Flags().BoolVar(&renameLocalOnly, "local", false, "only rename locally (skip remote)")
 37		rootCmd.AddCommand(renameCmd)
 38	}
 39	
 40	func runRename(cmd *cobra.Command, args []string) error {
 41		ctx, err := newContext()
 42		if err != nil {
 43			return err
 44		}
 45	
 46		cwd, err := os.Getwd()
 47		if err != nil {
 48			return fmt.Errorf("cannot determine current directory: %w", err)
 49		}
 50		currentBranch, err := git.CurrentBranch()
 51		if err != nil {
 52			return fmt.Errorf("not in a git repository or detached HEAD\n   Run this from inside a worktree")
 53		}
 54	
 55		// Safety: must be in a worktree, not main repo
 56		if cwd == ctx.MainWorktree || isSubpath(cwd, ctx.MainWorktree) {
 57			return fmt.Errorf("cannot rename the main repository\n   Switch to a worktree first: wt switch <name>")
 58		}
 59		if ctx.isBaseBranch(currentBranch) {
 60			return fmt.Errorf("cannot rename the base branch (%s)\n   Switch to a feature worktree first", currentBranch)
 61		}
 62	
 63		newName := args[0]
 64	
 65		// Strip prefix if user accidentally includes it
 66		var prefix string
 67		if ctx.Config.BranchPrefix != nil {
 68			prefix = *ctx.Config.BranchPrefix
 69		} else {
 70			prefix = ctx.Username
 71		}
 72		if prefix != "" {
 73			newName = strings.TrimPrefix(newName, prefix+"/")
 74		}
 75	
 76		newBranch := ctx.branchName(newName)
 77		newPath := ctx.worktreePath(newName)
 78	
 79		// Already correct?
 80		if currentBranch == newBranch && cwd == newPath {
 81			ui.Success("Already named correctly")
 82			return nil
 83		}
 84	
 85		// Check collisions
 86		if currentBranch != newBranch && git.BranchExists(newBranch) {
 87			return fmt.Errorf("branch already exists: %s", newBranch)
 88		}
 89		if cwd != newPath && isDir(newPath) {
 90			return fmt.Errorf("directory already exists: %s", newPath)
 91		}
 92	
 93		// Check remote and PR
 94		hasRemote := false
 95		var prDetails *github.PRDetails
 96	
 97		if !renameLocalOnly {
 98			if git.RemoteBranchExists(ctx.Config.Remote + "/" + currentBranch) {
 99				hasRemote = true
100				prDetails, err = github.GetPRDetails(currentBranch)
101				if err != nil {
102					ui.Warn("Could not fetch PR details: %v", err)
103				}
104			}
105		}
106	
107		// Preview
108		fmt.Println("Rename plan:")
109		if currentBranch != newBranch {
110			fmt.Printf("  Branch:    %s → %s\n", currentBranch, newBranch)
111		} else {
112			fmt.Printf("  Branch:    %s\n", ui.Dim(currentBranch+" (no change)"))
113		}
114	
115		currentShort := ctx.shortName(cwd)
116		if cwd != newPath {
117			fmt.Printf("  Directory: %s → %s\n", currentShort, ctx.worktreeDir(newName))
118		} else {
119			fmt.Printf("  Directory: %s\n", ui.Dim(currentShort+" (no change)"))
120		}
121	
122		switch {
123		case renameLocalOnly:
124			fmt.Printf("  Remote:    %s\n", ui.Dim("(skipped, --local)"))
125		case hasRemote:
126			fmt.Printf("  Remote:    %s/%s → %s/%s\n", ctx.Config.Remote, currentBranch, ctx.Config.Remote, newBranch)
127			if prDetails != nil {
128				fmt.Printf("             └─ PR #%d will be recreated\n", prDetails.Number)
129			}
130		default:
131			fmt.Printf("  Remote:    %s\n", ui.Dim("(no remote branch)"))
132		}
133	
134		fmt.Println()
135		if !ui.Confirm("Proceed?", false) {
136			fmt.Println("Cancelled")
137			return nil
138		}
139		fmt.Println()
140	
141		// Step 1: Rename local branch
142		if currentBranch != newBranch {
143			fmt.Println("Renaming branch…")
144			if err := git.RenameBranch(currentBranch, newBranch); err != nil {
145				return fmt.Errorf("failed to rename branch: %w", err)
146			}
147		}
148	
149		// Step 2: Move worktree directory
150		if cwd != newPath {
151			fmt.Println("Moving worktree…")
152			if err := git.MoveWorktree(cwd, newPath); err != nil {
153				// Rollback branch rename
154				if currentBranch != newBranch {
155					fmt.Println("   Rolling back branch rename…")
156					if rbErr := git.RenameBranch(newBranch, currentBranch); rbErr != nil {
157						return fmt.Errorf("failed to move worktree: %w (rollback also failed: %v)", err, rbErr)
158					}
159				}
160				return fmt.Errorf("failed to move worktree: %w", err)
161			}
162			ui.PrintCdHint(newPath)
163		}
164	
165		// Step 3: Update remote branch
166		if hasRemote && !renameLocalOnly {
167			fmt.Println("Pushing new branch…")
168			if err := git.PushSetUpstream(ctx.Config.Remote); err != nil {
169				fmt.Println()
170				ui.Warn("Failed to push new branch")
171				fmt.Printf("   Local rename succeeded, but remote is still: %s/%s\n", ctx.Config.Remote, currentBranch)
172				fmt.Println("   To fix manually:")
173				fmt.Printf("   %s\n", ui.Cyan(fmt.Sprintf("git push -u %s HEAD && git push %s --delete %s", ctx.Config.Remote, ctx.Config.Remote, currentBranch)))
174			} else {
175				fmt.Println("Removing old remote branch…")
176				if err := git.DeleteRemoteBranch(ctx.Config.Remote, currentBranch); err != nil {
177					ui.Warn("Failed to delete old remote branch: " + currentBranch)
178					fmt.Printf("   Delete manually: %s\n", ui.Cyan(fmt.Sprintf("git push %s --delete %s", ctx.Config.Remote, currentBranch)))
179				}
180	
181				// Recreate PR if one existed
182				if prDetails != nil {
183					fmt.Println("Recreating PR…")
184					labels := make([]string, len(prDetails.Labels))
185					for i, l := range prDetails.Labels {
186						labels[i] = l.Name
187					}
188					url, err := github.CreatePR(newBranch, prDetails.BaseRefName, prDetails.Title, prDetails.Body, prDetails.IsDraft, labels)
189					if err != nil {
190						ui.Warn("Failed to recreate PR")
191						fmt.Printf("   Create manually: %s\n", ui.Cyan("gh pr create"))
192					} else {
193						fmt.Printf("   %s\n", url)
194					}
195				}
196			}
197		}
198	
199		fmt.Println()
200		ui.Success("Renamed!")
201	
202		newCtx, _ := newContext()
203		if newCtx != nil {
204			path := newPath
205			if cwd == newPath {
206				path = cwd
207			}
208			showSwitchSummary(path, newCtx)
209		}
210		return nil
211	}
