 41		ctx, err := newContext()
 42		if err != nil {
 43			return err
 44		}
 45	
 46		var branch string
 47	
 48		if len(args) == 0 {
 49			// Current branch
 50			branch, err = git.CurrentBranch()
 51			if err != nil {
 52				return fmt.Errorf("not in a git repository or detached HEAD\n   Run this from inside a worktree")
 53			}
 54		} else {
 55			// Resolve worktree by name
 56			worktrees, err := git.ListWorktrees()
 57			if err != nil {
 58				return err
 59			}
 60			target, _, resolveErr := resolveWorktree(ctx, worktrees, args[0])
 61			if resolveErr != nil {
