 35	func runEdit(cmd *cobra.Command, args []string) error {
 36		ctx, err := newContext()
 37		if err != nil {
 38			return err
 39		}
 40		if len(args) == 0 {
 41			top, err := git.TopLevel()
 42			if err != nil {
 43				return err
 44			}
 45			return openEditor(top)
 46		}
 47	
 48		worktrees, err := git.ListWorktrees()
 49		if err != nil {
 50			return err
 51		}
 52		path, _, err := resolveWorktree(ctx, worktrees, args[0])
 53		if err != nil {
 54			return err
 55		}
 56		if path == "" {
 57			return fmt.Errorf("worktree not found: %s\n   Run wt list to see available worktrees", args[0])
 58		}
 59		return openEditor(path)
