 61	
 62	// terminalEditors run in the foreground; anything else counts as a GUI editor.
 63	var terminalEditors = map[string]bool{
 64		"vi": true, "vim": true, "nvim": true, "hx": true, "helix": true,
 65		"nano": true, "emacs": true, "micro": true, "kak": true,
 66	}
 67	
 68	// resolveEditor picks the editor command line: $WT_EDITOR, $VISUAL, then the
 69	// first of cursor, code, zed on PATH.
 70	func resolveEditor(getenv func(string) string, lookPath func(string) (string, error)) (string, error) {
 71		for _, env := range []string{"WT_EDITOR", "VISUAL"} {
 72			if e := strings.TrimSpace(getenv(env)); e != "" {
 73				return e, nil
 74			}
 75		}
 76		for _, e := range []string{"cursor", "code", "zed"} {
 77			if _, err := lookPath(e); err == nil {
 78				return e, nil
 79			}
 80		}
 81		return "", fmt.Errorf("no editor found\n   Set $WT_EDITOR (e.g. export WT_EDITOR=code), or install cursor, code or zed")
 82	}
 83	
 84	func isTerminalEditor(editor string) bool {
 85		fields := strings.Fields(editor)
 86		return len(fields) > 0 && terminalEditors[filepath.Base(fields[0])]
 87	}
 88	
 89	// openEditor opens path in the user's editor.
 90	func openEditor(path string) error {
 91		editor, err := resolveEditor(os.Getenv, exec.LookPath)
 92		if err != nil {
 93			return err
 94		}
 95		// sh -c lets the editor setting carry flags, such as "code -n".
 96		c := exec.Command("sh", "-c", editor+` "$1"`, "sh", path)
 97		if isTerminalEditor(editor) {
 98			c.Dir = path
 99			c.Stdin, c.Stdout, c.Stderr = os.Stdin, os.Stdout, os.Stderr
100			return c.Run()
101		}
102		if err := c.Start(); err != nil {
103			return fmt.Errorf("failed to start %s: %w", editor, err)
104		}
105		fmt.Printf("Opened %s in %s\n", path, editor)
106		return nil
107	}

