340	func (m dashModel) Init() tea.Cmd {
341		return tea.Batch(tickCmd(), statusTickCmd(), m.dispatchDetail(false))
342	}
343	
344	// dispatchDetail returns a Cmd that fetches detail for the focused row.
345	// When force is false, fetches only if the row's detail isn't already cached.
346	// When force is true (refresh tick), fetches regardless — used to keep CI/etc.
347	// up to date while the cursor stays put. Returns nil if no fetch is needed
348	// (no callback, no focus, fetch already in flight).
349	func (m dashModel) dispatchDetail(force bool) tea.Cmd {
350		if m.fetchDetail == nil {
351			return nil
352		}
353		if m.cursor < 0 || m.cursor >= len(m.items) {
354			return nil
355		}
356		it := m.items[m.cursor]
357		if m.detailLoading[it.Path] {
358			return nil
359		}
360		if !force {
361			if _, cached := m.details[it.Path]; cached {
362				return nil
363			}
364		}
365		m.detailLoading[it.Path] = true
366		return fetchDetailCmd(m.fetchDetail, it)
367	}
