369	func (m dashModel) Update(msg tea.Msg) (tea.Model, tea.Cmd) {
370		switch msg := msg.(type) {
371		case tea.WindowSizeMsg:
372			m.width = msg.Width
373			m.height = msg.Height
374			return m, nil
375	
376		case tea.KeyPressMsg:
377			// Confirmation prompts intercept all keys.
378			if m.confirm != confirmNone {
379				return m.handleConfirmKey(msg.String())
380			}
381			m.flash = ""
382			// Any key closes the help overlay.
383			if m.showHelp {
384				m.showHelp = false
385				return m, nil
386			}
387	
388			// Global keys (work in any focus mode)
389			switch msg.String() {
390			case "ctrl+c", "q":
391				return m, tea.Quit
392			case "R":
393				return m.startRebaseAll()
394			case "?", "h":
395				m.showHelp = true
396				return m, nil
397			case "tab":
398				return m.toggleFocus()
399			case "esc":
400				// Zoom out one level. Levels (deepest first):
401				//   1. commits focused          → worktrees focused (cursor preserved)
402				//   2. worktrees, on a feature  → worktrees, cursor on the trunk
403				//   3. worktrees, on the trunk  → quit
404				// A few esc presses always exit the app no matter how deep you are.
405				if m.focus == focusCommits {
406					m.focus = focusWorktrees
407					m.commitCursor = 0
408					return m, nil
409				}
410				if m.cursor >= 0 && m.cursor < len(m.items) && !m.items[m.cursor].IsBase {
411					for i, it := range m.items {
412						if it.IsBase {
413							m.cursor = i
414							return m, m.dispatchDetail(false)
415						}
416					}
417				}
418				return m, tea.Quit
419			case "s":
420				// Switch to the highlighted worktree from anywhere — the worktree
421				// cursor (m.cursor) is preserved regardless of focus mode.
422				if m.cursor >= 0 && m.cursor < len(m.items) {
423					m.switchTo = m.items[m.cursor].Path
424					return m, tea.Quit
425				}
426				return m, nil
427			}
428	
429			// Pane-specific keys
430			if m.focus == focusCommits {
431				return m.handleCommitsKey(msg.String())
432			}
433			return m.handleWorktreesKey(msg.String())
434	
435		case tickMsg:
436			if m.refreshing {
437				// Already refreshing — just reschedule the next tick.
438				return m, tickCmd()
439			}
440			m.refreshing = true
441			return m, tea.Batch(refreshCmd(m.gather), tickCmd())
442	
443		case statusTickMsg:
444			// Reschedule only — View() will re-render the "updated Ns ago"
445			// counter using the current time.Since(m.lastRefresh).
446			return m, statusTickCmd()
447	
448		case refreshedMsg:
449			m.refreshing = false
450			if msg.err != nil {
451				m.lastErr = msg.err
452				return m, nil
453			}
454			m.items = msg.items
455			m.lastErr = nil
456			m.lastRefresh = time.Now()
457			if m.cursor >= len(m.items) {
458				m.cursor = max(0, len(m.items)-1)
459			}
460			// Refresh the focused row's detail too, so live state (CI/reviews/new
461			// commits) stays in sync at the same cadence as the main table.
462			return m, m.dispatchDetail(true)
463	
464		case detailLoadedMsg:
465			delete(m.detailLoading, msg.path)
466			m.details[msg.path] = &dashDetailCache{data: msg.data, err: msg.err}
467			// Clamp commit cursor if the refreshed commit list shrunk under our feet.
468			if m.cursor >= 0 && m.cursor < len(m.items) && msg.path == m.items[m.cursor].Path {
469				if n := len(msg.data.Commits); m.commitCursor >= n {
470					m.commitCursor = max(0, n-1)
471				}
472			}
473			// If commits are focused, kick off the commit-detail fetch for the
474			// currently-cursored commit (it may have changed).
475			return m, m.dispatchCommitDetail()
476	
477		case commitDetailLoadedMsg:
478			delete(m.commitDetailLoading, msg.hash)
479			m.commitDetails[msg.hash] = &dashCommitDetailCache{data: msg.data, err: msg.err}
480			return m, nil
481	
482		case dashRebaseDoneMsg:
483			st, ok := m.rebases[msg.path]
484			if !ok {
485				return m, nil
486			}
487			if msg.err != nil {
488				st.phase = "failed"
489				st.errMsg = msg.err.Error()
490				return m, nil
491			}
492			st.phase = "done"
493			st.commits = msg.commits
494			return m, tea.Tick(1500*time.Millisecond, func(time.Time) tea.Msg {
495				return dashRebaseCleanupMsg{path: msg.path}
496			})
497	
498		case dashRebaseCleanupMsg:
499			delete(m.rebases, msg.path)
500			if !m.refreshing {
501				m.refreshing = true
502				return m, refreshCmd(m.gather)
503			}
504			return m, nil
505	
506		case dashCloseDoneMsg:
507			st, ok := m.closes[msg.path]
508			if !ok {
509				return m, nil
510			}
511			if msg.err != nil {
512				st.phase = "failed"
513				st.errMsg = msg.err.Error()
514				return m, nil
515			}
516			st.phase = "done"
517			// Hold the "✓ closed" indicator briefly, then drop it and refresh —
518			// the next gather will remove the row from items.
519			return m, tea.Tick(1500*time.Millisecond, func(time.Time) tea.Msg {
520				return dashCloseCleanupMsg{path: msg.path}
521			})
522	
523		case dashCloseCleanupMsg:
524			delete(m.closes, msg.path)
525			if !m.refreshing {
526				m.refreshing = true
527				return m, refreshCmd(m.gather)
528			}
529			return m, nil
530		}
531	
532		return m, nil
533	}
