535	// handleWorktreesKey processes keys when the worktree list owns focus.
536	// Enter zooms into the commits pane (same as Tab); use `s` to switch
537	// to the highlighted worktree.
538	func (m dashModel) handleWorktreesKey(key string) (tea.Model, tea.Cmd) {
539		switch key {
540		case "up", "k":
541			if m.cursor > 0 {
542				m.cursor--
543				return m, m.dispatchDetail(false)
544			}
545		case "down", "j":
546			if m.cursor < len(m.items)-1 {
547				m.cursor++
548				return m, m.dispatchDetail(false)
549			}
550		case "g", "home":
551			m.cursor = 0
552			return m, m.dispatchDetail(false)
553		case "G", "end":
554			m.cursor = max(0, len(m.items)-1)
555			return m, m.dispatchDetail(false)
556		case "c":
557			return m.startClose()
558		case "r":
559			return m.startRebase()
560		case "enter":
561			// Zoom in: focus the commits pane (no-op if there are no commits yet).
562			return m.toggleFocus()
563		}
564		return m, nil
565	}
566	
567	// handleCommitsKey processes keys when the commits list owns focus.
568	// j/k navigate within the commits; the third panel below auto-follows the
569	// cursor to show full detail for whichever commit is selected.
570	func (m dashModel) handleCommitsKey(key string) (tea.Model, tea.Cmd) {
571		commits := m.focusedCommits()
572		switch key {
573		case "up", "k":
574			if m.commitCursor > 0 {
575				m.commitCursor--
576				return m, m.dispatchCommitDetail()
577			}
578		case "down", "j":
579			if m.commitCursor < len(commits)-1 {
580				m.commitCursor++
581				return m, m.dispatchCommitDetail()
582			}
583		case "g", "home":
584			m.commitCursor = 0
585			return m, m.dispatchCommitDetail()
586		case "G", "end":
587			m.commitCursor = max(0, len(commits)-1)
588			return m, m.dispatchCommitDetail()
589		}
590		return m, nil
591	}
592	
593	// toggleFocus swaps focus between the worktree list and the commits list.
594	// No-ops if there's nothing to focus into (no commits cached for the
595	// currently-selected worktree yet). When entering commits focus, dispatches
596	// a fetch so the soon-to-be-visible commit-detail panel can render.
597	func (m dashModel) toggleFocus() (tea.Model, tea.Cmd) {
598		if m.focus == focusWorktrees {
599			if len(m.focusedCommits()) == 0 {
600				m.flash = "no commits on this branch yet"
601				if m.cursor >= 0 && m.cursor < len(m.items) && m.detailLoading[m.items[m.cursor].Path] {
602					m.flash = "commits still loading…"
603				}
604				return m, nil
605			}
606			m.focus = focusCommits
607			m.commitCursor = 0
608			return m, m.dispatchCommitDetail()
609		}
610		m.focus = focusWorktrees
611		m.commitCursor = 0
612		return m, nil
613	}
614	
615	// dispatchCommitDetail returns a Cmd that fetches detail for the commit under
616	// the commit cursor, or nil if no fetch is needed. Mirrors dispatchDetail's
617	// cache + loading guards. Commit data is immutable, so the cache never expires.
618	func (m dashModel) dispatchCommitDetail() tea.Cmd {
619		if m.fetchCommitDetail == nil {
620			return nil
621		}
622		if m.focus != focusCommits {
623			return nil
624		}
625		commits := m.focusedCommits()
626		if m.commitCursor < 0 || m.commitCursor >= len(commits) {
627			return nil
628		}
629		if m.cursor < 0 || m.cursor >= len(m.items) {
630			return nil
631		}
632		hash := commits[m.commitCursor].Hash
633		if m.commitDetailLoading[hash] {
634			return nil
635		}
636		if _, cached := m.commitDetails[hash]; cached {
637			return nil
638		}
639		m.commitDetailLoading[hash] = true
640		return fetchCommitDetailCmd(m.fetchCommitDetail, m.items[m.cursor].Path, hash)
641	}
642	
643	// focusedCommits returns the commit list for the worktree the cursor is on,
644	// or nil if none is cached / fetched / available.
645	func (m dashModel) focusedCommits() []DashCommit {
646		if m.cursor < 0 || m.cursor >= len(m.items) {
647			return nil
648		}
649		cache, ok := m.details[m.items[m.cursor].Path]
650		if !ok || cache.err != nil {
651			return nil
652		}
653		return cache.data.Commits
654	}
655	
656	// rowBusy reports whether a worktree has any async operation pending — close
657	// or rebase in any phase (running, done-pending-cleanup, or failed). While
658	// busy, the row's tail cell is displaying state for that operation and
659	// starting another would either clobber the display or hit a real git
660	// conflict. All per-row action entry points consult this.
661	func (m dashModel) rowBusy(path string) bool {
662		if _, ok := m.closes[path]; ok {
663			return true
664		}
665		if _, ok := m.rebases[path]; ok {
666			return true
667		}
668		return false
669	}
