671	// handleConfirmKey intercepts keys while a confirmation prompt is active.
672	// y/enter confirms; n/esc/any-other-key cancels.
673	func (m dashModel) handleConfirmKey(key string) (tea.Model, tea.Cmd) {
674		switch key {
675		case "y", "Y", "enter":
676			kind := m.confirm
677			m.confirm = confirmNone
678			switch kind {
679			case confirmRebaseAll:
680				return m.executeRebaseAll()
681			case confirmClose:
682				return m.executeConfirmedClose()
683			}
684			return m, nil
685		default:
686			// Cancel: clear the prompt and any close-target state we may have set
687			// when entering it.
688			m.confirm = confirmNone
689			m.confirmCloseTarget = ""
690			m.confirmCloseName = ""
691			m.confirmCloseBranch = ""
692			m.confirmCloseRisks = nil
693			return m, nil
694		}
695	}
