697	// startRebase queues an async sync for the highlighted worktree. For feature
698	// branches this is a rebase onto the base branch; for the base-branch row it's
699	// a fast-forward from the remote. No-ops when the row is busy or there's no
700	// rebase callback.
701	func (m dashModel) startRebase() (tea.Model, tea.Cmd) {
702		if m.rebase == nil {
703			return m, nil
704		}
705		if m.cursor < 0 || m.cursor >= len(m.items) {
706			return m, nil
707		}
708		it := m.items[m.cursor]
709		if m.rowBusy(it.Path) {
710			return m, nil
711		}
712		m.rebases[it.Path] = &dashRebaseState{phase: "running", isBase: it.IsBase}
713		return m, dashRebaseCmd(m.rebase, it.Path, it.Branch)
714	}
