716	// startRebaseAll triggers the confirmation prompt for bulk rebase. Actual
717	// dispatch happens in executeRebaseAll after the user answers y/enter.
718	func (m dashModel) startRebaseAll() (tea.Model, tea.Cmd) {
719		if m.rebase == nil {
720			return m, nil
721		}
722		// Count eligible worktrees to give the user concrete numbers.
723		if m.countRebaseTargets() == 0 {
724			return m, nil
725		}
726		m.confirm = confirmRebaseAll
727		return m, nil
