730	// executeRebaseAll dispatches a rebase for every non-base worktree concurrently.
731	// Each rebase runs in its own goroutine via dashRebaseCmd; results arrive as
732	// dashRebaseDoneMsg and are rendered per-row.
733	func (m dashModel) executeRebaseAll() (tea.Model, tea.Cmd) {
734		var cmds []tea.Cmd
735		for _, it := range m.items {
736			if it.IsBase {
737				continue
738			}
739			if m.rowBusy(it.Path) {
740				continue
741			}
742			m.rebases[it.Path] = &dashRebaseState{phase: "running"}
743			cmds = append(cmds, dashRebaseCmd(m.rebase, it.Path, it.Branch))
744		}
745		if len(cmds) == 0 {
746			return m, nil
747		}
748		return m, tea.Batch(cmds...)
749	}
