828	// canClose reports whether a row is eligible to be closed from the dashboard.
829	// Refuses the base branch (you can't remove it) and the current worktree
830	// (closing the dashboard's own cwd would tear out the ground beneath us).
831	// Everything else is fair game; risky rows get a confirmation via closeRisks.
832	func canClose(it DashItem) bool {
833		if it.IsBase || it.IsCurrent {
834			return false
835		}
836		return true
837	}
