535	// handleWorktreesKey processes keys when the worktree list owns focus.
536	// Enter zooms into the commits pane (same as Tab); use `s` to switch
537	// to the highlighted worktree.
538	func (m dashModel) handleWorktreesKey(key string) (tea.Model, tea.Cmd) {
539		switch key {
540		case "up", "k":
541			if m.cursor > 0 {
542				m.cursor--
543				return m, m.dispatchDetail(false)
544			}
545		case "down", "j":
546			if m.cursor < len(m.items)-1 {
547				m.cursor++
548				return m, m.dispatchDetail(false)
549			}
550		case "g", "home":
551			m.cursor = 0
552			return m, m.dispatchDetail(false)
553		case "G", "end":
554			m.cursor = max(0, len(m.items)-1)
555			return m, m.dispatchDetail(false)
556		case "c":
557			return m.startClose()
558		case "r":
559			return m.startRebase()
560		case "enter":
