775	// No-ops when the row isn't closeable (base branch, current worktree, already
776	// closing). Multiple concurrent closes are supported.
777	func (m dashModel) startClose() (tea.Model, tea.Cmd) {
778		if m.close == nil {
779			return m, nil
780		}
781		if m.cursor < 0 || m.cursor >= len(m.items) {
782			return m, nil
783		}
784		it := m.items[m.cursor]
785		if !canClose(it) {
786			return m, nil
787		}
788		if m.rowBusy(it.Path) {
789			return m, nil
790		}
791	
792		risks := closeRisks(it)
793		if len(risks) == 0 {
794			// Safe: just do it.
795			m.closes[it.Path] = &dashCloseState{phase: "closing"}
796			return m, dashCloseCmd(m.close, it.Path, it.Branch)
797		}
798	
799		// Risky: show confirmation prompt at the footer. Store the target so
800		// handleConfirmKey can dispatch it on y/enter.
801		m.confirm = confirmClose
802		m.confirmCloseTarget = it.Path
803		m.confirmCloseName = it.ShortName
804		m.confirmCloseBranch = it.Branch
805		m.confirmCloseRisks = risks
806		return m, nil
807	}
