809	// executeConfirmedClose dispatches the close that was waiting on confirmation.
810	// Called from handleConfirmKey after the user answers y/enter.
811	func (m dashModel) executeConfirmedClose() (tea.Model, tea.Cmd) {
812		path := m.confirmCloseTarget
813		branch := m.confirmCloseBranch
814		m.confirmCloseTarget = ""
815		m.confirmCloseName = ""
816		m.confirmCloseBranch = ""
817		m.confirmCloseRisks = nil
818		if path == "" || m.close == nil {
819			return m, nil
820		}
821		if m.rowBusy(path) {
822			return m, nil
823		}
824		m.closes[path] = &dashCloseState{phase: "closing"}
825		return m, dashCloseCmd(m.close, path, branch)
826	}
