828	// canClose reports whether a row is eligible to be closed from the dashboard.
829	// Refuses the base branch (you can't remove it) and the current worktree
830	// (closing the dashboard's own cwd would tear out the ground beneath us).
831	// Everything else is fair game; risky rows get a confirmation via closeRisks.
832	func canClose(it DashItem) bool {
833		if it.IsBase || it.IsCurrent {
834			return false
835		}
836		return true
837	}
838	
839	// closeRisks returns human-readable reasons a worktree is risky to close.
840	// Empty slice means safe (proceed without confirmation). Order is stable
841	// (dirty → unpushed → PR state) so the prompt reads consistently.
842	func closeRisks(it DashItem) []string {
843		var risks []string
844		if it.DirtyCount > 0 {
845			risks = append(risks, fmt.Sprintf("%d uncommitted change%s", it.DirtyCount, plural(it.DirtyCount)))
846		}
847		if it.Unpushed > 0 {
848			risks = append(risks, fmt.Sprintf("%d unpushed commit%s", it.Unpushed, plural(it.Unpushed)))
849		}
850		if it.PR != nil && it.PR.State == "open" {
851			risks = append(risks, fmt.Sprintf("PR #%d still open", it.PR.Number))
852		}
853		return risks
854	}
