1711	// fitCommitPanel trims the commit body, then the file list, to fit room lines.
1712	// Each non-empty section also costs one blank separator line.
1713	func fitCommitPanel(body, files []string, room int) ([]string, []string) {
1714		cost := func(s []string) int {
1715			if len(s) == 0 {
1716				return 0
1717			}
1718			return len(s) + 1
1719		}
1720		if cost(body)+cost(files) <= room {
1721			return body, files
1722		}
1723		if keep := room - cost(files) - 1; keep >= 1 && len(body) > 0 {
1724			body = slices.Clone(body[:keep])
1725			body[keep-1] += dStyleDim.Render(" …")
1726			return body, files
1727		}
1728		if cost(files) <= room {
1729			return nil, files
1730		}
1731		if keep := room - 2; keep >= 0 { // blank + "+N more" line
1732			more := dStyleDim.Render(fmt.Sprintf("+%d more", len(files)-keep))
1733			return nil, append(slices.Clone(files[:keep]), more)
1734		}
1735		return nil, nil
1736	}
