1803	// wrapText word-wraps a string to lines no wider than `width`, preserving
1804	// paragraph breaks (double newlines become an empty line).
1805	func wrapText(s string, width int) []string {
1806		if width <= 0 {
1807			return []string{s}
1808		}
1809		var out []string
1810		for paragraph := range strings.SplitSeq(s, "\n") {
1811			if paragraph == "" {
1812				out = append(out, "")
1813				continue
1814			}
1815			var line string
1816			for word := range strings.FieldsSeq(paragraph) {
1817				if line == "" {
1818					line = word
1819					continue
1820				}
1821				if lipgloss.Width(line)+1+lipgloss.Width(word) > width {
1822					out = append(out, line)
1823					line = word
1824					continue
1825				}
1826				line += " " + word
1827			}
1828			if line != "" {
