1933			}
1934			return w + "s"
1935		}
1936		num := func(v int) string { return dStyleBold.Render(fmt.Sprintf("%d", v)) }
1937		yellowNum := func(v int) string { return dStyleYellow.Render(fmt.Sprintf("%d", v)) }
