1944			// present — the units are obvious in context.
1945			parts = append(parts,
1946				num(s.Commits)+" "+dStyleDim.Render("ahead")+", "+
1947					yellowNum(behind)+" "+dStyleDim.Render("behind"),
1948			)
1949		case s.Commits > 0:
1950			parts = append(parts,
1951				num(s.Commits)+" "+dStyleDim.Render(unit(s.Commits, "commit")+" ahead"),
1952			)
1953		case behind > 0:
1954			parts = append(parts,
