2039	// renderRebaseCell renders the ephemeral rebase state that replaces the
2040	// [pr][review][ci] columns while a rebase is in flight or recently completed.
2041	// Base-branch rows use "syncing"/"synced" wording since the operation is a
2042	// fast-forward from the remote, not a rebase.
2043	func renderRebaseCell(r *dashRebaseState, width int) string {
2044		running := "rebasing…"
