2106	// buildStatusCell collapses PR + review + CI into one short cell for the
2107	// narrow layout. The single most important signal wins: failing CI/changes
2108	// requested beat pending which beats approved which beats "open". A worktree
2109	// with no PR renders the same em-dash placeholder as the wide layout's PR
2110	// column so the table stays consistent.
2111	func buildStatusCell(it DashItem) string {
2112		if it.IsBase || it.PR == nil {
