2138	func buildPRCells(it DashItem) (pr, review, ci string) {
2139		if it.IsBase {
2140			return dStyleDim.Render("—"), "", ""
2141		}
2142		if it.PR == nil {
2143			return dStyleDim.Render("—"), "", ""
2144		}
2145		pr = dStyleBlue.Render(fmt.Sprintf("#%d", it.PR.Number))
2146		switch it.PR.State {
2147		case "merged":
