2149			ci = dStyleYellow.Render("stale")
2150			return
2151		case "closed":
2152			review = dStyleRed.Render("closed")
2153			ci = dStyleYellow.Render("stale")
2154			return
2155		}
2156	
2157		review = buildReviewGlyphs(it.PR.Review)
2158		ci = buildCIGlyphs(it.PR.CI, it.Unpushed)
