2166		}
2167		if r.Changes > 0 {
2168			parts = append(parts, dStyleRed.Render(strings.Repeat("✗", r.Changes)))
2169		}
2170		if r.Pending > 0 {
2171			parts = append(parts, dStyleBlue.Render(strings.Repeat("◐", r.Pending)))
2172		}
2173		if len(parts) == 0 {
2174			return dStyleDim.Render("○")
