2179	func buildCIGlyphs(c DashCI, unpushed int) string {
2180		if c.Total == 0 {
2181			return dStyleDim.Render("○")
2182		}
2183		style := dStyleGreen
2184		switch {
2185		case c.Fail > 0:
2186			style = dStyleRed
2187		case c.Pending > 0:
2188			style = dStyleYellow
2189		}
2190		s := style.Render(ui.CISummary(c.Pass, c.Fail, c.Pending, c.Total))
