2197	// padAnsi pads an ANSI-containing string to a visible width.
2198	func padAnsi(s string, width int) string {
2199		w := lipgloss.Width(s)
2200		if w >= width {
2201			return s
2202		}
2203		return s + strings.Repeat(" ", width-w)
