2206	func truncate(s string, max int) string {
2207		if max <= 0 {
2208			return ""
2209		}
2210		runes := []rune(s)
2211		if len(runes) <= max {
2212			return s
2213		}
2214		if max == 1 {
2215			return "…"
2216		}
2217		return string(runes[:max-1]) + "…"
2218	}

