	common := t.TempDir()
	mk := func(id string) string {
		d := filepath.Join(common, "worktrees", id)
		if err := os.MkdirAll(d, 0755); err != nil {
			t.Fatal(err)
		}
		return d
	}
	get := func(gitDir string) int {
		n, err := worktreeIndex(gitDir)
		if err != nil {
			t.Fatal(err)
		}
		return n
