		t.Fatalf("first indexes = %d, %d, want 1, 2", get(a), get(b))
	}
	if get(a) != 1 {
		t.Error("index is not stable")
	}
	// Closing a frees its number for the next worktree.
	if err := os.RemoveAll(a); err != nil {
		t.Fatal(err)
	}
	if n := get(c); n != 1 {
		t.Errorf("index after free = %d, want 1", n)
